window.MT_DATA['pl'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Pologne, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Nouveau à Mokotów","phrases":[{"fr":"Bonjour, je suis le nouveau voisin du troisième.","tgt":"Dzień dobry, jestem nowym sąsiadem z trzeciego piętra.","lit":"jour · bon · je-suis · nouveau · voisin [instrumental] · de · troisième · étage [génitif]"},{"fr":"J'habite à Mokotów, près du parc.","tgt":"Mieszkam na Mokotowie, blisko parku.","lit":"j'habite · sur · Mokotów [locatif] · près · parc [génitif]"},{"fr":"Je travaille dans le centre de Varsovie.","tgt":"Pracuję w centrum Warszawy.","lit":"je-travaille · dans · centre · Varsovie [génitif]"},{"fr":"Je suis français, originaire de Lyon.","tgt":"Jestem Francuzem, pochodzę z Lyonu.","lit":"je-suis · Français [instrumental] · je-viens · de · Lyon [génitif]"},{"fr":"Je parle un tout petit peu polonais.","tgt":"Mówię troszkę po polsku.","lit":"je-parle · un-tout-petit-peu · à-la · polonaise"},{"fr":"J'apprends le polonais dans le tramway.","tgt":"Uczę się polskiego w tramwaju.","lit":"j'apprends · [se] · polonais [génitif] · dans · tramway"},{"fr":"Mon prénom, c'est Marc.","tgt":"Mam na imię Marc.","lit":"j'ai · pour · prénom · Marc"},{"fr":"Je suis content d'être ici.","tgt":"Cieszę się, że tu jestem.","lit":"je-me-réjouis · [se] · que · ici · je-suis"},{"fr":"Je suis fatigué, mais très content.","tgt":"Jestem zmęczony, ale bardzo zadowolony.","lit":"je-suis · fatigué · mais · très · content"},{"fr":"Je bois un café et je pars au bureau.","tgt":"Piję kawę i idę do biura.","lit":"je-bois · café [acc.] · et · je-vais · vers · bureau [génitif]"}],"tip":{"title":"Le verbe porte le sujet : « jestem », je suis, sans « ja »","example":"Je suis fatigué, mais très content. — <b>Jestem</b> zmęczony, ale bardzo zadowolony.","body":"En français, on dit toujours « je » devant le verbe. En polonais, c'est inutile : la fin du verbe dit déjà qui parle. « Jestem » veut dire à lui seul « je suis », et « mieszkam », « j'habite ». Le petit mot « ja », qui signifie « moi, je », existe bien, mais on ne l'ajoute que pour insister, un peu comme quand on dit « moi, je ». Décomposons « Pracuję w centrum » : « pracuję », je travaille, « w », dans, « centrum », le centre. Trois mots, et le sujet est caché dans la terminaison du verbe. Écoutez aussi « piję kawę », je bois un café, et « mówię po polsku », je parle polonais. Astuce : quand vous parlez de vous, commencez directement par le verbe, sans chercher le « je ».","lit":"je-suis · fatigué · mais · très · content"}},{"title":"La boulangerie du coin","phrases":[{"fr":"Bonjour, une baguette, s'il vous plaît.","tgt":"Dzień dobry, poproszę bagietkę.","lit":"jour · bon · je-demande · baguette [acc.]"},{"fr":"Ce pain est encore chaud.","tgt":"Ten chleb jest jeszcze ciepły.","lit":"ce · pain · est · encore · chaud"},{"fr":"Je voudrais aussi deux petits pains.","tgt":"Poproszę jeszcze dwie bułki.","lit":"je-demande · encore · deux · petits-pains"},{"fr":"Combien je vous dois pour tout ça ?","tgt":"Ile płacę za wszystko?","lit":"combien · je-paie · pour · tout"},{"fr":"Cinq złotys, s'il vous plaît.","tgt":"Pięć złotych, proszę.","lit":"cinq · złotys [génitif] · je-vous-prie"},{"fr":"Il y a des beignets aujourd'hui ?","tgt":"Czy są dziś pączki?","lit":"[question] · sont · aujourd'hui · beignets"},{"fr":"Oui, à la confiture de rose, tout frais.","tgt":"Tak, z różą, świeżutkie.","lit":"oui · avec · rose [instrumental] · tout-frais"},{"fr":"Cette dame est vraiment gentille.","tgt":"Ta pani jest naprawdę miła.","lit":"cette · dame · est · vraiment · gentille"},{"fr":"Je passe ici tous les matins.","tgt":"Przychodzę tu codziennie rano.","lit":"je-viens · ici · chaque-jour · le-matin"},{"fr":"Merci, bonne journée !","tgt":"Dziękuję, miłego dnia!","lit":"je-remercie · agréable · jour [génitif]"}],"tip":{"title":"L'accent tonique toujours sur l'avant-dernière syllabe","example":"Merci, bonne journée ! — <b>Dziękuję</b>, miłego dnia!","body":"Bonne nouvelle : en polonais, l'accent tombe presque toujours sur l'avant-dernière syllabe du mot. En français, on appuie plutôt sur la fin du mot, alors il faut changer d'habitude. Prenez « dziękuję », merci : on le découpe en « dzię », « ku », « ję », et on appuie sur « ku ». De même, « poproszę », je voudrais, se dit avec la force sur « pro ». Et dans « bagietka », la baguette, on insiste sur « giet ». Quand le mot s'allonge, l'accent se déplace pour rester à l'avant-dernière place. Astuce : comptez les syllabes à partir de la fin, une, deux, et frappez la deuxième. Votre polonais sonnera tout de suite plus naturel.","lit":"je-remercie · agréable · jour [génitif]"}},{"title":"Bonjour aux voisins","phrases":[{"fr":"Bonjour, monsieur !","tgt":"Dzień dobry panu!","lit":"jour · bon · [à] monsieur [datif]"},{"fr":"Salut, Kasia !","tgt":"Cześć, Kasiu!","lit":"salut · Kasia [vocatif]"},{"fr":"Bonsoir à tous les voisins !","tgt":"Dobry wieczór wszystkim sąsiadom!","lit":"bon · soir · à-tous · voisins [datif]"},{"fr":"Quoi de neuf, Tomek ?","tgt":"Co słychać, Tomku?","lit":"quoi · s'entend · Tomek [vocatif]"},{"fr":"Bien, merci, et vous ?","tgt":"Dobrze, dziękuję, a pan?","lit":"bien · je-remercie · et · monsieur"},{"fr":"Je descends au marché.","tgt":"Idę na targ.","lit":"je-vais · sur · marché [acc.]"},{"fr":"Au revoir, à demain !","tgt":"Do widzenia, do jutra!","lit":"jusqu'à · revoir · jusqu'à · demain"},{"fr":"Salut, à plus tard !","tgt":"Cześć, na razie!","lit":"salut · pour · l'instant"},{"fr":"Bonne nuit, les enfants !","tgt":"Dobranoc, dzieci!","lit":"bonne-nuit · enfants"},{"fr":"Le voisin dit toujours bonjour.","tgt":"Sąsiad zawsze mówi „dzień dobry”.","lit":"voisin · toujours · dit · jour · bon"}],"tip":{"title":"Saluer : « dzień dobry », « cześć », « do widzenia »","example":"Au revoir, à demain ! — <b>Do widzenia</b>, do jutra!","body":"Pour saluer en polonais, il faut d'abord choisir entre le poli et le familier. « Dzień dobry », mot à mot « jour bon », c'est le bonjour poli, valable du matin jusqu'à la fin de l'après-midi. Le soir, on passe à « dobry wieczór », bon soir. Entre amis, on dit « cześć », qui sert à la fois de salut et de au revoir. Pour partir poliment, on dit « do widzenia », littéralement « jusqu'au revoir », et entre amis « na razie », à plus tard. Pour aller se coucher, c'est « dobranoc », bonne nuit. Astuce : avec un voisin que vous vouvoyez, « dzień dobry » en arrivant, « do widzenia » en partant, et vous ne vous tromperez jamais.","lit":"jusqu'à · revoir · jusqu'à · demain"}},{"title":"Un matin sans café","phrases":[{"fr":"Le soir, je ne bois pas de café.","tgt":"Wieczorem nie piję kawy.","lit":"le-soir · [ne… pas] · je-bois · café [génitif]"},{"fr":"Il n'y a plus de lait.","tgt":"Nie ma już mleka.","lit":"[ne… pas] · a · déjà · lait [génitif]"},{"fr":"Ce matin, je ne suis pas pressé.","tgt":"Dziś rano się nie spieszę.","lit":"aujourd'hui · matin · [se] · [ne… pas] · je-me-presse"},{"fr":"Ce n'est pas mon tramway.","tgt":"To nie jest mój tramwaj.","lit":"ce · [ne… pas] · est · mon · tramway"},{"fr":"Pardon, je ne comprends pas très bien.","tgt":"Przepraszam, nie bardzo rozumiem.","lit":"pardon · [ne… pas] · très · je-comprends"},{"fr":"Je ne travaille pas le samedi.","tgt":"Nie pracuję w soboty.","lit":"[ne… pas] · je-travaille · en · samedis"},{"fr":"Le café n'est pas assez chaud.","tgt":"Kawa nie jest wystarczająco gorąca.","lit":"café · [ne… pas] · est · assez · chaud"},{"fr":"Je ne mange pas de viande le lundi.","tgt":"Nie jem mięsa w poniedziałki.","lit":"[ne… pas] · je-mange · viande [génitif] · en · lundis"},{"fr":"Non, merci, sans sucre.","tgt":"Nie, dziękuję, bez cukru.","lit":"non · je-remercie · sans · sucre [génitif]"},{"fr":"Je ne connais pas encore le quartier.","tgt":"Jeszcze nie znam okolicy.","lit":"encore · [ne… pas] · je-connais · quartier [génitif]"}],"tip":{"title":"« Nie » : la négation, toujours devant le verbe","example":"Le soir, je ne bois pas de café. — Wieczorem <b>nie</b> piję kawy.","body":"En français, la négation a deux morceaux, « ne » et « pas », qui entourent le verbe. En polonais, c'est beaucoup plus simple : un seul petit mot, « nie », placé juste devant le verbe. « Piję », je bois, devient « nie piję », je ne bois pas. « Rozumiem », je comprends, devient « nie rozumiem », je ne comprends pas. Et « jest », il est, devient « nie jest », il n'est pas. Attention, « nie » veut aussi dire « non » tout court, quand on répond à une question. Petit détail que vous entendrez : après « nie », l'objet change souvent de forme, « kawę » devient « kawy ». Astuce : collez « nie » au verbe comme s'il faisait partie du mot, et dites les deux d'un seul souffle.","lit":"le-soir · [ne… pas] · je-bois · café [génitif]"}},{"title":"Au café du matin","phrases":[{"fr":"Pardon, cette place est libre ?","tgt":"Przepraszam, czy to miejsce jest wolne?","lit":"pardon · [question] · cette · place · est · libre"},{"fr":"Il y a du lait végétal ?","tgt":"Czy jest mleko roślinne?","lit":"[question] · est · lait · végétal"},{"fr":"Vous parlez français, monsieur ?","tgt":"Czy pan mówi po francusku?","lit":"[question] · monsieur · parle · à-la · française"},{"fr":"Je peux payer avec ma carte ?","tgt":"Czy mogę zapłacić kartą?","lit":"[question] · je-peux · payer · carte [instrumental]"},{"fr":"Ce café est fort ?","tgt":"Czy ta kawa jest mocna?","lit":"[question] · ce · café · est · fort"},{"fr":"Le café ouvre à sept heures ?","tgt":"Czy kawiarnia jest otwarta o siódmej?","lit":"[question] · café · est · ouvert · à · septième"},{"fr":"Oui, bien sûr.","tgt":"Tak, oczywiście.","lit":"oui · évidemment"},{"fr":"Il y a le wifi ici ?","tgt":"Czy jest tu wifi?","lit":"[question] · est · ici · wifi"},{"fr":"Un cappuccino et une brioche, s'il vous plaît.","tgt":"Poproszę cappuccino i drożdżówkę.","lit":"je-demande · cappuccino · et · brioche [acc.]"},{"fr":"Est-ce que tout va bien ?","tgt":"Czy wszystko w porządku?","lit":"[question] · tout · en · ordre"}],"tip":{"title":"« Czy » : transformer une phrase en question","example":"Je peux payer avec ma carte ? — <b>Czy</b> mogę zapłacić kartą?","body":"Pour poser une question fermée, celle à laquelle on répond par oui ou par non, le polonais a un outil très pratique : le petit mot « czy ». Il joue exactement le rôle de notre « est-ce que ». On prend une phrase normale et on met « czy » devant, sans rien changer d'autre. « Mogę zapłacić kartą », je peux payer par carte, devient « czy mogę zapłacić kartą ? », est-ce que je peux payer par carte ? De même, « czy jest tu wifi ? », est-ce qu'il y a le wifi ici ? À l'oral, on peut aussi oublier « czy » et simplement monter la voix à la fin, comme en français. Astuce : dans un café ou une boutique, commencez par « czy », c'est toujours poli et clair.","lit":"[question] · je-peux · payer · carte [instrumental]"}},{"title":"Les voisins de palier","phrases":[{"fr":"Moi, je suis de Paris.","tgt":"Ja jestem z Paryża.","lit":"moi · je-suis · de · Paris [génitif]"},{"fr":"Et toi, tu es d'où ?","tgt":"A ty skąd jesteś?","lit":"et · toi · d'où · tu-es"},{"fr":"Voici Piotr, il est médecin.","tgt":"To jest Piotr, on jest lekarzem.","lit":"ce · est · Piotr · lui · est · médecin [instrumental]"},{"fr":"Elle, elle travaille à la poste.","tgt":"Ona pracuje na poczcie.","lit":"elle · travaille · sur · poste [locatif]"},{"fr":"Nous habitons au troisième étage.","tgt":"My mieszkamy na trzecim piętrze.","lit":"nous · habitons · sur · troisième · étage [locatif]"},{"fr":"Vous habitez ici depuis longtemps, tous les deux ?","tgt":"Czy wy mieszkacie tu od dawna?","lit":"[question] · vous · habitez · ici · depuis · longtemps"},{"fr":"Ils ont un petit chien.","tgt":"Oni mają małego psa.","lit":"eux · ont · petit · chien [acc.]"},{"fr":"Elle est très sympathique.","tgt":"Ona jest bardzo sympatyczna.","lit":"elle · est · très · sympathique"},{"fr":"Nous, nous prenons le tramway.","tgt":"My jeździmy tramwajem.","lit":"nous · roulons · tramway [instrumental]"},{"fr":"Lui, il ne parle pas français.","tgt":"On nie mówi po francusku.","lit":"lui · [ne… pas] · parle · à-la · française"}],"tip":{"title":"Les pronoms : « ja », « ty », « on », « ona », « my », « wy », « oni »","example":"Ils ont un petit chien. — <b>Oni</b> mają małego psa.","body":"Voici les pronoms personnels du polonais : « ja », je, « ty », tu, « on », il, « ona », elle, « my », nous, « wy », vous quand on s'adresse à plusieurs personnes, et « oni », ils. Comme le verbe indique déjà qui agit, on les utilise surtout pour insister ou pour opposer deux personnes, comme notre « moi, je » ou « lui, il ». Par exemple, « ja jestem z Paryża », moi, je suis de Paris. Ou encore « on nie mówi po francusku », lui, il ne parle pas français. Pour « il » et « elle », le pronom est utile quand on présente quelqu'un. Attention, « wy » n'est pas le vous de politesse, nous verrons cela plus tard. Astuce : « on » ressemble à notre « on », mais il veut dire « il ».","lit":"eux · ont · petit · chien [acc.]"}},{"title":"Premier jour au bureau","phrases":[{"fr":"Je suis au bureau à neuf heures.","tgt":"Jestem w biurze o dziewiątej.","lit":"je-suis · dans · bureau [locatif] · à · neuvième"},{"fr":"Tu es nouveau dans l'équipe ?","tgt":"Jesteś nowy w zespole?","lit":"tu-es · nouveau · dans · équipe [locatif]"},{"fr":"Le chef est en réunion.","tgt":"Szef jest na spotkaniu.","lit":"chef · est · sur · réunion [locatif]"},{"fr":"Nous sommes une petite équipe.","tgt":"Jesteśmy małym zespołem.","lit":"nous-sommes · petite · équipe [instrumental]"},{"fr":"Vous êtes prêts, tout le monde ?","tgt":"Jesteście gotowi?","lit":"vous-êtes · prêts"},{"fr":"Les collègues sont très gentils.","tgt":"Koledzy są bardzo mili.","lit":"collègues · sont · très · gentils"},{"fr":"Le bureau est au cinquième étage.","tgt":"Biuro jest na piątym piętrze.","lit":"bureau · est · sur · cinquième · étage [locatif]"},{"fr":"Je suis un peu en retard ce matin.","tgt":"Jestem dziś rano trochę spóźniony.","lit":"je-suis · aujourd'hui · matin · un-peu · en-retard"},{"fr":"Elle est où, la salle de réunion ?","tgt":"Gdzie jest sala konferencyjna?","lit":"où · est · salle · de-conférence"},{"fr":"L'ordinateur est très lent aujourd'hui.","tgt":"Komputer jest dziś bardzo wolny.","lit":"ordinateur · est · aujourd'hui · très · lent"}],"tip":{"title":"« Być » au présent : « jestem », « jesteś », « jest »","example":"Tu es nouveau dans l'équipe ? — <b>Jesteś</b> nowy w zespole?","body":"Le verbe « być », être, est le plus utile de tous. Au présent, il se dit « jestem », je suis, « jesteś », tu es, et « jest », il est ou elle est. Au pluriel, on a « jesteśmy », nous sommes, « jesteście », vous êtes, et « są », ils sont. Remarquez que presque toutes les formes commencent par le même morceau, « jest », auquel on ajoute une petite fin : « em » pour moi, « eś » pour toi, « eśmy » pour nous. Seule la forme « są » fait bande à part. Décomposons « szef jest na spotkaniu » : le chef, est, sur, la réunion. Astuce : récitez la série à voix haute dans le tramway, comme une petite chanson, jestem, jesteś, jest.","lit":"tu-es · nouveau · dans · équipe [locatif]"}},{"title":"Le marché du quartier","phrases":[{"fr":"Le fromage est bien frais.","tgt":"Ser jest bardzo świeży.","lit":"fromage [masc.] · est · très · frais"},{"fr":"La tomate est bien mûre.","tgt":"Pomidor jest dojrzały.","lit":"tomate [masc.] · est · mûr"},{"fr":"La soupe est encore chaude.","tgt":"Zupa jest jeszcze gorąca.","lit":"soupe [fém.] · est · encore · chaude"},{"fr":"Le lait vient de la ferme.","tgt":"Mleko jest prosto z gospodarstwa.","lit":"lait [neutre] · est · directement · de · ferme [génitif]"},{"fr":"Cette fraise est délicieuse.","tgt":"Ta truskawka jest pyszna.","lit":"cette · fraise [fém.] · est · délicieuse"},{"fr":"Le miel vient de Mazurie.","tgt":"Miód jest z Mazur.","lit":"miel [masc.] · est · de · Mazurie [génitif]"},{"fr":"La pomme est sucrée.","tgt":"Jabłko jest słodkie.","lit":"pomme [neutre] · est · sucrée"},{"fr":"La vendeuse est très souriante.","tgt":"Sprzedawczyni jest bardzo uśmiechnięta.","lit":"vendeuse [fém.] · est · très · souriante"},{"fr":"Le marché est ouvert jusqu'à midi.","tgt":"Targ jest czynny do południa.","lit":"marché [masc.] · est · ouvert · jusqu'à · midi [génitif]"},{"fr":"La viande est chère aujourd'hui.","tgt":"Mięso jest dziś drogie.","lit":"viande [neutre] · est · aujourd'hui · chère"}],"tip":{"title":"Le genre des noms : masculin, féminin, neutre","example":"La pomme est sucrée. — <b>Jabłko</b> jest słodkie.","body":"Le français a deux genres, le polonais en a trois : masculin, féminin et neutre. Bonne nouvelle, on entend le genre à la fin du mot. Un nom qui se termine par une consonne est en général masculin, comme « ser », le fromage, ou « targ », le marché. Un nom en « a » est souvent féminin, comme « zupa », la soupe. Un nom en « o » ou en « e » est neutre, comme « mleko », le lait. Attention, le genre ne correspond pas toujours au français : la pomme, « jabłko », est neutre, et la tomate, « pomidor », est masculine. Il n'y a pas d'article, pas de « le » ni de « la », c'est la terminaison qui fait tout. Astuce : écoutez la dernière syllabe, elle vous dit le genre.","lit":"pomme [neutre] · est · sucrée"}},{"title":"Bienvenue chez moi","phrases":[{"fr":"Voici ma cuisine.","tgt":"To jest moja kuchnia.","lit":"ce · est · ma · cuisine"},{"fr":"Et ça, c'est le salon.","tgt":"A to jest salon.","lit":"et · ce · est · salon"},{"fr":"C'est une petite salle de bains.","tgt":"To jest mała łazienka.","lit":"ce · est · petite · salle-de-bains"},{"fr":"Je te présente ma femme, Ania.","tgt":"To jest moja żona, Ania.","lit":"ce · est · ma · femme · Ania"},{"fr":"C'est un appartement calme.","tgt":"To jest ciche mieszkanie.","lit":"ce · est · calme · appartement"},{"fr":"Qu'est-ce que c'est, ce truc ?","tgt":"Co to jest?","lit":"quoi · ce · est"},{"fr":"C'est une vieille photo de Gdańsk.","tgt":"To jest stare zdjęcie z Gdańska.","lit":"ce · est · vieille · photo · de · Gdańsk [génitif]"},{"fr":"C'est la clé de la cave.","tgt":"To jest klucz do piwnicy.","lit":"ce · est · clé · vers · cave [génitif]"},{"fr":"Voici le balcon, avec vue sur le parc.","tgt":"To jest balkon z widokiem na park.","lit":"ce · est · balcon · avec · vue [instrumental] · sur · parc"},{"fr":"C'est vraiment joli chez toi !","tgt":"Bardzo ładnie u ciebie!","lit":"très · joliment · chez · toi"}],"tip":{"title":"« To jest » : c'est, voici","example":"Voici ma cuisine. — <b>To jest</b> moja kuchnia.","body":"Pour montrer quelque chose ou présenter quelqu'un, le polonais utilise une formule passe-partout : « to jest ». Mot à mot, « to » veut dire ce ou ça, et « jest » veut dire est. C'est donc notre « c'est », mais aussi notre « voici ». « To jest moja kuchnia », voici ma cuisine. « To jest moja żona », je te présente ma femme. Et pour demander ce qu'est un objet, on retourne la formule : « co to jest ? », qu'est-ce que c'est ? Le mot « to » ne change jamais, que l'objet soit masculin, féminin ou neutre. À l'oral, on raccourcit souvent en « to », tout seul, sans « jest ». Astuce : pendant une visite, pointez chaque objet du doigt et dites « to jest », puis son nom.","lit":"ce · est · ma · cuisine"}},{"title":"Le bar à lait","phrases":[{"fr":"Le bar à lait n'est pas cher.","tgt":"Bar mleczny jest tani.","lit":"bar · laitier · est · bon-marché"},{"fr":"Le żurek est très bon ici.","tgt":"Żurek jest tu bardzo dobry.","lit":"żurek [masc.] · est · ici · très · bon"},{"fr":"La soupe du jour est bonne.","tgt":"Zupa dnia jest dobra.","lit":"soupe [fém.] · du-jour · est · bonne"},{"fr":"Ce plat est bon et pas cher.","tgt":"To danie jest dobre i niedrogie.","lit":"ce · plat [neutre] · est · bon · et · pas-cher"},{"fr":"Je prends des pierogi à la viande.","tgt":"Poproszę pierogi z mięsem.","lit":"je-demande · pierogi · avec · viande [instrumental]"},{"fr":"Les pierogi sont chauds et bons.","tgt":"Pierogi są gorące i dobre.","lit":"pierogi · sont · chauds · et · bons"},{"fr":"La dame à la caisse est gentille.","tgt":"Pani przy kasie jest miła.","lit":"dame · près · caisse [locatif] · est · gentille"},{"fr":"Un grand thé, s'il vous plaît.","tgt":"Poproszę dużą herbatę.","lit":"je-demande · grand · thé [acc.]"},{"fr":"Le kompot est froid et sucré.","tgt":"Kompot jest zimny i słodki.","lit":"kompot [masc.] · est · froid · et · sucré"},{"fr":"C'est un bon endroit pour déjeuner.","tgt":"To dobre miejsce na obiad.","lit":"ce · bon · endroit [neutre] · pour · déjeuner"}],"tip":{"title":"L'adjectif s'accorde : « dobry », « dobra », « dobre »","example":"La soupe du jour est bonne. — Zupa dnia jest <b>dobra</b>.","body":"Comme en français, l'adjectif polonais s'accorde avec le nom, mais il a trois formes au lieu de deux. Prenons « bon » : on dit « dobry » pour un nom masculin, « dobra » pour un nom féminin, et « dobre » pour un nom neutre. « Żurek jest dobry », le żurek est bon. « Zupa jest dobra », la soupe est bonne. « Danie jest dobre », le plat est bon. Vous voyez la logique : la fin de l'adjectif fait écho à la fin du nom, « a » avec « a », « e » avec « o ». Au pluriel, pour des choses, on retrouve souvent la forme en « e », comme dans « pierogi są dobre ». Astuce : au bar à lait, entraînez-vous avec chaque plat, « dobry », « dobra », « dobre ».","lit":"soupe [fém.] · du-jour · est · bonne"}},{"title":"Ce que j'ai à la maison","phrases":[{"fr":"J'ai un petit appartement.","tgt":"Mam małe mieszkanie.","lit":"j'ai · petit · appartement"},{"fr":"Tu as un vélo pour aller au bureau ?","tgt":"Masz rower do pracy?","lit":"tu-as · vélo · pour · travail [génitif]"},{"fr":"Ma voisine a deux chats.","tgt":"Moja sąsiadka ma dwa koty.","lit":"ma · voisine · a · deux · chats"},{"fr":"Nous avons un balcon ensoleillé.","tgt":"Mamy słoneczny balkon.","lit":"nous-avons · ensoleillé · balcon"},{"fr":"Vous avez une minute, monsieur ?","tgt":"Ma pan chwilę?","lit":"a · monsieur · moment [acc.]"},{"fr":"Ils ont une maison à la campagne.","tgt":"Oni mają dom na wsi.","lit":"eux · ont · maison · sur · campagne [locatif]"},{"fr":"Je n'ai pas le temps ce matin.","tgt":"Nie mam dziś rano czasu.","lit":"[ne… pas] · j'ai · aujourd'hui · matin · temps [génitif]"},{"fr":"J'ai une petite question pour vous.","tgt":"Mam do pana małe pytanie.","lit":"j'ai · à · monsieur [génitif] · petite · question"},{"fr":"Tu as les clés ?","tgt":"Masz klucze?","lit":"tu-as · clés"},{"fr":"On a de la chance avec les voisins.","tgt":"Mamy szczęście do sąsiadów.","lit":"nous-avons · chance · pour · voisins [génitif]"}],"tip":{"title":"« Mieć » : avoir, « mam », « masz », « ma »","example":"Tu as un vélo pour aller au bureau ? — <b>Masz</b> rower do pracy?","body":"Le verbe « mieć », avoir, est court et très régulier. On dit « mam », j'ai, « masz », tu as, et « ma », il ou elle a. Au pluriel, « mamy », nous avons, « macie », vous avez, et « mają », ils ont. Tout part du petit morceau « ma », auquel on ajoute une fin : « m » pour moi, « sz » pour toi, « my » pour nous. Décomposons « mam małe mieszkanie » : j'ai, petit, appartement. Pour une question, il suffit de monter la voix : « masz klucze ? », tu as les clés ? Et à la négation, on dit « nie mam », je n'ai pas. Astuce : « ma », la troisième personne, sert aussi pour le vouvoiement, comme dans « ma pan chwilę ? », vous avez une minute ?","lit":"tu-as · vélo · pour · travail [génitif]"}},{"title":"Faire les courses","phrases":[{"fr":"Un pain de seigle, s'il vous plaît.","tgt":"Poproszę jeden chleb żytni.","lit":"je-demande · un · pain · de-seigle"},{"fr":"Deux bouteilles d'eau.","tgt":"Dwie butelki wody.","lit":"deux · bouteilles · eau [génitif]"},{"fr":"Trois tomates bien rouges.","tgt":"Trzy czerwone pomidory.","lit":"trois · rouges · tomates"},{"fr":"Quatre pommes vertes.","tgt":"Cztery zielone jabłka.","lit":"quatre · vertes · pommes"},{"fr":"Je voudrais cinq œufs.","tgt":"Poproszę pięć jajek.","lit":"je-demande · cinq · œufs [génitif]"},{"fr":"Six yaourts nature.","tgt":"Sześć jogurtów naturalnych.","lit":"six · yaourts [génitif] · nature"},{"fr":"Ça coûte sept złotys.","tgt":"To kosztuje siedem złotych.","lit":"ça · coûte · sept · złotys [génitif]"},{"fr":"Le magasin est à huit minutes à pied.","tgt":"Do sklepu mam osiem minut pieszo.","lit":"vers · magasin [génitif] · j'ai · huit · minutes · à-pied"},{"fr":"J'habite au numéro neuf.","tgt":"Mieszkam pod numerem dziewięć.","lit":"j'habite · sous · numéro [instrumental] · neuf"},{"fr":"Dix petits pains pour toute la famille.","tgt":"Dziesięć bułek dla całej rodziny.","lit":"dix · petits-pains [génitif] · pour · toute · famille"}],"tip":{"title":"Compter de un à dix : « jeden », « dwa », « trzy »","example":"Deux bouteilles d'eau. — <b>Dwie</b> butelki wody.","body":"Voici les chiffres de un à dix : « jeden », « dwa », « trzy », « cztery », « pięć », « sześć », « siedem », « osiem », « dziewięć », « dziesięć ». Comme les adjectifs, les premiers nombres changent selon le genre. « Jeden » est masculin, « jedna » féminin et « jedno » neutre. Pour deux, on dit « dwa » devant un masculin ou un neutre, mais « dwie » devant un féminin : « dwie butelki », deux bouteilles. Autre surprise : à partir de cinq, le nom qui suit change de forme. On dit « trzy złote », trois złotys, mais « pięć złotych », cinq złotys. Ne vous inquiétez pas, à force d'entendre les prix, cela viendra tout seul. Astuce : comptez vos marches d'escalier en polonais chaque matin.","lit":"deux · bouteilles · eau [génitif]"}},{"title":"À la pharmacie du quartier","phrases":[{"fr":"Bonjour madame, vous pouvez m'aider ?","tgt":"Dzień dobry, czy pani może mi pomóc?","lit":"jour · bon · [question] · madame · peut · me · aider"},{"fr":"Que désirez-vous, monsieur ?","tgt":"Czego pan sobie życzy?","lit":"quoi [génitif] · monsieur · [se] · souhaite"},{"fr":"Vous avez quelque chose contre le rhume ?","tgt":"Czy ma pani coś na katar?","lit":"[question] · a · madame · quelque-chose · sur · rhume"},{"fr":"Vous prenez ce sirop le soir.","tgt":"Ten syrop bierze pan wieczorem.","lit":"ce · sirop · prend · monsieur · le-soir"},{"fr":"Vous êtes de Varsovie, madame ?","tgt":"Czy pani jest z Warszawy?","lit":"[question] · madame · est · de · Varsovie [génitif]"},{"fr":"Vous êtes très aimable, merci.","tgt":"Pan jest bardzo uprzejmy, dziękuję.","lit":"monsieur · est · très · aimable · je-remercie"},{"fr":"Vous payez en espèces ?","tgt":"Płaci pan gotówką?","lit":"paie · monsieur · espèces [instrumental]"},{"fr":"Voici votre monnaie, madame.","tgt":"Proszę, oto reszta dla pani.","lit":"je-vous-prie · voici · monnaie · pour · madame [génitif]"},{"fr":"Vous connaissez la pharmacie près du parc ?","tgt":"Zna pan aptekę przy parku?","lit":"connaît · monsieur · pharmacie [acc.] · près · parc [locatif]"},{"fr":"Merci, monsieur, au revoir.","tgt":"Dziękuję panu, do widzenia.","lit":"je-remercie · monsieur [datif] · jusqu'à · revoir"}],"tip":{"title":"« Pan » et « pani » : le vouvoiement à la troisième personne","example":"Vous êtes de Varsovie, madame ? — Czy <b>pani</b> jest z Warszawy?","body":"En polonais, pour vouvoyer quelqu'un, on ne dit pas « vous ». On dit « pan », monsieur, à un homme, et « pani », madame, à une femme, et on conjugue le verbe comme pour « il » ou « elle ». C'est un peu comme si l'on disait en français : « monsieur désire ? » ou « madame est de Varsovie ? ». Décomposons « czy pani jest z Warszawy ? » : est-ce que, madame, est, de Varsovie. Autre exemple, « ma pan chwilę ? », mot à mot « monsieur a un moment ? ». Ce n'est pas du tout vieillot : c'est la façon normale et polie de parler à un inconnu, à un vendeur, à un voisin âgé. Astuce : si vous hésitez, utilisez toujours « pan » ou « pani », personne ne s'en vexera.","lit":"[question] · madame · est · de · Varsovie [génitif]"}},{"title":"Le déjeuner au bistrot","phrases":[{"fr":"Je voudrais un café noir.","tgt":"Poproszę czarną kawę.","lit":"je-demande · noir · café [acc.]"},{"fr":"Et aussi une tarte aux pommes.","tgt":"I jeszcze szarlotkę.","lit":"et · encore · tarte-aux-pommes [acc.]"},{"fr":"Je prends la soupe à la tomate.","tgt":"Biorę zupę pomidorową.","lit":"je-prends · soupe [acc.] · de-tomate [acc.]"},{"fr":"Ma collègue prend une salade.","tgt":"Moja koleżanka bierze sałatkę.","lit":"ma · collègue · prend · salade [acc.]"},{"fr":"J'aime beaucoup la cuisine polonaise.","tgt":"Bardzo lubię polską kuchnię.","lit":"beaucoup · j'aime · polonaise [acc.] · cuisine [acc.]"},{"fr":"Je bois de l'eau gazeuse.","tgt":"Piję wodę gazowaną.","lit":"je-bois · eau [acc.] · gazeuse [acc.]"},{"fr":"La serveuse apporte la carte.","tgt":"Kelnerka przynosi kartę.","lit":"serveuse · apporte · carte [acc.]"},{"fr":"J'attends Marta, elle est en retard.","tgt":"Czekam na Martę, spóźnia się.","lit":"j'attends · sur · Marta [acc.] · elle-est-en-retard · [se]"},{"fr":"Je connais bien cette rue.","tgt":"Dobrze znam tę ulicę.","lit":"bien · je-connais · cette [acc.] · rue [acc.]"},{"fr":"Nous mangeons une soupe et des pierogi.","tgt":"Jemy zupę i pierogi.","lit":"nous-mangeons · soupe [acc.] · et · pierogi"}],"tip":{"title":"L'accusatif : « poproszę kawę », l'objet change de terminaison","example":"Je voudrais un café noir. — Poproszę czarną <b>kawę</b>.","body":"En polonais, les noms changent de terminaison selon leur rôle dans la phrase. Quand un nom est l'objet direct du verbe, celui qu'on prend, qu'on boit ou qu'on aime, il passe à une forme appelée l'accusatif. Le changement le plus visible concerne les noms féminins : le « a » final devient « ę ». « Kawa », le café, devient « kawę » dans « poproszę kawę », je voudrais un café. « Zupa » devient « zupę », et « herbata », le thé, devient « herbatę ». L'adjectif suit le mouvement : « czarna kawa » devient « czarną kawę ». Pour beaucoup de noms masculins de choses et pour les neutres, rien ne change, ouf. Astuce : retenez « poproszę » suivi d'un mot en « ę », c'est la formule magique de toutes vos commandes.","lit":"je-demande · noir · café [acc.]"}},{"title":"Se repérer dans le quartier","phrases":[{"fr":"Où est l'arrêt de tramway ?","tgt":"Gdzie jest przystanek tramwajowy?","lit":"où · est · arrêt · de-tramway"},{"fr":"Qui habite au deuxième étage ?","tgt":"Kto mieszka na drugim piętrze?","lit":"qui · habite · sur · deuxième · étage [locatif]"},{"fr":"Qu'est-ce que tu fais ce soir ?","tgt":"Co robisz dziś wieczorem?","lit":"quoi · tu-fais · aujourd'hui · le-soir"},{"fr":"Combien coûte un ticket de tramway ?","tgt":"Ile kosztuje bilet na tramwaj?","lit":"combien · coûte · billet · pour · tramway"},{"fr":"Où est la boulangerie la plus proche ?","tgt":"Gdzie jest najbliższa piekarnia?","lit":"où · est · la-plus-proche · boulangerie"},{"fr":"Qui est-ce, sur le balcon ?","tgt":"Kto to jest na balkonie?","lit":"qui · ce · est · sur · balcon [locatif]"},{"fr":"Que vend ce petit magasin ?","tgt":"Co sprzedaje ten mały sklep?","lit":"quoi · vend · ce · petit · magasin"},{"fr":"Le trajet dure combien de temps ?","tgt":"Ile czasu trwa jazda?","lit":"combien · temps [génitif] · dure · trajet"},{"fr":"Où habitez-vous, monsieur ?","tgt":"Gdzie pan mieszka?","lit":"où · monsieur · habite"},{"fr":"Qu'est-ce qu'il y a dans ce parc ?","tgt":"Co jest w tym parku?","lit":"quoi · est · dans · ce · parc [locatif]"}],"tip":{"title":"Les mots interrogatifs : « co », « gdzie », « kto », « ile »","example":"Qui habite au deuxième étage ? — <b>Kto</b> mieszka na drugim piętrze?","body":"Pour poser une question ouverte, il suffit de quatre petits mots. « Co » veut dire quoi, ou qu'est-ce que. « Gdzie » veut dire où. « Kto » veut dire qui. Et « ile » veut dire combien. On les place au tout début de la phrase, puis on enchaîne avec le verbe, sans rien ajouter d'autre, pas de « est-ce que ». Décomposons « gdzie jest przystanek ? » : où, est, l'arrêt. Autres exemples : « kto to jest ? », qui est-ce ? et « ile kosztuje bilet ? », combien coûte le ticket ? Avec ces mots-là, on ne met pas « czy », qui sert seulement aux questions en oui ou non. Astuce : retenez la petite série « co, gdzie, kto, ile », et vous pourrez déjà demander presque tout dans la rue.","lit":"qui · habite · sur · deuxième · étage [locatif]"}},{"title":"Le tramway du matin","phrases":[{"fr":"Excusez-moi, quelle heure est-il ?","tgt":"Przepraszam, która godzina?","lit":"pardon · quelle · heure"},{"fr":"Il est exactement sept heures.","tgt":"Jest dokładnie siódma.","lit":"est · exactement · septième"},{"fr":"Le tramway part à huit heures.","tgt":"Tramwaj odjeżdża o ósmej.","lit":"tramway · part · à · huitième"},{"fr":"Je commence à travailler à neuf heures.","tgt":"Zaczynam pracę o dziewiątej.","lit":"je-commence · travail [acc.] · à · neuvième"},{"fr":"Le prochain tramway est dans cinq minutes.","tgt":"Następny tramwaj jest za pięć minut.","lit":"suivant · tramway · est · dans · cinq · minutes [génitif]"},{"fr":"Le matin, je me lève à six heures.","tgt":"Rano wstaję o szóstej.","lit":"le-matin · je-me-lève · à · sixième"},{"fr":"Il est déjà dix heures !","tgt":"Już dziesiąta!","lit":"déjà · dixième"},{"fr":"On se retrouve à midi ?","tgt":"Spotykamy się w południe?","lit":"nous-rencontrons · [se] · en · midi"},{"fr":"Je rentre à la maison à sept heures du soir.","tgt":"Wracam do domu o siódmej wieczorem.","lit":"je-rentre · vers · maison [génitif] · à · septième · le-soir"},{"fr":"Le tramway est à l'heure aujourd'hui.","tgt":"Tramwaj jest dziś punktualny.","lit":"tramway · est · aujourd'hui · ponctuel"}],"tip":{"title":"L'heure : « która godzina ? » et « o ósmej »","example":"Le tramway part à huit heures. — Tramwaj odjeżdża <b>o ósmej</b>.","body":"Pour demander l'heure, on dit « która godzina ? », mot à mot « quelle heure ? ». Pour répondre, le polonais n'utilise pas les nombres ordinaires mais des mots qui veulent dire « la septième », « la huitième », sous-entendu la septième heure. « Jest siódma », il est sept heures, mot à mot « est la septième ». Pour dire « à » une heure, on ajoute le petit mot « o » et la fin du mot change : « o ósmej », à huit heures, « o dziewiątej », à neuf heures, « o szóstej », à six heures. Pour midi, on dit simplement « w południe ». Les terminaisons se ressemblent toutes, retenez juste ce son « ej » à la fin. Astuce : chaque matin, en attendant le tramway, annoncez l'heure à voix basse en polonais.","lit":"tramway · part · à · huitième"}},{"title":"Un samedi à Varsovie","phrases":[{"fr":"Je veux me promener dans le parc Łazienki.","tgt":"Chcę pospacerować po Łazienkach.","lit":"je-veux · me-promener · dans · Łazienki [locatif]"},{"fr":"Tu veux venir au parc avec moi ?","tgt":"Chcesz iść ze mną do parku?","lit":"tu-veux · aller · avec · moi · vers · parc [génitif]"},{"fr":"Aujourd'hui, je vais au marché.","tgt":"Dziś idę na targ.","lit":"aujourd'hui · je-vais · sur · marché [acc.]"},{"fr":"Je peux passer à dix heures.","tgt":"Mogę przyjść o dziesiątej.","lit":"je-peux · venir · à · dixième"},{"fr":"Je prends le tramway jusqu'à la Vieille Ville.","tgt":"Jadę tramwajem na Stare Miasto.","lit":"je-vais · tramway [instrumental] · sur · Vieille · Ville"},{"fr":"Je ne veux pas rester à la maison.","tgt":"Nie chcę siedzieć w domu.","lit":"[ne… pas] · je-veux · être-assis · dans · maison [locatif]"},{"fr":"Nous voulons manger des pierogi.","tgt":"Chcemy zjeść pierogi.","lit":"nous-voulons · manger · pierogi"},{"fr":"J'écris un message à Marta.","tgt":"Piszę wiadomość do Marty.","lit":"j'écris · message · à · Marta [génitif]"},{"fr":"Je veux voir la Vistule au coucher du soleil.","tgt":"Chcę zobaczyć Wisłę o zachodzie słońca.","lit":"je-veux · voir · Vistule [acc.] · à · coucher · soleil [génitif]"},{"fr":"Elle veut acheter des fleurs.","tgt":"Ona chce kupić kwiaty.","lit":"elle · veut · acheter · fleurs"}],"tip":{"title":"« Chcę » : je veux, et les verbes en « -ę »","example":"Je ne veux pas rester à la maison. — Nie <b>chcę</b> siedzieć w domu.","body":"« Chcę » veut dire « je veux », et c'est un verbe très utile pour faire des projets. On le fait suivre directement d'un autre verbe, comme en français : « chcę zobaczyć », je veux voir, « chcę zjeść », je veux manger. Écoutez bien la fin de « chcę » : ce son nasal, un peu comme « an » ou « è » léger, marque très souvent la personne « je ». Vous le retrouvez dans « idę », je vais, « mogę », je peux, « piszę », j'écris, et dans votre fidèle « poproszę ». Pour « tu veux », on dit « chcesz », et pour « il veut », « chce ». Attention, entre amis, « chcę » est parfait, mais dans un magasin, préférez « poproszę », plus poli. Astuce : quand vous parlez de vous, finissez le verbe par ce petit « ę ».","lit":"[ne… pas] · je-veux · être-assis · dans · maison [locatif]"}},{"title":"Les métiers du quartier","phrases":[{"fr":"Moi, je suis ingénieur.","tgt":"Ja jestem inżynierem.","lit":"moi · je-suis · ingénieur [instrumental]"},{"fr":"Ma femme est médecin.","tgt":"Moja żona jest lekarką.","lit":"ma · femme · est · médecin [instrumental]"},{"fr":"Mon voisin est boulanger.","tgt":"Mój sąsiad jest piekarzem.","lit":"mon · voisin · est · boulanger [instrumental]"},{"fr":"Et toi, tu es étudiant ?","tgt":"A ty jesteś studentem?","lit":"et · toi · tu-es · étudiant [instrumental]"},{"fr":"Elle est professeure de français.","tgt":"Ona jest nauczycielką francuskiego.","lit":"elle · est · professeure [instrumental] · français [génitif]"},{"fr":"Le frère d'Ania conduit le tramway.","tgt":"Brat Ani jest motorniczym.","lit":"frère · Ania [génitif] · est · conducteur-de-tramway [instrumental]"},{"fr":"Nous sommes collègues de travail.","tgt":"Jesteśmy kolegami z pracy.","lit":"nous-sommes · collègues [instrumental] · de · travail [génitif]"},{"fr":"C'est un très bon cuisinier.","tgt":"On jest bardzo dobrym kucharzem.","lit":"il · est · très · bon [instrumental] · cuisinier [instrumental]"},{"fr":"Moi, je suis français, et vous ?","tgt":"Jestem Francuzem, a pan?","lit":"je-suis · Français [instrumental] · et · monsieur"},{"fr":"Ma fille est encore étudiante.","tgt":"Moja córka jest jeszcze studentką.","lit":"ma · fille · est · encore · étudiante [instrumental]"}],"tip":{"title":"L'instrumental après « być » : « jestem studentem »","example":"Moi, je suis ingénieur. — Ja jestem <b>inżynierem</b>.","body":"Quand on dit ce que l'on est, son métier ou sa nationalité, le nom qui suit « być », être, change de terminaison. Cette forme s'appelle l'instrumental. Pour un homme, on ajoute en général « em » : « student » devient « jestem studentem », je suis étudiant, et « inżynier » devient « jestem inżynierem ». Pour une femme, le « a » final devient « ą » : « lekarka », la femme médecin, devient « jest lekarką ». C'est comme si le polonais disait « je suis en tant qu'étudiant ». Attention, avec « to jest », on ne change rien : « to jest student », c'est un étudiant. Astuce : présentez-vous chaque jour avec votre métier, « jestem », puis le mot avec « em », jusqu'à ce que ça sonne tout seul.","lit":"moi · je-suis · ingénieur [instrumental]"}},{"title":"Le dimanche au parc","phrases":[{"fr":"Moi aussi, j'aime ce parc.","tgt":"Ja też lubię ten park.","lit":"moi · aussi · j'aime · ce · parc"},{"fr":"Je n'ai que dix minutes.","tgt":"Mam tylko dziesięć minut.","lit":"j'ai · seulement · dix · minutes [génitif]"},{"fr":"Ma femme vient aussi.","tgt":"Moja żona też idzie.","lit":"ma · femme · aussi · vient"},{"fr":"Il n'y a que des enfants ici.","tgt":"Tu są tylko dzieci.","lit":"ici · sont · seulement · enfants"},{"fr":"Je parle seulement un peu polonais.","tgt":"Mówię tylko trochę po polsku.","lit":"je-parle · seulement · un-peu · à-la · polonaise"},{"fr":"Le café est ouvert aussi le dimanche.","tgt":"Kawiarnia jest otwarta też w niedzielę.","lit":"café · est · ouvert · aussi · en · dimanche [acc.]"},{"fr":"Juste un thé, s'il vous plaît.","tgt":"Poproszę tylko herbatę.","lit":"je-demande · seulement · thé [acc.]"},{"fr":"Nous aussi, nous habitons à Mokotów.","tgt":"My też mieszkamy na Mokotowie.","lit":"nous · aussi · habitons · sur · Mokotów [locatif]"},{"fr":"C'est seulement à cinq minutes à pied.","tgt":"To tylko pięć minut pieszo.","lit":"ce · seulement · cinq · minutes [génitif] · à-pied"},{"fr":"Elle aussi est fatiguée.","tgt":"Ona też jest zmęczona.","lit":"elle · aussi · est · fatiguée"}],"tip":{"title":"« Też » et « tylko » : aussi et seulement","example":"Je n'ai que dix minutes. — Mam <b>tylko</b> dziesięć minut.","body":"Deux petits mots vont rendre vos phrases plus vivantes : « też », aussi, et « tylko », seulement. « Też » se place juste après le mot qu'il concerne : « ja też », moi aussi, « ona też », elle aussi. Décomposons « ja też lubię ten park » : moi, aussi, j'aime, ce parc. « Tylko », lui, se met devant ce qu'il limite : « tylko herbatę », seulement un thé, « tylko dziesięć minut », seulement dix minutes. Remarquez qu'en français on dit souvent « ne… que » : « je n'ai que dix minutes ». En polonais, pas de négation, juste « tylko ». Astuce : quand quelqu'un vous dit quelque chose qui vous ressemble, répondez simplement « ja też », c'est la réplique la plus facile et la plus sympathique.","lit":"j'ai · seulement · dix · minutes [génitif]"}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Je parle déjà un peu polonais.","tgt":"Już trochę mówię po polsku.","lit":"déjà · un-peu · je-parle · à-la · polonaise"},{"fr":"Un grand merci pour votre aide.","tgt":"Bardzo dziękuję za pomoc.","lit":"beaucoup · je-remercie · pour · aide [acc.]"},{"fr":"Pardon, vous pouvez répéter ?","tgt":"Przepraszam, może pan powtórzyć?","lit":"pardon · peut · monsieur · répéter"},{"fr":"Je vous en prie, avec plaisir.","tgt":"Proszę bardzo, z przyjemnością.","lit":"je-prie · très · avec · plaisir [instrumental]"},{"fr":"Le polonais est difficile, mais beau.","tgt":"Polski jest trudny, ale piękny.","lit":"polonais · est · difficile · mais · beau"},{"fr":"Excusez-moi, je suis en retard.","tgt":"Przepraszam, jestem spóźniony.","lit":"pardon · je-suis · en-retard"},{"fr":"Je comprends de plus en plus de mots.","tgt":"Rozumiem coraz więcej słów.","lit":"je-comprends · de-plus-en-plus · mots [génitif]"},{"fr":"Je sais saluer, compter et commander.","tgt":"Umiem się przywitać, policzyć i coś zamówić.","lit":"je-sais · [se] · saluer · compter · et · quelque-chose · commander"},{"fr":"Un żurek, s'il vous plaît !","tgt":"Poproszę żurek!","lit":"je-demande · żurek"},{"fr":"Merci, et à bientôt à Varsovie !","tgt":"Dziękuję i do zobaczenia w Warszawie!","lit":"je-remercie · et · jusqu'à · revoir · dans · Varsovie [locatif]"}],"tip":{"title":"Les formules magiques : « proszę », « dziękuję », « przepraszam »","example":"Pardon, vous pouvez répéter ? — <b>Przepraszam</b>, może pan powtórzyć?","body":"Pour terminer ce module, voici trois mots qui ouvrent toutes les portes. « Proszę » veut dire à la fois s'il vous plaît, je vous en prie, et tenez, voici. On l'entend partout, au guichet comme à la boulangerie. « Dziękuję » veut dire merci, et « bardzo dziękuję », merci beaucoup. « Przepraszam » sert à s'excuser, mais aussi à attirer l'attention, comme notre « excusez-moi ». Décomposons « przepraszam, może pan powtórzyć ? » : pardon, peut, monsieur, répéter. Souvenez-vous que l'accent tombe toujours sur l'avant-dernière syllabe : « pro », « ku », « pra ». Astuce : si vous ne deviez garder que trois mots de polonais, ce seraient ceux-là. Bravo pour tout le chemin parcouru !","lit":"pardon · peut · monsieur · répéter"}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Pologne.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à la gare centrale de Cracovie","phrases":[{"fr":"Bonjour, me voici à Cracovie !","tgt":"Dzień dobry, jestem w Krakowie!","lit":"jour · bon · je-suis · à · Cracovie [locatif]"},{"fr":"Excusez-moi, la sortie, c'est où ?","tgt":"Przepraszam, gdzie jest wyjście?","lit":"je-m'excuse · où · est · sortie"},{"fr":"La sortie est là-bas, à gauche.","tgt":"Wyjście jest tam, po lewej.","lit":"sortie · est · là-bas · à · gauche"},{"fr":"Excusez-moi, où sont les taxis ?","tgt":"Przepraszam, gdzie są taksówki?","lit":"je-m'excuse · où · sont · taxis"},{"fr":"J'ai une grande valise.","tgt":"Mam dużą walizkę.","lit":"j'ai · grande · valise [accusatif]"},{"fr":"La gare est vraiment très grande.","tgt":"Dworzec jest bardzo duży.","lit":"gare · est · très · grande"},{"fr":"La vieille ville, c'est par là-bas.","tgt":"Stare Miasto jest tam.","lit":"vieille · ville · est · là-bas"},{"fr":"Je suis fatigué, mais content.","tgt":"Jestem zmęczony, ale zadowolony.","lit":"je-suis · fatigué · mais · content"},{"fr":"Mon hôtel est près de la place du marché.","tgt":"Mój hotel jest blisko rynku.","lit":"mon · hôtel · est · près · place-du-marché [génitif]"},{"fr":"On y va à pied ?","tgt":"Idziemy pieszo?","lit":"nous-allons · à-pied"}]},{"title":"Le programme du séjour","phrases":[{"fr":"Aujourd'hui, je visite la vieille ville.","tgt":"Dzisiaj zwiedzam Stare Miasto.","lit":"aujourd'hui · je-visite · vieille · ville"},{"fr":"Demain, je vais à Wieliczka.","tgt":"Jutro jadę do Wieliczki.","lit":"demain · je-vais [en véhicule] · à · Wieliczka [génitif]"},{"fr":"Hier, j'étais à la gare.","tgt":"Wczoraj byłem na dworcu.","lit":"hier · j'étais · sur · gare [locatif]"},{"fr":"Aujourd'hui, le temps est beau.","tgt":"Dzisiaj jest ładna pogoda.","lit":"aujourd'hui · est · beau · temps"},{"fr":"Demain, c'est samedi.","tgt":"Jutro jest sobota.","lit":"demain · est · samedi"},{"fr":"Qu'est-ce qu'on fait aujourd'hui ?","tgt":"Co dzisiaj robimy?","lit":"quoi · aujourd'hui · nous-faisons"},{"fr":"Aujourd'hui, nous visitons le Wawel.","tgt":"Dzisiaj zwiedzamy Wawel.","lit":"aujourd'hui · nous-visitons · Wawel"},{"fr":"Hier, il faisait froid.","tgt":"Wczoraj było zimno.","lit":"hier · c'était · froid"},{"fr":"Demain, j'ai toute la journée libre.","tgt":"Jutro mam cały dzień wolny.","lit":"demain · j'ai · toute · journée · libre"},{"fr":"Bon, alors à demain !","tgt":"No to do jutra!","lit":"bon · alors · jusqu'à · demain [génitif]"}],"tip":{"title":"« Dzisiaj », « jutro », « wczoraj » : aujourd'hui, demain, hier","example":"Demain, je vais à Wieliczka. — <b>Jutro</b> jadę do Wieliczki.","body":"Trois petits mots suffisent pour situer toute une journée de voyage. « Dzisiaj » veut dire aujourd'hui, et se prononce à peu près « djichaï ». « Jutro » veut dire demain, et se dit « youtro », avec un r bien roulé. « Wczoraj » veut dire hier, et se prononce « ftchoraï » : le w du début sonne comme un f léger. Comme en français, on les place volontiers en tête de phrase : « Jutro jadę do Wieliczki », mot à mot demain, je vais, à Wieliczka. Vous pouvez aussi dire « Dzisiaj zwiedzam », aujourd'hui je visite, ou « Wczoraj było zimno », hier il faisait froid. Une formule très utile pour se quitter : « do jutra », à demain. Astuce pour retenir : « jutro » commence comme « jour », le jour qui vient.","lit":"demain · je-vais [en véhicule] · à · Wieliczka [génitif]"}},{"title":"À l'hôtel près de la place du marché","phrases":[{"fr":"Bonsoir, j'ai une réservation.","tgt":"Dobry wieczór, mam rezerwację.","lit":"bon · soir · j'ai · réservation [accusatif]"},{"fr":"C'est à quel nom, monsieur ?","tgt":"Na jakie nazwisko?","lit":"sur · quel · nom-de-famille"},{"fr":"Je m'appelle Paul Martin.","tgt":"Nazywam się Paul Martin.","lit":"je-nomme · [se] · Paul · Martin"},{"fr":"Voici votre clé, monsieur.","tgt":"Oto pana klucz.","lit":"voici · de-monsieur · clé"},{"fr":"Votre chambre se trouve au deuxième étage.","tgt":"Pana pokój jest na drugim piętrze.","lit":"de-monsieur · chambre · est · sur · deuxième · étage [locatif]"},{"fr":"Le petit-déjeuner, c'est à quelle heure ?","tgt":"O której jest śniadanie?","lit":"à · quelle [heure] · est · petit-déjeuner"},{"fr":"De sept heures à dix heures.","tgt":"Od siódmej do dziesiątej.","lit":"de · septième · à · dixième"},{"fr":"Y a-t-il internet dans la chambre ?","tgt":"Czy w pokoju jest internet?","lit":"[question] · dans · chambre [locatif] · est · internet"},{"fr":"La chambre a vue sur la place.","tgt":"Pokój ma widok na rynek.","lit":"chambre · a · vue · sur · place-du-marché"},{"fr":"Merci, et passez une bonne soirée !","tgt":"Dziękuję, miłego wieczoru!","lit":"merci · agréable · soirée [génitif]"}]},{"title":"Un café sur la place","phrases":[{"fr":"Bonjour, je voudrais un café, s'il vous plaît.","tgt":"Dzień dobry, poproszę kawę.","lit":"jour · bon · je-demanderai · café [accusatif]"},{"fr":"Vous le voulez avec du lait ?","tgt":"Z mlekiem?","lit":"avec · lait [instrumental]"},{"fr":"Oui, et je voudrais aussi un petit gâteau.","tgt":"Tak, i poproszę jeszcze ciastko.","lit":"oui · et · je-demanderai · encore · petit-gâteau"},{"fr":"Je voudrais l'addition, s'il vous plaît.","tgt":"Poproszę rachunek.","lit":"je-demanderai · addition"},{"fr":"Pour moi, un thé au citron.","tgt":"Dla mnie herbata z cytryną.","lit":"pour · moi · thé · avec · citron [instrumental]"},{"fr":"Je voudrais une table pour deux personnes.","tgt":"Poproszę stolik dla dwóch osób.","lit":"je-demanderai · table · pour · deux · personnes [génitif]"},{"fr":"Un verre d'eau, s'il vous plaît.","tgt":"Poproszę szklankę wody.","lit":"je-demanderai · verre [accusatif] · eau [génitif]"},{"fr":"Et pour madame ?","tgt":"A dla pani?","lit":"et · pour · madame"},{"fr":"Je voudrais un chocolat chaud.","tgt":"Poproszę gorącą czekoladę.","lit":"je-demanderai · chaude · chocolat [accusatif]"},{"fr":"Voilà, régalez-vous !","tgt":"Proszę bardzo, smacznego!","lit":"je-vous-prie · très · bon-appétit"}],"tip":{"title":"« Poproszę » : je voudrais, pour commander poliment","example":"Bonjour, je voudrais un café, s'il vous plaît. — Dzień dobry, <b>poproszę</b> kawę.","body":"Au café, au guichet ou au marché, un seul mot vous ouvre toutes les portes : « poproszę ». Il se prononce « poprochè », avec l'accent sur l'avant-dernière syllabe, « pro ». Mot à mot, il veut dire je demanderai, mais il sert exactement comme notre je voudrais, s'il vous plaît. Inutile d'ajouter un verbe : on dit simplement « poproszę » suivi de ce qu'on veut. Par exemple « poproszę kawę », un café s'il vous plaît, ou « poproszę rachunek », l'addition s'il vous plaît. Remarquez que « kawa », le café, devient « kawę » : l'objet change de terminaison, c'est l'accusatif. Pour un verre d'eau, on dira « poproszę szklankę wody ». Astuce pour retenir : « poproszę » contient « proszę », qui veut dire s'il vous plaît, et que vous entendrez partout.","lit":"jour · bon · je-demanderai · café [accusatif]"}},{"title":"La place du marché et la halle aux draps","phrases":[{"fr":"La place du marché est immense.","tgt":"Rynek jest ogromny.","lit":"place-du-marché · est · immense"},{"fr":"Voici la halle aux draps.","tgt":"Oto Sukiennice.","lit":"voici · halle-aux-draps"},{"fr":"Il y a beaucoup de touristes ici.","tgt":"Tu jest dużo turystów.","lit":"ici · est · beaucoup · touristes [génitif]"},{"fr":"Les pigeons sont partout.","tgt":"Gołębie są wszędzie.","lit":"pigeons · sont · partout"},{"fr":"Les calèches sont très jolies.","tgt":"Dorożki są bardzo ładne.","lit":"calèches · sont · très · jolies"},{"fr":"Le café sur la place est cher.","tgt":"Kawa na rynku jest droga.","lit":"café · sur · place-du-marché [locatif] · est · chère"},{"fr":"La halle aux draps est au milieu de la place.","tgt":"Sukiennice są na środku rynku.","lit":"halle-aux-draps · sont · sur · milieu · place-du-marché [génitif]"},{"fr":"À l'intérieur, il y a des stands de souvenirs.","tgt":"W środku są stoiska z pamiątkami.","lit":"dans · intérieur · sont · stands · avec · souvenirs [instrumental]"},{"fr":"J'aime beaucoup cet endroit.","tgt":"Bardzo lubię to miejsce.","lit":"beaucoup · j'aime · cet · endroit"},{"fr":"On fait une photo ici ?","tgt":"Robimy tu zdjęcie?","lit":"nous-faisons · ici · photo"}]},{"title":"Des souvenirs à la halle aux draps","phrases":[{"fr":"Combien coûte ce collier ?","tgt":"Ile kosztuje ten naszyjnik?","lit":"combien · coûte · ce · collier"},{"fr":"Quarante złotys.","tgt":"Czterdzieści złotych.","lit":"quarante · złotys [génitif]"},{"fr":"Hum, c'est un peu cher pour moi.","tgt":"Hm, to dla mnie trochę drogo.","lit":"hum · ça · pour · moi · un-peu · cher"},{"fr":"Et combien coûte cette tasse ?","tgt":"A ile kosztuje ta filiżanka?","lit":"et · combien · coûte · cette · tasse"},{"fr":"Vingt-cinq złotys.","tgt":"Dwadzieścia pięć złotych.","lit":"vingt · cinq · złotys [génitif]"},{"fr":"Combien coûtent ces cartes postales ?","tgt":"Ile kosztują te pocztówki?","lit":"combien · coûtent · ces · cartes-postales"},{"fr":"Trois złotys pièce.","tgt":"Trzy złote za sztukę.","lit":"trois · złotys · pour · pièce"},{"fr":"Je prends dix cartes postales.","tgt":"Biorę dziesięć pocztówek.","lit":"je-prends · dix · cartes-postales [génitif]"},{"fr":"Ça fait cent złotys en tout.","tgt":"Razem sto złotych.","lit":"ensemble · cent · złotys [génitif]"},{"fr":"Je peux régler par carte ?","tgt":"Mogę zapłacić kartą?","lit":"je-peux · payer · carte [instrumental]"}],"tip":{"title":"« Ile kosztuje ? » : les prix et les nombres jusqu'à cent","example":"Combien coûte ce collier ? — <b>Ile kosztuje</b> ten naszyjnik?","body":"Pour demander un prix, retenez « ile kosztuje », qui se prononce à peu près « ilé kochtouyé » et veut dire combien coûte. On le fait suivre de l'objet : « ile kosztuje ten naszyjnik », combien coûte ce collier. Pour plusieurs objets, le verbe devient « kosztują », combien coûtent. Côté réponse, le mot de la monnaie change selon le nombre, et c'est ce qu'on entend tout de suite. Avec deux, trois ou quatre, on dit « złote », par exemple « trzy złote », trois złotys. À partir de cinq, on dit « złotych » : « pięć złotych », « dwadzieścia złotych », « sto złotych », cinq, vingt, cent złotys. Les dizaines sont faciles à reconnaître : « dwadzieścia », vingt, « trzydzieści », trente, « pięćdziesiąt », cinquante. Astuce pour retenir : jusqu'à quatre on dit « złote », au-delà on dit « złotych ».","lit":"combien · coûte · ce · collier"}},{"title":"Un obwarzanek dans la rue","phrases":[{"fr":"C'est quel genre de pain ?","tgt":"Co to za pieczywo?","lit":"quoi · ce · [pour] · pain"},{"fr":"C'est un obwarzanek de Cracovie.","tgt":"To krakowski obwarzanek.","lit":"c'est · cracovien · obwarzanek"},{"fr":"Il y en a au sésame et au pavot.","tgt":"Są z sezamem i z makiem.","lit":"sont · avec · sésame [instrumental] · et · avec · pavot [instrumental]"},{"fr":"Je voudrais un obwarzanek au sésame.","tgt":"Poproszę jeden obwarzanek z sezamem.","lit":"je-demanderai · un · obwarzanek · avec · sésame [instrumental]"},{"fr":"Combien je vous dois pour ça ?","tgt":"Ile płacę za to?","lit":"combien · je-paie · pour · ça"},{"fr":"Trois złotys cinquante.","tgt":"Trzy złote pięćdziesiąt.","lit":"trois · złotys · cinquante"},{"fr":"Il est encore tiède !","tgt":"Jest jeszcze ciepły!","lit":"est · encore · tiède"},{"fr":"Il est croustillant et bon.","tgt":"Jest chrupiący i dobry.","lit":"est · croustillant · et · bon"},{"fr":"Les Cracoviens en mangent le matin.","tgt":"Krakowianie jedzą je rano.","lit":"Cracoviens · mangent · les · le-matin"},{"fr":"J'en achète un aussi pour ma femme.","tgt":"Kupuję też jeden dla żony.","lit":"j'achète · aussi · un · pour · épouse [génitif]"}]},{"title":"Les billets de tramway","phrases":[{"fr":"Où est le distributeur de billets ?","tgt":"Gdzie jest biletomat?","lit":"où · est · distributeur-de-billets"},{"fr":"Le distributeur est dans le tram.","tgt":"Biletomat jest w tramwaju.","lit":"distributeur · est · dans · tram [locatif]"},{"fr":"Je vais de la gare à l'hôtel.","tgt":"Jadę z dworca do hotelu.","lit":"je-vais [en véhicule] · de · gare [génitif] · à · hôtel [génitif]"},{"fr":"Ce tram va-t-il à Kazimierz ?","tgt":"Czy ten tramwaj jedzie do Kazimierza?","lit":"[question] · ce · tram · va · à · Kazimierz [génitif]"},{"fr":"Oui, il va de la gare jusqu'à Kazimierz.","tgt":"Tak, z dworca do Kazimierza.","lit":"oui · de · gare [génitif] · à · Kazimierz [génitif]"},{"fr":"Un billet de vingt minutes, s'il vous plaît.","tgt":"Poproszę bilet na dwadzieścia minut.","lit":"je-demanderai · billet · pour · vingt · minutes [génitif]"},{"fr":"Je marche de l'hôtel au musée.","tgt":"Idę z hotelu do muzeum.","lit":"je-vais [à pied] · de · hôtel [génitif] · à · musée"},{"fr":"Il faut combien de temps de la gare au centre ?","tgt":"Jak długo jedzie się z dworca do centrum?","lit":"comment · longtemps · roule · [se] · de · gare [génitif] · à · centre"},{"fr":"À peu près dix minutes.","tgt":"Około dziesięciu minut.","lit":"environ · dix · minutes [génitif]"},{"fr":"Il faut composter le billet.","tgt":"Trzeba skasować bilet.","lit":"il-faut · composter · billet"}],"tip":{"title":"« Z… do… » : de… à…, et le génitif après « do »","example":"Je vais de la gare à l'hôtel. — Jadę <b>z</b> dworca <b>do</b> hotelu.","body":"Pour dire d'où l'on part et où l'on va, le polonais utilise deux tout petits mots : « z », de, et « do », à ou jusqu'à. « Z » se prononce comme un simple z collé au mot suivant, et « do » se dit « do », comme la note de musique. Après ces deux mots, le nom change de terminaison : c'est le génitif. Ainsi « dworzec », la gare, devient « z dworca », de la gare, et « hotel » devient « do hotelu », à l'hôtel. Décomposons « Jadę z dworca do hotelu » : je vais, de, gare, à, hôtel. De même, « Kraków » donne « do Krakowa », à Cracovie, et « Kazimierz » donne « do Kazimierza ». Les mots étrangers comme « muzeum » ou « centrum » ne changent pas, ce qui simplifie la vie. Astuce pour retenir : après « do », le mot s'allonge souvent d'un petit « a » ou « u » à la fin.","lit":"je-vais [en véhicule] · de · gare [génitif] · à · hôtel [génitif]"}},{"title":"Le quartier de Kazimierz","phrases":[{"fr":"Kazimierz est un quartier très animé.","tgt":"Kazimierz to bardzo żywa dzielnica.","lit":"Kazimierz · c'est · très · animé · quartier"},{"fr":"Il y a beaucoup de petits cafés.","tgt":"Jest tu dużo małych kawiarni.","lit":"est · ici · beaucoup · petits · cafés [génitif]"},{"fr":"Sur la place Nowy, on mange des zapiekanki.","tgt":"Na placu Nowym je się zapiekanki.","lit":"sur · place [locatif] · Nowy · mange · [se] · zapiekanki"},{"fr":"Cette zapiekanka est énorme !","tgt":"Ta zapiekanka jest ogromna!","lit":"cette · zapiekanka · est · énorme"},{"fr":"Les rues sont étroites et jolies.","tgt":"Ulice są wąskie i ładne.","lit":"rues · sont · étroites · et · jolies"},{"fr":"Il y a une fresque sur ce mur.","tgt":"Na tej ścianie jest mural.","lit":"sur · ce · mur [locatif] · est · fresque"},{"fr":"J'aime l'ambiance de ce quartier.","tgt":"Lubię klimat tej dzielnicy.","lit":"j'aime · ambiance · ce · quartier [génitif]"},{"fr":"Le soir, on entend de la musique partout.","tgt":"Wieczorem wszędzie gra muzyka.","lit":"le-soir · partout · joue · musique"},{"fr":"Dans ce café, il y a de vieux meubles.","tgt":"W tej kawiarni są stare meble.","lit":"dans · ce · café [locatif] · sont · vieux · meubles"},{"fr":"On reste encore un peu ?","tgt":"Zostajemy jeszcze trochę?","lit":"nous-restons · encore · un-peu"}]},{"title":"Où êtes-vous ?","phrases":[{"fr":"Je suis à Cracovie depuis trois jours.","tgt":"Jestem w Krakowie od trzech dni.","lit":"je-suis · à · Cracovie [locatif] · depuis · trois · jours [génitif]"},{"fr":"Où êtes-vous en ce moment ?","tgt":"Gdzie pan teraz jest?","lit":"où · monsieur · maintenant · est"},{"fr":"Je suis sur la place du marché.","tgt":"Jestem na rynku.","lit":"je-suis · sur · place-du-marché [locatif]"},{"fr":"Ma femme est à l'hôtel.","tgt":"Żona jest w hotelu.","lit":"épouse · est · dans · hôtel [locatif]"},{"fr":"Ce soir, nous dînons au restaurant.","tgt":"Dziś wieczorem jemy kolację w restauracji.","lit":"aujourd'hui · le-soir · nous-mangeons · dîner · dans · restaurant [locatif]"},{"fr":"Les billets sont dans mon sac.","tgt":"Bilety są w mojej torbie.","lit":"billets · sont · dans · mon · sac [locatif]"},{"fr":"Il y a un concert sur la colline du Wawel.","tgt":"Na Wawelu jest koncert.","lit":"sur · Wawel [locatif] · est · concert"},{"fr":"Mon ami habite à Kazimierz.","tgt":"Mój kolega mieszka na Kazimierzu.","lit":"mon · ami · habite · sur · Kazimierz [locatif]"},{"fr":"Je suis à la gare, sur le quai trois.","tgt":"Jestem na dworcu, na trzecim peronie.","lit":"je-suis · sur · gare [locatif] · sur · troisième · quai [locatif]"},{"fr":"On se retrouve sur la place dans une heure ?","tgt":"Spotkamy się na rynku za godzinę?","lit":"nous-nous-retrouverons · [se] · sur · place-du-marché [locatif] · dans · heure"}],"tip":{"title":"« W » et « na » + locatif : « w Krakowie », « na rynku »","example":"Je suis sur la place du marché. — Jestem <b>na</b> rynku.","body":"Pour dire où l'on se trouve, le polonais utilise surtout deux petits mots : « w », dans, et « na », sur. « W » se prononce comme un v, et devant un son dur il devient presque un f : « w Krakowie » se dit « fkrakovié ». On emploie « w » pour les villes et les lieux fermés : « w Krakowie », à Cracovie, « w hotelu », à l'hôtel. On emploie « na » pour les lieux ouverts et quelques autres : « na rynku », sur la place, « na dworcu », à la gare, « na Wawelu », sur la colline du Wawel. Après ces deux mots, le nom prend une nouvelle terminaison, souvent en « u » ou en « ie » : c'est le locatif. Décomposons « Jestem na rynku » : je suis, sur, place du marché. Astuce pour retenir : si vous pouvez voir le ciel au-dessus de vous, pensez d'abord à « na ».","lit":"je-suis · sur · place-du-marché [locatif]"}},{"title":"Au restaurant de pierogi","phrases":[{"fr":"Bonsoir, vous avez une table libre ?","tgt":"Dobry wieczór, jest wolny stolik?","lit":"bon · soir · est · libre · table"},{"fr":"Tenez, voici le menu.","tgt":"Proszę, oto menu.","lit":"je-vous-prie · voici · menu"},{"fr":"Quels pierogi me conseillez-vous ?","tgt":"Jakie pierogi pan poleca?","lit":"quels · pierogi · monsieur · recommande"},{"fr":"Les plus connus sont au fromage blanc et aux pommes de terre.","tgt":"Najbardziej znane są ruskie, z serem i ziemniakami.","lit":"le-plus · connus · sont · ruskie · avec · fromage · et · pommes-de-terre [instrumental]"},{"fr":"Je vais prendre des pierogi à la viande.","tgt":"Wezmę pierogi z mięsem.","lit":"je-prendrai · pierogi · avec · viande [instrumental]"},{"fr":"Et pour moi, ceux aux myrtilles.","tgt":"A dla mnie z jagodami.","lit":"et · pour · moi · avec · myrtilles [instrumental]"},{"fr":"Avec de la crème ?","tgt":"Ze śmietaną?","lit":"avec · crème [instrumental]"},{"fr":"Oui, et avec des oignons, s'il vous plaît.","tgt":"Tak, i z cebulką, poproszę.","lit":"oui · et · avec · petit-oignon [instrumental] · je-demanderai"},{"fr":"Ces pierogi sont vraiment excellents.","tgt":"Pierogi są naprawdę świetne.","lit":"pierogi · sont · vraiment · excellents"},{"fr":"On laisse un pourboire ?","tgt":"Zostawiamy napiwek?","lit":"nous-laissons · pourboire"}]},{"title":"Demander son chemin vers le Wawel","phrases":[{"fr":"Excusez-moi, comment aller au Wawel ?","tgt":"Przepraszam, jak dojść na Wawel?","lit":"je-m'excuse · comment · arriver-à-pied · sur · Wawel"},{"fr":"Allez tout droit, puis à gauche.","tgt":"Proszę iść prosto, potem w lewo.","lit":"je-vous-prie · aller · tout-droit · ensuite · à · gauche"},{"fr":"Comment aller à la gare à pied ?","tgt":"Jak dojść do dworca?","lit":"comment · arriver-à-pied · à · gare [génitif]"},{"fr":"Je ne connais pas la ville.","tgt":"Nie znam miasta.","lit":"[ne… pas] · je-connais · ville [génitif]"},{"fr":"Comment arriver à la halle aux draps ?","tgt":"Jak dojść do Sukiennic?","lit":"comment · arriver-à-pied · à · halle-aux-draps [génitif]"},{"fr":"Prenez la deuxième rue à droite.","tgt":"Proszę skręcić w drugą ulicę w prawo.","lit":"je-vous-prie · tourner · dans · deuxième · rue · à · droite"},{"fr":"Le Wawel est au bout de cette rue.","tgt":"Wawel jest na końcu tej ulicy.","lit":"Wawel · est · sur · bout [locatif] · cette · rue [génitif]"},{"fr":"Vous avez un plan, monsieur ?","tgt":"Ma pan mapę?","lit":"a · monsieur · plan [accusatif]"},{"fr":"Et pour Kazimierz, c'est par où ?","tgt":"A jak dojść na Kazimierz?","lit":"et · comment · arriver-à-pied · sur · Kazimierz"},{"fr":"Merci beaucoup, vous êtes très gentil.","tgt":"Dziękuję bardzo, jest pan bardzo miły.","lit":"merci · beaucoup · est · monsieur · très · gentil"}],"tip":{"title":"« Jak dojść ? » : demander son chemin","example":"Excusez-moi, comment aller au Wawel ? — Przepraszam, <b>jak dojść</b> na Wawel?","body":"Perdu dans les rues de Cracovie ? Une seule question suffit : « jak dojść ? », qui se prononce à peu près « yak doïchtch ». « Jak » veut dire comment, et « dojść » veut dire arriver à pied jusqu'à un endroit. On commence poliment par « przepraszam », excusez-moi, puis on ajoute le lieu. Pour la plupart des endroits, on dit « do » suivi du génitif : « jak dojść do dworca », comment aller à la gare. Pour certains lieux, on dit « na » : « jak dojść na Wawel », comment aller au Wawel. La réponse commence souvent par « proszę iść prosto », allez tout droit, puis « w lewo », à gauche, ou « w prawo », à droite. Astuce pour retenir : « jak » sonne comme le prénom Jacques dit très vite, et c'est bien une question qu'on pose.","lit":"je-m'excuse · comment · arriver-à-pied · sur · Wawel"}},{"title":"La colline du Wawel","phrases":[{"fr":"Le château du Wawel est magnifique.","tgt":"Zamek na Wawelu jest piękny.","lit":"château · sur · Wawel [locatif] · est · beau"},{"fr":"La colline est au bord de la Vistule.","tgt":"Wzgórze jest nad Wisłą.","lit":"colline · est · au-dessus-de · Vistule [instrumental]"},{"fr":"À l'intérieur, il y a une grande cour.","tgt":"W środku jest duży dziedziniec.","lit":"dans · intérieur · est · grande · cour"},{"fr":"Voici la grotte du dragon.","tgt":"Oto Smocza Jama.","lit":"voici · du-dragon · grotte"},{"fr":"Le dragon crache du feu !","tgt":"Smok zieje ogniem!","lit":"dragon · crache · feu [instrumental]"},{"fr":"Les enfants adorent le dragon.","tgt":"Dzieci uwielbiają smoka.","lit":"enfants · adorent · dragon [accusatif]"},{"fr":"La vue sur la ville est superbe.","tgt":"Widok na miasto jest wspaniały.","lit":"vue · sur · ville · est · superbe"},{"fr":"Aujourd'hui, il y a énormément de monde.","tgt":"Dzisiaj jest bardzo dużo ludzi.","lit":"aujourd'hui · est · très · beaucoup · gens [génitif]"},{"fr":"Deux billets pour le château, s'il vous plaît.","tgt":"Poproszę dwa bilety do zamku.","lit":"je-demanderai · deux · billets · à · château [génitif]"},{"fr":"Le Wawel est le symbole de Cracovie.","tgt":"Wawel to symbol Krakowa.","lit":"Wawel · c'est · symbole · Cracovie [génitif]"}]},{"title":"Au musée du château","phrases":[{"fr":"Je peux entrer ?","tgt":"Mogę wejść?","lit":"je-peux · entrer"},{"fr":"Est-ce qu'on peut prendre des photos ici ?","tgt":"Czy można tu robić zdjęcia?","lit":"[question] · on-peut · ici · faire · photos"},{"fr":"Non, ici, ce n'est pas permis.","tgt":"Nie, tutaj nie można.","lit":"non · ici · [ne… pas] · on-peut"},{"fr":"Je peux laisser mon sac au vestiaire ?","tgt":"Mogę zostawić torbę w szatni?","lit":"je-peux · laisser · sac · dans · vestiaire [locatif]"},{"fr":"A-t-on le droit de s'asseoir ici ?","tgt":"Można tu usiąść?","lit":"on-peut · ici · s'asseoir"},{"fr":"Bien sûr, vous pouvez, monsieur.","tgt":"Oczywiście, może pan.","lit":"évidemment · peut · monsieur"},{"fr":"Je peux payer en espèces ?","tgt":"Mogę zapłacić gotówką?","lit":"je-peux · payer · espèces [instrumental]"},{"fr":"On peut visiter le soir ?","tgt":"Można zwiedzać wieczorem?","lit":"on-peut · visiter · le-soir"},{"fr":"Je peux vous demander quelque chose ?","tgt":"Mogę o coś zapytać?","lit":"je-peux · sur · quelque-chose · demander"},{"fr":"Où peut-on acheter de l'eau ?","tgt":"Gdzie można kupić wodę?","lit":"où · on-peut · acheter · eau [accusatif]"}],"tip":{"title":"« Mogę » et « można » : je peux, est-ce permis","example":"Est-ce qu'on peut prendre des photos ici ? — Czy <b>można</b> tu robić zdjęcia?","body":"Dans un musée ou un château, deux mots vous rendront de grands services. « Mogę », prononcé « moguè », veut dire je peux : « mogę wejść ? », je peux entrer ? « Można », prononcé « mojna », veut dire on peut, ou c'est permis, sans préciser qui. C'est le mot idéal pour demander une règle : « czy można tu robić zdjęcia ? », est-ce qu'on peut prendre des photos ici ? Décomposons : « czy » annonce la question, « można » on peut, « tu » ici, « robić zdjęcia » faire des photos. La réponse négative est très simple : « nie można », ce n'est pas permis. Dans les deux cas, on ajoute le verbe tel quel, sans le changer. Astuce pour retenir : « mogę » parle de moi, « można » parle de tout le monde.","lit":"[question] · on-peut · ici · faire · photos"}},{"title":"Une promenade au bord de la Vistule","phrases":[{"fr":"On se promène au bord de la Vistule ?","tgt":"Idziemy na spacer nad Wisłę?","lit":"nous-allons · sur · promenade · au-bord-de · Vistule [accusatif]"},{"fr":"Ce matin, le fleuve est calme.","tgt":"Dziś rano rzeka jest spokojna.","lit":"aujourd'hui · matin · fleuve · est · calme"},{"fr":"Il y a des bateaux pour les touristes.","tgt":"Są tu statki dla turystów.","lit":"sont · ici · bateaux · pour · touristes [génitif]"},{"fr":"La croisière dure une heure.","tgt":"Rejs trwa godzinę.","lit":"croisière · dure · heure [accusatif]"},{"fr":"Les gens font du vélo.","tgt":"Ludzie jeżdżą na rowerach.","lit":"gens · roulent · sur · vélos [locatif]"},{"fr":"Il y a un banc libre là-bas.","tgt":"Tam jest wolna ławka.","lit":"là-bas · est · libre · banc"},{"fr":"Je m'assois cinq minutes.","tgt":"Siadam na pięć minut.","lit":"je-m'assois · pour · cinq · minutes [génitif]"},{"fr":"Le coucher de soleil sur le fleuve est splendide.","tgt":"Zachód słońca nad rzeką jest przepiękny.","lit":"coucher · soleil [génitif] · au-dessus-de · fleuve [instrumental] · est · splendide"},{"fr":"Le soir, il fait frais au bord de l'eau.","tgt":"Wieczorem nad wodą jest chłodno.","lit":"le-soir · au-bord-de · eau [instrumental] · est · frais"},{"fr":"On rentre à l'hôtel ?","tgt":"Wracamy do hotelu?","lit":"nous-rentrons · à · hôtel [génitif]"}]},{"title":"En route pour Wieliczka","phrases":[{"fr":"On va à Wieliczka en train ou en bus ?","tgt":"Jedziemy do Wieliczki pociągiem czy autobusem?","lit":"nous-allons · à · Wieliczka [génitif] · train [instrumental] · ou · bus [instrumental]"},{"fr":"En train, c'est plus simple.","tgt":"Pociągiem jest prościej.","lit":"train [instrumental] · est · plus-simple"},{"fr":"Le train part de la gare centrale.","tgt":"Pociąg odjeżdża z dworca głównego.","lit":"train · part · de · gare · centrale [génitif]"},{"fr":"Je vais à la gare en tramway.","tgt":"Na dworzec jadę tramwajem.","lit":"sur · gare · je-vais · tram [instrumental]"},{"fr":"Ma femme préfère y aller en taxi.","tgt":"Żona woli jechać taksówką.","lit":"épouse · préfère · aller · taxi [instrumental]"},{"fr":"Le trajet en train dure vingt minutes.","tgt":"Podróż pociągiem trwa dwadzieścia minut.","lit":"trajet · train [instrumental] · dure · vingt · minutes [génitif]"},{"fr":"Deux allers-retours pour Wieliczka, s'il vous plaît.","tgt":"Poproszę dwa bilety do Wieliczki i z powrotem.","lit":"je-demanderai · deux · billets · à · Wieliczka · et · de · retour"},{"fr":"Vous voyagez en voiture ?","tgt":"Podróżuje pan samochodem?","lit":"voyage · monsieur · voiture [instrumental]"},{"fr":"Non, je voyage toujours en train.","tgt":"Nie, zawsze jeżdżę pociągiem.","lit":"non · toujours · je-roule · train [instrumental]"},{"fr":"À Cracovie, je me déplace surtout à vélo.","tgt":"W Krakowie jeżdżę głównie rowerem.","lit":"à · Cracovie [locatif] · je-roule · surtout · vélo [instrumental]"}],"tip":{"title":"Le moyen de transport à l'instrumental : « pociągiem », « tramwajem »","example":"Je vais à la gare en tramway. — Na dworzec jadę <b>tramwajem</b>.","body":"En français, on dit en train, en bus, à vélo. En polonais, on n'ajoute aucun petit mot : c'est la terminaison du nom qui fait tout le travail. On appelle cette forme l'instrumental, car le moyen de transport est l'instrument du voyage. Pour la plupart des mots, on ajoute simplement « em » à la fin : « pociąg », le train, devient « pociągiem », prononcé « potchongièm ». De même, « tramwaj » devient « tramwajem », « autobus » devient « autobusem », et « rower », le vélo, devient « rowerem ». Pour les mots en « a », la fin devient un son nasal « on » : « taksówka » donne « taksówką », en taxi. Décomposons « Jadę pociągiem » : je vais, train à l'instrumental, donc je vais en train. Astuce pour retenir : pensez à « em » comme à un petit moteur accroché au bout du mot.","lit":"sur · gare · je-vais · tram [instrumental]"}},{"title":"La mine de sel de Wieliczka","phrases":[{"fr":"La mine de sel est très profonde.","tgt":"Kopalnia soli jest bardzo głęboka.","lit":"mine · sel [génitif] · est · très · profonde"},{"fr":"On descend par l'escalier.","tgt":"Schodzimy po schodach.","lit":"nous-descendons · par · escaliers [locatif]"},{"fr":"Notre guide parle français.","tgt":"Nasz przewodnik mówi po francusku.","lit":"notre · guide · parle · à-la · française"},{"fr":"En bas, il fait frais.","tgt":"Na dole jest chłodno.","lit":"sur · bas [locatif] · est · frais"},{"fr":"Prenez un pull.","tgt":"Proszę wziąć sweter.","lit":"je-vous-prie · prendre · pull"},{"fr":"Les murs sont en sel.","tgt":"Ściany są z soli.","lit":"murs · sont · de · sel [génitif]"},{"fr":"On a le droit de lécher le mur ?","tgt":"Można polizać ścianę?","lit":"on-peut · lécher · mur [accusatif]"},{"fr":"Il y a même un lac souterrain.","tgt":"Jest tu nawet podziemne jezioro.","lit":"est · ici · même · souterrain · lac"},{"fr":"Les sculptures en sel sont incroyables.","tgt":"Rzeźby z soli są niesamowite.","lit":"sculptures · de · sel [génitif] · sont · incroyables"},{"fr":"La visite dure trois heures.","tgt":"Zwiedzanie trwa trzy godziny.","lit":"visite · dure · trois · heures"}]},{"title":"Loin ou près ?","phrases":[{"fr":"L'hôtel est loin d'ici ?","tgt":"Czy hotel jest daleko stąd?","lit":"[question] · hôtel · est · loin · d'ici"},{"fr":"Non, c'est vraiment tout près.","tgt":"Nie, to naprawdę bardzo blisko.","lit":"non · c'est · vraiment · très · près"},{"fr":"La gare est à cinq minutes à pied.","tgt":"Do dworca jest pięć minut pieszo.","lit":"à · gare [génitif] · est · cinq · minutes · à-pied"},{"fr":"Wieliczka n'est pas loin de Cracovie.","tgt":"Wieliczka jest niedaleko Krakowa.","lit":"Wieliczka · est · pas-loin · Cracovie [génitif]"},{"fr":"Zakopane est plus loin.","tgt":"Zakopane jest dalej.","lit":"Zakopane · est · plus-loin"},{"fr":"Il y a une pharmacie quelque part près d'ici ?","tgt":"Czy jest gdzieś blisko apteka?","lit":"[question] · est · quelque-part · près · pharmacie"},{"fr":"Oui, juste à côté, au coin de la rue.","tgt":"Tak, zaraz obok, na rogu.","lit":"oui · juste · à-côté · sur · coin [locatif]"},{"fr":"Le Wawel, c'est loin à pied ?","tgt":"Czy na Wawel jest daleko na piechotę?","lit":"[question] · sur · Wawel · est · loin · à-pied"},{"fr":"Non, c'est à dix minutes d'ici.","tgt":"Nie, to dziesięć minut stąd.","lit":"non · c'est · dix · minutes [génitif] · d'ici"},{"fr":"J'habite loin, à Paris.","tgt":"Mieszkam daleko, w Paryżu.","lit":"j'habite · loin · à · Paris [locatif]"}],"tip":{"title":"« Daleko » et « blisko » : loin et près d'ici","example":"L'hôtel est loin d'ici ? — Czy hotel jest <b>daleko</b> stąd?","body":"Avant de partir à pied, on veut savoir si c'est loin. En polonais, loin se dit « daleko », prononcé « daléko », et près se dit « blisko », prononcé « blisko » avec un o bien rond. Pour dire d'ici, on ajoute « stąd », prononcé « stont ». Décomposons « Czy hotel jest daleko stąd ? » : question, hôtel, est, loin, d'ici. Si l'on veut préciser près de quoi, le nom qui suit prend la terminaison du génitif : « blisko rynku », près de la place du marché. Il existe aussi un mot très pratique, « niedaleko », pas loin : « Wieliczka jest niedaleko Krakowa », Wieliczka n'est pas loin de Cracovie. Et pour dire plus loin, on dit « dalej ». Astuce pour retenir : « daleko » est un mot long, comme le chemin, et « blisko » est un mot court, comme la distance.","lit":"[question] · hôtel · est · loin · d'ici"}},{"title":"Le départ de l'hôtel","phrases":[{"fr":"Je voudrais la note de la chambre.","tgt":"Poproszę rachunek za pokój.","lit":"je-demanderai · note · pour · chambre"},{"fr":"Je vous rends la clé de la chambre.","tgt":"Oddaję klucz do pokoju.","lit":"je-rends · clé · à · chambre [génitif]"},{"fr":"Vous êtes content de votre séjour ?","tgt":"Jest pan zadowolony z pobytu?","lit":"est · monsieur · content · de · séjour [génitif]"},{"fr":"Oui, l'hôtel est très agréable.","tgt":"Tak, hotel jest bardzo przyjemny.","lit":"oui · hôtel · est · très · agréable"},{"fr":"Mon train part ce soir.","tgt":"Mój pociąg odjeżdża wieczorem.","lit":"mon · train · part · le-soir"},{"fr":"Je peux laisser ma valise ici jusqu'au soir ?","tgt":"Mogę tu zostawić walizkę do wieczora?","lit":"je-peux · ici · laisser · valise [accusatif] · jusqu'à · soir [génitif]"},{"fr":"Bien sûr, jusqu'à dix-huit heures.","tgt":"Oczywiście, do osiemnastej.","lit":"évidemment · jusqu'à · dix-huitième [heure]"},{"fr":"Pouvez-vous m'appeler un taxi ?","tgt":"Może pan zamówić taksówkę?","lit":"peut · monsieur · commander · taxi [accusatif]"},{"fr":"Je reviendrai à Cracovie !","tgt":"Wrócę do Krakowa!","lit":"je-reviendrai · à · Cracovie [génitif]"},{"fr":"Merci pour tout et au revoir !","tgt":"Dziękuję za wszystko, do widzenia!","lit":"merci · pour · tout · jusqu'à · revoir"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Notre voyage à Cracovie se termine.","tgt":"Nasza podróż do Krakowa się kończy.","lit":"notre · voyage · à · Cracovie [génitif] · [se] · termine"},{"fr":"À la gare, il n'y a plus de surprises.","tgt":"Na dworcu nie ma już niespodzianek.","lit":"sur · gare [locatif] · [ne… pas] · il-y-a · plus · surprises [génitif]"},{"fr":"Pas de problème, je commande en polonais.","tgt":"Nie ma problemu, zamawiam po polsku.","lit":"[ne… pas] · il-y-a · problème [génitif] · je-commande · à-la · polonaise"},{"fr":"Je sais demander mon chemin.","tgt":"Umiem zapytać o drogę.","lit":"je-sais · demander · sur · chemin [accusatif]"},{"fr":"Je connais les prix et les nombres.","tgt":"Znam ceny i liczby.","lit":"je-connais · prix · et · nombres"},{"fr":"En polonais, il n'y a pas d'articles.","tgt":"W polskim nie ma rodzajników.","lit":"dans · polonais [locatif] · [ne… pas] · il-y-a · articles [génitif]"},{"fr":"Il n'y a aucune raison d'avoir peur.","tgt":"Nie ma powodu do strachu.","lit":"[ne… pas] · il-y-a · raison [génitif] · à · peur [génitif]"},{"fr":"Je comprends déjà beaucoup de mots.","tgt":"Rozumiem już dużo słów.","lit":"je-comprends · déjà · beaucoup · mots [génitif]"},{"fr":"Le prochain module parle de conversations.","tgt":"Następny moduł jest o rozmowach.","lit":"prochain · module · est · sur · conversations [locatif]"},{"fr":"Bravo, et à très bientôt !","tgt":"Brawo i do zobaczenia!","lit":"bravo · et · jusqu'à · revoir"}],"tip":{"title":"« Nie ma » + génitif : il n'y a pas de…","example":"En polonais, il n'y a pas d'articles. — W polskim <b>nie ma</b> rodzajników.","body":"Pour dire il n'y a pas de, le polonais utilise deux mots très courts : « nie ma », prononcé « nié ma ». Mot à mot, cela veut dire ne a pas, et cela remplace notre il n'y a pas. Après « nie ma », le nom change de terminaison : il passe au génitif, comme après « do ». Ainsi « problem » devient « nie ma problemu », pas de problème, une formule que vous entendrez cent fois par jour. De même, « nie ma biletów », il n'y a plus de billets, ou « nie ma stolika », il n'y a pas de table. Décomposons « W polskim nie ma rodzajników » : dans, polonais, il n'y a pas, articles. Et bonne nouvelle, c'est vrai : le polonais n'a ni le, ni la, ni un, ni une. Astuce pour retenir : commencez par « nie ma problemu », et tout le reste suivra.","lit":"dans · polonais [locatif] · [ne… pas] · il-y-a · articles [génitif]"}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Rendez-vous sur la place du marché","phrases":[{"fr":"Salut ! Quoi de neuf ?","tgt":"Cześć! Co słychać?","lit":"salut · quoi · s'entend"},{"fr":"Ça va bien, merci, et toi ?","tgt":"Dobrze, dziękuję, a ty?","lit":"bien · merci · et · toi"},{"fr":"Je t'attends près de l'hôtel de ville.","tgt":"Czekam na ciebie przy ratuszu.","lit":"j'attends · sur · toi · près-de · hôtel-de-ville"},{"fr":"La place du marché est vraiment belle.","tgt":"Rynek jest naprawdę piękny.","lit":"place-du-marché · est · vraiment · beau"},{"fr":"Que de monde sur la place aujourd'hui !","tgt":"Ale dzisiaj dużo ludzi na Rynku!","lit":"mais · aujourd'hui · beaucoup · de-gens · sur · place-du-marché"},{"fr":"Tu veux un café ?","tgt":"Chcesz kawę?","lit":"tu-veux · café[acc.]"},{"fr":"Oui, volontiers.","tgt":"Tak, chętnie.","lit":"oui · volontiers"},{"fr":"C'est mon ami Marek.","tgt":"To mój przyjaciel Marek.","lit":"c'est · mon · ami · Marek"},{"fr":"Ravi de te connaître, Marek.","tgt":"Miło cię poznać, Marku.","lit":"agréable · te · connaître · Marek"},{"fr":"Wrocław est une ville magnifique !","tgt":"Wrocław to wspaniałe miasto!","lit":"Wrocław · c'est · magnifique · ville"}]},{"title":"Se présenter","phrases":[{"fr":"Dis-moi, tu t'appelles comment ?","tgt":"Powiedz, jak masz na imię?","lit":"dis · comment · tu-as · sur · prénom"},{"fr":"Je m'appelle Paul.","tgt":"Mam na imię Paul.","lit":"j'ai · sur · prénom · Paul"},{"fr":"Mon nom complet, c'est Paul Martin.","tgt":"Nazywam się Paul Martin.","lit":"je-m'appelle · Paul · Martin"},{"fr":"Et toi, c'est quoi ton nom de famille ?","tgt":"A ty, jak się nazywasz?","lit":"et · toi · comment · se · tu-appelles"},{"fr":"Mon nom, c'est Kowalska, Ania Kowalska.","tgt":"Nazywam się Kowalska, Ania Kowalska.","lit":"je-m'appelle · Kowalska · Ania · Kowalska"},{"fr":"Et ton copain, quel est son prénom ?","tgt":"A twój kolega, jak ma na imię?","lit":"et · ton · ami · comment · a · sur · prénom"},{"fr":"Il s'appelle Tomek.","tgt":"Ma na imię Tomek.","lit":"il-a · sur · prénom · Tomek"},{"fr":"Je suis un Français de Lyon.","tgt":"Jestem Francuzem z Lyonu.","lit":"je-suis · Français[instr.] · de · Lyon"},{"fr":"J'habite à Wrocław depuis un mois.","tgt":"Mieszkam we Wrocławiu od miesiąca.","lit":"j'habite · à · Wrocław · depuis · mois"},{"fr":"Et ta voisine, elle s'appelle comment ?","tgt":"A twoja sąsiadka, jak ma na imię?","lit":"et · ta · voisine · comment · a · sur · prénom"}],"tip":{"title":"Se présenter : « mam na imię », « nazywam się »","example":"Je m'appelle Paul. — <b>Mam na imię</b> Paul.","body":"Pour dire son prénom, le polonais utilise une jolie formule : « mam na imię », mot à mot « j'ai pour prénom ». On dit donc « mam na imię Paul », je m'appelle Paul. Pour demander à un ami, on change juste le verbe : « jak masz na imię ? », comment tu t'appelles, avec « jak » qui veut dire comment. Pour quelqu'un d'autre, c'est « ma na imię », il ou elle s'appelle. Il existe une deuxième formule, « nazywam się », qui ressemble beaucoup au français « je me nomme ». On l'utilise surtout pour donner son nom de famille ou son nom complet, par exemple « nazywam się Paul Martin ». La question correspondante est « jak się nazywasz ? ». Retenez l'image : avec « mam na imię », vous tendez la main à un ami ; avec « nazywam się », vous remplissez un formulaire.","lit":"j'ai · sur · prénom · Paul"}},{"title":"D'où viens-tu ?","phrases":[{"fr":"Tu viens d'où, au fait ?","tgt":"A właściwie skąd jesteś?","lit":"et · au-fait · d'où · tu-es"},{"fr":"Je viens de France, de Nantes.","tgt":"Jestem z Francji, z Nantes.","lit":"je-suis · de · France · de · Nantes"},{"fr":"Et toi, tu es de Wrocław ?","tgt":"A ty jesteś z Wrocławia?","lit":"et · toi · tu-es · de · Wrocław"},{"fr":"Non, moi je suis de Gdańsk.","tgt":"Nie, ja jestem z Gdańska.","lit":"non · moi · je-suis · de · Gdańsk"},{"fr":"Gdańsk est au bord de la mer.","tgt":"Gdańsk leży nad morzem.","lit":"Gdańsk · est-situé · au-dessus-de · mer[instr.]"},{"fr":"Tu habites ici depuis longtemps ?","tgt":"Długo tu mieszkasz?","lit":"longtemps · ici · tu-habites"},{"fr":"Depuis deux ans environ.","tgt":"Od mniej więcej dwóch lat.","lit":"depuis · moins · plus · deux · ans"},{"fr":"Tu es étudiant ici ?","tgt":"Jesteś tu studentem?","lit":"tu-es · ici · étudiant[instr.]"},{"fr":"Oui, j'étudie à l'université.","tgt":"Tak, studiuję na uniwersytecie.","lit":"oui · j'étudie · sur · université"},{"fr":"Ton français est vraiment excellent !","tgt":"Świetnie mówisz po francusku!","lit":"excellemment · tu-parles · en · français"}]},{"title":"Les loisirs","phrases":[{"fr":"Qu'est-ce que tu aimes faire le soir ?","tgt":"Co lubisz robić wieczorem?","lit":"quoi · tu-aimes · faire · le-soir"},{"fr":"J'aime la musique.","tgt":"Lubię muzykę.","lit":"j'aime · musique[acc.]"},{"fr":"J'aime aussi le cinéma polonais.","tgt":"Lubię też polskie kino.","lit":"j'aime · aussi · polonais · cinéma"},{"fr":"Tu aimes le sport ?","tgt":"Lubisz sport?","lit":"tu-aimes · sport"},{"fr":"J'aime faire du vélo au bord de l'Oder.","tgt":"Lubię jeździć na rowerze nad Odrą.","lit":"j'aime · rouler · sur · vélo · au-bord-de · Oder[instr.]"},{"fr":"Mon ami aime le football.","tgt":"Mój kolega lubi piłkę nożną.","lit":"mon · ami · aime · ballon[acc.] · de-pied[acc.]"},{"fr":"Moi, je n'aime pas trop le froid.","tgt":"Ja nie bardzo lubię zimno.","lit":"moi · [ne… pas] · très · j'aime · froid"},{"fr":"Tu aimes lire ?","tgt":"Lubisz czytać?","lit":"tu-aimes · lire"},{"fr":"J'aime beaucoup le café au lait.","tgt":"Bardzo lubię kawę z mlekiem.","lit":"très · j'aime · café[acc.] · avec · lait[instr.]"},{"fr":"On aime la même chose !","tgt":"Lubimy to samo!","lit":"nous-aimons · ce · même"}],"tip":{"title":"« Lubię » : aimer, suivi de l'accusatif","example":"J'aime la musique. — <b>Lubię muzykę</b>.","body":"Pour dire j'aime, on dit « lubię », qui se prononce à peu près « loubié ». Comme souvent en polonais, le verbe contient déjà le sujet : pas besoin de dire je. Avec un ami, on demande « lubisz ? », tu aimes, et pour une autre personne on dit « lubi », il ou elle aime. Ce qui est aimé se met à l'accusatif, la forme de l'objet. Pour les mots féminins en « a », cela s'entend bien : « muzyka », la musique, devient « lubię muzykę », j'aime la musique, et « kawa », le café, devient « lubię kawę ». Pour beaucoup de mots masculins, rien ne change : « lubię sport », j'aime le sport. Et pour aimer faire quelque chose, on ajoute simplement le verbe : « lubię czytać », j'aime lire. Astuce : quand vous dites « lubię », pensez que le « a » final du mot suivant se transforme en « ę », qui se prononce comme un « è » à peine nasal.","lit":"j'aime · musique[acc.]"}},{"title":"À la chasse aux nains de bronze","phrases":[{"fr":"Tu connais les petits nains de Wrocław ?","tgt":"Znasz wrocławskie krasnale?","lit":"tu-connais · wrocłaviens · nains"},{"fr":"Ce sont de petites statues en bronze.","tgt":"To są małe figurki z brązu.","lit":"ce · sont · petites · figurines · de · bronze[gén.]"},{"fr":"Il y en a des centaines en ville.","tgt":"W mieście są ich setki.","lit":"dans · ville · sont · d'eux · centaines"},{"fr":"Regarde, il y en a un juste là !","tgt":"Patrz, tu jest jeden!","lit":"regarde · ici · est · un"},{"fr":"Qu'il est mignon, celui-là !","tgt":"Ale ten jest słodki!","lit":"mais · celui-là · est · mignon"},{"fr":"Celui-ci dort sur un banc.","tgt":"Ten śpi na ławce.","lit":"celui-ci · dort · sur · banc"},{"fr":"On en cherche un autre ?","tgt":"Szukamy następnego?","lit":"nous-cherchons · suivant[gén.]"},{"fr":"Attends, je prends une photo.","tgt":"Czekaj, robię zdjęcie.","lit":"attends · je-fais · photo"},{"fr":"On en a combien maintenant ?","tgt":"Ile ich już mamy?","lit":"combien · d'eux · déjà · nous-avons"},{"fr":"Déjà sept, c'est un jeu génial !","tgt":"Już siedem, to świetna zabawa!","lit":"déjà · sept · c'est · génial · jeu"}]},{"title":"Présenter sa famille","phrases":[{"fr":"Voici ma famille sur cette photo.","tgt":"To moja rodzina na tym zdjęciu.","lit":"c'est · ma · famille · sur · cette · photo"},{"fr":"Là, c'est ma mère et mon père.","tgt":"Tu są moja mama i mój tata.","lit":"ici · sont · ma · maman · et · mon · papa"},{"fr":"Maman est prof de maths.","tgt":"Mama jest nauczycielką matematyki.","lit":"maman · est · professeure[instr.] · mathématiques[gén.]"},{"fr":"Mon père travaille à Paris.","tgt":"Tata pracuje w Paryżu.","lit":"papa · travaille · à · Paris"},{"fr":"J'ai un frère et une sœur.","tgt":"Mam brata i siostrę.","lit":"j'ai · frère[acc.] · et · sœur[acc.]"},{"fr":"Mon frère s'appelle Louis.","tgt":"Mój brat ma na imię Louis.","lit":"mon · frère · a · sur · prénom · Louis"},{"fr":"Ma sœur est encore petite.","tgt":"Moja siostra jest jeszcze mała.","lit":"ma · sœur · est · encore · petite"},{"fr":"Et toi, tu as des frères ou des sœurs ?","tgt":"A ty masz rodzeństwo?","lit":"et · toi · tu-as · fratrie"},{"fr":"Non, je suis fils unique.","tgt":"Nie, jestem jedynakiem.","lit":"non · je-suis · enfant-unique[instr.]"},{"fr":"Ta famille vit en France ?","tgt":"Twoja rodzina mieszka we Francji?","lit":"ta · famille · habite · en · France"}],"tip":{"title":"La famille : « mama », « tata », « brat », « siostra »","example":"J'ai un frère et une sœur. — Mam <b>brata</b> i <b>siostrę</b>.","body":"Bonne nouvelle : les mots de la famille sont faciles en polonais. La mère se dit « mama » et le père « tata », exactement comme les petits mots tendres du français, et les adultes les utilisent tous les jours. Le frère se dit « brat » et la sœur « siostra », qu'on prononce à peu près « chiostra ». Quand on dit qu'on a un frère ou une sœur, ces mots changent un peu de forme, car ils deviennent l'objet du verbe avoir. Ainsi « mam brata » veut dire j'ai un frère, et « mam siostrę », j'ai une sœur. Décomposons « mam brata i siostrę » : « mam », j'ai, « brata », un frère, « i », et, « siostrę », une sœur. Pour dire mes parents, on dit « rodzice ». Astuce : pour le frère, imaginez un bras qui protège, « brat » ; pour la sœur, pensez au chuchotement doux qui ouvre le mot « siostra ».","lit":"j'ai · frère[acc.] · et · sœur[acc.]"}},{"title":"Les grands-parents et les autres","phrases":[{"fr":"Et là, ce sont mes grands-parents.","tgt":"A to moi dziadkowie.","lit":"et · ce · mes · grands-parents"},{"fr":"Ma grand-mère fait de super gâteaux.","tgt":"Babcia robi świetne ciasta.","lit":"grand-mère · fait · excellents · gâteaux"},{"fr":"Mon grand-père adore son jardin.","tgt":"Dziadek uwielbia swój ogród.","lit":"grand-père · adore · son · jardin"},{"fr":"Ils habitent à la campagne.","tgt":"Mieszkają na wsi.","lit":"ils-habitent · sur · campagne"},{"fr":"Ton frère est marié ?","tgt":"Twój brat jest żonaty?","lit":"ton · frère · est · marié"},{"fr":"Oui, il a une femme et un fils.","tgt":"Tak, ma żonę i syna.","lit":"oui · il-a · femme[acc.] · et · fils[acc.]"},{"fr":"Mon neveu a cinq ans.","tgt":"Mój bratanek ma pięć lat.","lit":"mon · neveu · a · cinq · ans"},{"fr":"Ta sœur ressemble à ta mère.","tgt":"Twoja siostra jest podobna do mamy.","lit":"ta · sœur · est · semblable · à · maman[gén.]"},{"fr":"C'est vrai, elles ont les mêmes yeux.","tgt":"To prawda, mają takie same oczy.","lit":"c'est · vérité · elles-ont · tels · mêmes · yeux"},{"fr":"Tu as une grande famille !","tgt":"Masz dużą rodzinę!","lit":"tu-as · grande · famille[acc.]"}]},{"title":"Chez moi, chez toi","phrases":[{"fr":"Voilà, c'est mon appartement.","tgt":"No i to jest moje mieszkanie.","lit":"bon · et · ce · est · mon · appartement"},{"fr":"Et ici, c'est ma chambre.","tgt":"A tu jest mój pokój.","lit":"et · ici · est · ma · chambre"},{"fr":"Et ça, c'est notre cuisine.","tgt":"A to nasza kuchnia.","lit":"et · ça · notre · cuisine"},{"fr":"Ton appartement est très lumineux.","tgt":"Twoje mieszkanie jest bardzo jasne.","lit":"ton · appartement · est · très · clair"},{"fr":"C'est ta guitare ?","tgt":"To twoja gitara?","lit":"c'est · ta · guitare"},{"fr":"Non, c'est la guitare de Marek.","tgt":"Nie, to gitara Marka.","lit":"non · c'est · guitare · Marek[gén.]"},{"fr":"Notre quartier est calme.","tgt":"Nasza dzielnica jest spokojna.","lit":"notre · quartier · est · calme"},{"fr":"Où est ton vélo ?","tgt":"Gdzie jest twój rower?","lit":"où · est · ton · vélo"},{"fr":"Mon vélo est en bas.","tgt":"Mój rower jest na dole.","lit":"mon · vélo · est · en · bas"},{"fr":"Notre balcon donne sur l'Oder.","tgt":"Nasz balkon wychodzi na Odrę.","lit":"notre · balcon · sort · sur · Oder[acc.]"}],"tip":{"title":"« Mój », « twój », « nasz » : les possessifs qui s'accordent","example":"C'est ta guitare ? — To <b>twoja</b> gitara?","body":"Les possessifs polonais fonctionnent comme les adjectifs : ils prennent le genre du mot qui suit. Mon se dit « mój » devant un mot masculin, « moja » devant un mot féminin et « moje » devant un mot neutre. Attention, c'est le genre du mot polonais qui compte, pas celui du français : ma chambre se dit « mój pokój », car « pokój » est masculin. Pour ton, c'est la même musique : « twój », « twoja », « twoje ». Pour notre, on dit « nasz », « nasza », « nasze ». Écoutez la phrase « to twoja gitara ? » : « to », c'est, « twoja », ta, « gitara », guitare ; le « a » de « twoja » rime avec le « a » de « gitara ». Voilà l'astuce : très souvent, le possessif finit par le même son que le nom. « Moja kawa », mon café, « nasze mieszkanie », notre appartement. Écoutez la rime et vous ne vous tromperez presque jamais.","lit":"c'est · ta · guitare"}},{"title":"Sur l'île aux étudiants","phrases":[{"fr":"On va sur l'île aux étudiants ?","tgt":"Idziemy na Wyspę Słodową?","lit":"nous-allons · sur · île[acc.] · Słodowa[acc.]"},{"fr":"Le soir, les étudiants s'y retrouvent.","tgt":"Wieczorem spotykają się tam studenci.","lit":"le-soir · rencontrent · se · là-bas · étudiants"},{"fr":"On s'assoit dans l'herbe ?","tgt":"Siadamy na trawie?","lit":"nous-asseyons · sur · herbe"},{"fr":"La soirée est douce.","tgt":"Wieczór jest ciepły.","lit":"soirée · est · chaude"},{"fr":"Regarde la rivière, c'est superbe.","tgt":"Patrz na rzekę, jak pięknie.","lit":"regarde · sur · rivière[acc.] · comme · joliment"},{"fr":"Il y a de la musique là-bas.","tgt":"Tam gra muzyka.","lit":"là-bas · joue · musique"},{"fr":"Ce garçon joue de la guitare.","tgt":"Ten chłopak gra na gitarze.","lit":"ce · garçon · joue · sur · guitare"},{"fr":"Tu as quelque chose à boire ?","tgt":"Masz coś do picia?","lit":"tu-as · quelque-chose · à · boire"},{"fr":"J'ai de l'eau et du jus de pomme.","tgt":"Mam wodę i sok jabłkowy.","lit":"j'ai · eau[acc.] · et · jus · de-pomme"},{"fr":"Ça me plaît énormément, ici.","tgt":"Bardzo mi się tu podoba.","lit":"très · me · se · ici · plaît"}]},{"title":"Passer au « tu »","phrases":[{"fr":"On peut se tutoyer ?","tgt":"Możemy przejść na ty?","lit":"nous-pouvons · passer · sur · tu"},{"fr":"Bien sûr, appelle-moi Kasia.","tgt":"Jasne, mów mi Kasia.","lit":"clair · dis · me · Kasia"},{"fr":"Vous êtes de Wrocław, monsieur ?","tgt":"Czy pan jest z Wrocławia?","lit":"[question] · monsieur · est · de · Wrocław"},{"fr":"Oui, mais tutoyons-nous.","tgt":"Tak, ale mówmy sobie na ty.","lit":"oui · mais · disons · nous · sur · tu"},{"fr":"Avec plaisir, moi c'est Piotr.","tgt":"Z przyjemnością, jestem Piotr.","lit":"avec · plaisir[instr.] · je-suis · Piotr"},{"fr":"Madame, vous voulez un thé ?","tgt":"Czy pani chce herbatę?","lit":"[question] · madame · veut · thé[acc.]"},{"fr":"Tu veux un thé, Ania ?","tgt":"Chcesz herbatę, Aniu?","lit":"tu-veux · thé[acc.] · Ania"},{"fr":"Tu as le temps ce soir ?","tgt":"Masz czas dziś wieczorem?","lit":"tu-as · temps · aujourd'hui · le-soir"},{"fr":"Vous avez le temps ce soir, monsieur ?","tgt":"Czy ma pan czas dziś wieczorem?","lit":"[question] · a · monsieur · temps · aujourd'hui · le-soir"},{"fr":"Entre amis, on se dit toujours « tu ».","tgt":"Między przyjaciółmi zawsze mówimy na ty.","lit":"entre · amis[instr.] · toujours · nous-disons · sur · tu"}],"tip":{"title":"« Ty » ou « pan » : passer au tutoiement entre amis","example":"Vous avez le temps ce soir, monsieur ? — Czy <b>ma pan</b> czas dziś wieczorem?","body":"En polonais, le vouvoiement ne se fait pas avec vous, mais avec « pan », monsieur, et « pani », madame. On parle à la personne comme si elle était une troisième personne : « czy ma pan czas ? », mot à mot « est-ce que monsieur a le temps ? ». Entre amis, c'est beaucoup plus simple : on utilise « ty », tu, et le verbe se termine souvent par un son « ch » : « masz czas ? », tu as le temps ? Comparez « ma pan », vous avez, monsieur, et « masz », tu as. Au début, les Polonais restent assez polis, puis l'un propose de passer au tutoiement avec la formule « przejdźmy na ty », passons au tu. Si on vous le propose, répondez chaleureusement « z przyjemnością », avec plaisir. Astuce : dans un groupe d'amis ou d'étudiants à Wrocław, le « ty » vient très vite, mais avec une personne âgée, gardez « pan » ou « pani ».","lit":"[question] · a · monsieur · temps · aujourd'hui · le-soir"}},{"title":"Une invitation à dîner","phrases":[{"fr":"Je t'invite à dîner samedi.","tgt":"Zapraszam cię w sobotę na kolację.","lit":"j'invite · te · en · samedi · sur · dîner"},{"fr":"Je fais des pierogi maison.","tgt":"Robię domowe pierogi.","lit":"je-fais · maison · pierogi"},{"fr":"Génial, j'adore les pierogi !","tgt":"Super, uwielbiam pierogi!","lit":"super · j'adore · pierogi"},{"fr":"On se voit à quelle heure ?","tgt":"O której się widzimy?","lit":"à · quelle[heure] · se · nous-voyons"},{"fr":"Vers sept heures, ça te va ?","tgt":"Około siódmej, pasuje ci?","lit":"vers · septième · convient · te"},{"fr":"Oui, c'est parfait pour moi.","tgt":"Tak, dla mnie idealnie.","lit":"oui · pour · moi · idéalement"},{"fr":"J'apporte un petit quelque chose ?","tgt":"Przynieść coś?","lit":"apporter · quelque-chose"},{"fr":"Juste un dessert, si tu veux.","tgt":"Tylko deser, jeśli chcesz.","lit":"seulement · dessert · si · tu-veux"},{"fr":"Tu habites où exactement ?","tgt":"Gdzie dokładnie mieszkasz?","lit":"où · exactement · tu-habites"},{"fr":"Rue Świdnicka, au numéro dix.","tgt":"Na Świdnickiej, pod numerem dziesięć.","lit":"sur · Świdnicka · sous · numéro[instr.] · dix"}]},{"title":"On prépare les pierogi","phrases":[{"fr":"Je cuisine aujourd'hui parce que j'ai le temps.","tgt":"Gotuję dzisiaj, bo mam czas.","lit":"je-cuisine · aujourd'hui · parce-que · j'ai · temps"},{"fr":"J'ai de la farine, donc je fais la pâte.","tgt":"Mam mąkę, więc robię ciasto.","lit":"j'ai · farine[acc.] · donc · je-fais · pâte"},{"fr":"Tu veux m'aider ?","tgt":"Chcesz mi pomóc?","lit":"tu-veux · me · aider"},{"fr":"Oui, parce que j'aime cuisiner.","tgt":"Tak, bo lubię gotować.","lit":"oui · parce-que · j'aime · cuisiner"},{"fr":"Avec du fromage blanc et des pommes de terre ?","tgt":"Z twarogiem i ziemniakami?","lit":"avec · fromage-blanc[instr.] · et · pommes-de-terre[instr.]"},{"fr":"Oui, ce sont les pierogi ruskie.","tgt":"Tak, to są pierogi ruskie.","lit":"oui · ce · sont · pierogi · ruskie"},{"fr":"L'eau bout, donc on commence.","tgt":"Woda się gotuje, więc zaczynamy.","lit":"eau · se · cuit · donc · nous-commençons"},{"fr":"Je suis crevé parce que je travaille trop.","tgt":"Jestem zmęczony, bo za dużo pracuję.","lit":"je-suis · fatigué · parce-que · trop · beaucoup · je-travaille"},{"fr":"Il est tard, donc on mange tout de suite.","tgt":"Jest późno, więc jemy od razu.","lit":"est · tard · donc · nous-mangeons · d'un · coup"},{"fr":"Ils sont délicieux parce qu'ils sont faits maison.","tgt":"Są pyszne, bo domowe.","lit":"sont · délicieux · parce-que · maison"}],"tip":{"title":"« Bo » et « więc » : parce que et donc","example":"J'ai de la farine, donc je fais la pâte. — Mam mąkę, <b>więc</b> robię ciasto.","body":"Pour relier deux idées, deux petits mots suffisent. « Bo », qui se prononce comme le mot français beau, veut dire parce que. « Więc », à peu près « vienntss », veut dire donc. Avec « bo », on donne la cause : « gotuję, bo mam czas », je cuisine parce que j'ai le temps. Avec « więc », on donne la conséquence : « mam mąkę, więc robię ciasto », j'ai de la farine, donc je fais la pâte. Mot à mot : « mam », j'ai, « mąkę », de la farine, « więc », donc, « robię », je fais, « ciasto », la pâte. L'ordre des idées est le même qu'en français, rien à réorganiser. À l'oral, on fait une petite pause avant ces deux mots, là où l'on écrirait une virgule. Astuce pour retenir : « bo » regarde en arrière vers la raison, « więc » regarde en avant vers la suite.","lit":"j'ai · farine[acc.] · donc · je-fais · pâte"}},{"title":"À table !","phrases":[{"fr":"Bon appétit à tout le monde !","tgt":"Smacznego wszystkim!","lit":"bon-appétit · à-tous"},{"fr":"Tu peux me passer le sel ?","tgt":"Możesz mi podać sól?","lit":"tu-peux · me · passer · sel"},{"fr":"Bien sûr, tiens.","tgt":"Jasne, proszę.","lit":"clair · je-t'en-prie"},{"fr":"Tu en reveux un peu ?","tgt":"Chcesz jeszcze?","lit":"tu-veux · encore"},{"fr":"Oui, volontiers, ils sont excellents.","tgt":"Tak, chętnie, są pyszne.","lit":"oui · volontiers · sont · délicieux"},{"fr":"Tu bois du vin ou du jus ?","tgt":"Pijesz wino czy sok?","lit":"tu-bois · vin · ou · jus"},{"fr":"Juste de l'eau, je conduis ce soir.","tgt":"Tylko wodę, dziś prowadzę.","lit":"seulement · eau[acc.] · aujourd'hui · je-conduis"},{"fr":"La soupe aussi est très bonne.","tgt":"Zupa też jest bardzo dobra.","lit":"soupe · aussi · est · très · bonne"},{"fr":"C'est la recette de ma grand-mère.","tgt":"To przepis mojej babci.","lit":"c'est · recette · ma[gén.] · grand-mère[gén.]"},{"fr":"À notre santé !","tgt":"Na zdrowie!","lit":"sur · santé"}]},{"title":"Une soirée au café","phrases":[{"fr":"Ce café est très agréable.","tgt":"Ta kawiarnia jest bardzo przyjemna.","lit":"ce · café · est · très · agréable"},{"fr":"Il y a un peu de monde ce soir.","tgt":"Dziś wieczorem jest trochę ludzi.","lit":"aujourd'hui · le-soir · est · un-peu · de-gens"},{"fr":"La musique est trop forte.","tgt":"Muzyka jest za głośna.","lit":"musique · est · trop · forte"},{"fr":"On s'assoit un peu plus loin ?","tgt":"Siadamy trochę dalej?","lit":"nous-asseyons · un-peu · plus-loin"},{"fr":"Mon chocolat est trop chaud.","tgt":"Moja czekolada jest za gorąca.","lit":"mon · chocolat · est · trop · chaud"},{"fr":"Je suis un peu fatigué aujourd'hui.","tgt":"Jestem dziś trochę zmęczony.","lit":"je-suis · aujourd'hui · un-peu · fatigué"},{"fr":"Ce gâteau est très bon.","tgt":"To ciasto jest bardzo dobre.","lit":"ce · gâteau · est · très · bon"},{"fr":"C'est un peu trop cher pour moi.","tgt":"To jest trochę za drogie dla mnie.","lit":"ça · est · un-peu · trop · cher · pour · moi"},{"fr":"Je parle un petit peu polonais.","tgt":"Mówię trochę po polsku.","lit":"je-parle · un-peu · en · polonais"},{"fr":"Tu parles trop vite pour moi !","tgt":"Mówisz za szybko dla mnie!","lit":"tu-parles · trop · vite · pour · moi"}],"tip":{"title":"« Bardzo », « trochę », « za » : très, un peu, trop","example":"La musique est trop forte. — Muzyka jest <b>za</b> głośna.","body":"Trois petits mots permettent de doser tout ce que vous dites. « Bardzo », avec un « dz » léger, veut dire très : « bardzo dobre », très bon. « Trochę », à peu près « trohè », avec un h soufflé, veut dire un peu : « trochę zmęczony », un peu fatigué. Et « za », tout court, veut dire trop : « za głośna », trop forte. Ils se placent juste devant le mot qu'ils modifient, comme en français. Décomposons « muzyka jest za głośna » : « muzyka », la musique, « jest », est, « za », trop, « głośna », forte. On peut même les combiner : « trochę za drogie », un peu trop cher, exactement dans le même ordre qu'en français. Attention, « bardzo » sert aussi avec aimer : « bardzo lubię », j'aime beaucoup. Astuce : « za » est le plus court des trois, et c'est justement le mot pour dire qu'il y en a trop.","lit":"musique · est · trop · forte"}},{"title":"Parler de musique","phrases":[{"fr":"Quelle musique tu écoutes en ce moment ?","tgt":"Jakiej muzyki teraz słuchasz?","lit":"quelle[gén.] · musique[gén.] · maintenant · tu-écoutes"},{"fr":"J'écoute surtout du jazz.","tgt":"Słucham głównie jazzu.","lit":"j'écoute · surtout · jazz[gén.]"},{"fr":"Il y a un concert ce soir.","tgt":"Dziś wieczorem jest koncert.","lit":"aujourd'hui · le-soir · est · concert"},{"fr":"Il a lieu où ?","tgt":"A gdzie to jest?","lit":"et · où · ça · est"},{"fr":"Dans un petit club près de la place.","tgt":"W małym klubie koło Rynku.","lit":"dans · petit · club · près-de · place-du-marché[gén.]"},{"fr":"Tu joues toi-même d'un instrument ?","tgt":"Sam grasz na jakimś instrumencie?","lit":"toi-même · tu-joues · sur · quelque · instrument"},{"fr":"Je joue un peu de piano.","tgt":"Gram trochę na pianinie.","lit":"je-joue · un-peu · sur · piano"},{"fr":"Mon frère chante dans un groupe.","tgt":"Mój brat śpiewa w zespole.","lit":"mon · frère · chante · dans · groupe"},{"fr":"Les billets coûtent vingt złotys.","tgt":"Bilety kosztują dwadzieścia złotych.","lit":"billets · coûtent · vingt · złotys"},{"fr":"Alors on y va ensemble !","tgt":"To idziemy razem!","lit":"alors · nous-allons · ensemble"}]},{"title":"Sortir avec les autres","phrases":[{"fr":"Je vais au cinéma avec mon frère.","tgt":"Idę do kina z bratem.","lit":"je-vais · à · cinéma[gén.] · avec · frère[instr.]"},{"fr":"Tu sors avec nous ce soir ?","tgt":"Wychodzisz z nami wieczorem?","lit":"tu-sors · avec · nous[instr.] · le-soir"},{"fr":"Ce soir, je suis avec ma sœur.","tgt":"Dziś wieczorem jestem z siostrą.","lit":"aujourd'hui · le-soir · je-suis · avec · sœur[instr.]"},{"fr":"Elle peut venir avec nous ?","tgt":"Może przyjść z nami?","lit":"elle-peut · venir · avec · nous[instr.]"},{"fr":"Bien sûr, ta sœur est sympa.","tgt":"Jasne, twoja siostra jest fajna.","lit":"clair · ta · sœur · est · sympa"},{"fr":"Je parle souvent avec Marek.","tgt":"Często rozmawiam z Markiem.","lit":"souvent · je-parle · avec · Marek[instr.]"},{"fr":"Un café avec du lait, s'il vous plaît.","tgt":"Kawę z mlekiem, poproszę.","lit":"café[acc.] · avec · lait[instr.] · je-demande"},{"fr":"J'habite avec un ami.","tgt":"Mieszkam z kolegą.","lit":"j'habite · avec · ami[instr.]"},{"fr":"Tu habites avec ta copine ?","tgt":"Mieszkasz z dziewczyną?","lit":"tu-habites · avec · copine[instr.]"},{"fr":"Non, j'habite avec mes parents.","tgt":"Nie, mieszkam z rodzicami.","lit":"non · j'habite · avec · parents[instr.]"}],"tip":{"title":"« Z » + instrumental : avec quelqu'un, « z bratem »","example":"Je vais au cinéma avec mon frère. — Idę do kina <b>z bratem</b>.","body":"Pour dire avec, le polonais utilise un tout petit mot : « z », qu'on prononce simplement comme un « z » français. Mais après « z », le nom change de terminaison : c'est l'instrumental, la forme de l'accompagnement. Pour les mots masculins, on ajoute le son « em » : « brat », frère, devient « z bratem », avec mon frère, et « Marek » devient « z Markiem ». Pour les mots féminins en « a », on remplace le « a » par « ą », un son nasal proche de « on » : « siostra » devient « z siostrą », avec ma sœur. Décomposons « idę do kina z bratem » : « idę », je vais, « do kina », au cinéma, « z bratem », avec mon frère. Remarquez qu'on ne dit pas mon : en polonais, c'est compris. Avec nous se dit « z nami », avec mes parents « z rodzicami ». Astuce : « em » pour les garçons, « on » pour les filles, et le tour est joué.","lit":"je-vais · à · cinéma[gén.] · avec · frère[instr.]"}},{"title":"Un week-end à Wrocław","phrases":[{"fr":"Quels sont tes projets pour ce week-end ?","tgt":"Jakie masz plany na weekend?","lit":"quels · tu-as · projets · sur · week-end"},{"fr":"Samedi, je vais au zoo avec des amis.","tgt":"W sobotę idę do zoo z przyjaciółmi.","lit":"en · samedi · je-vais · à · zoo · avec · amis[instr.]"},{"fr":"Le zoo de Wrocław est immense.","tgt":"Wrocławskie zoo jest ogromne.","lit":"wrocławien · zoo · est · immense"},{"fr":"Dimanche, je me repose.","tgt":"W niedzielę odpoczywam.","lit":"en · dimanche · je-me-repose"},{"fr":"On fait un tour en bateau sur l'Oder ?","tgt":"Płyniemy statkiem po Odrze?","lit":"nous-naviguons · bateau[instr.] · sur · Oder"},{"fr":"Bonne idée, j'adore être sur l'eau.","tgt":"Dobry pomysł, uwielbiam pływać.","lit":"bonne · idée · j'adore · naviguer"},{"fr":"Et on se rejoint où, du coup ?","tgt":"To gdzie się spotykamy?","lit":"alors · où · se · nous-rencontrons"},{"fr":"Devant l'hôtel de ville, à midi.","tgt":"Przed ratuszem, w południe.","lit":"devant · hôtel-de-ville[instr.] · en · midi"},{"fr":"Je t'écris ce soir pour confirmer.","tgt":"Napiszę do ciebie wieczorem.","lit":"j'écrirai · à · toi · le-soir"},{"fr":"Passe un bon week-end !","tgt":"Miłego weekendu!","lit":"agréable[gén.] · week-end[gén.]"}]},{"title":"Un anniversaire entre amis","phrases":[{"fr":"Et toi, tu as quel âge ?","tgt":"A ty ile masz lat?","lit":"et · toi · combien · tu-as · d'années"},{"fr":"J'ai vingt-cinq ans.","tgt":"Mam dwadzieścia pięć lat.","lit":"j'ai · vingt · cinq · ans[lat]"},{"fr":"Mon frère a vingt-deux ans.","tgt":"Mój brat ma dwadzieścia dwa lata.","lit":"mon · frère · a · vingt · deux · ans[lata]"},{"fr":"Ma sœur a dix-neuf ans.","tgt":"Moja siostra ma dziewiętnaście lat.","lit":"ma · sœur · a · dix-neuf · ans[lat]"},{"fr":"C'est l'anniversaire d'Ola aujourd'hui.","tgt":"Ola ma dzisiaj urodziny.","lit":"Ola · a · aujourd'hui · anniversaire"},{"fr":"Elle a quel âge maintenant ?","tgt":"Ile ona ma teraz lat?","lit":"combien · elle · a · maintenant · d'années"},{"fr":"Elle a trente-trois ans.","tgt":"Ma trzydzieści trzy lata.","lit":"elle-a · trente · trois · ans[lata]"},{"fr":"Mon grand-père a quatre-vingts ans.","tgt":"Dziadek ma osiemdziesiąt lat.","lit":"grand-père · a · quatre-vingts · ans[lat]"},{"fr":"Ma nièce a quatre ans.","tgt":"Moja siostrzenica ma cztery lata.","lit":"ma · nièce · a · quatre · ans[lata]"},{"fr":"Joyeux anniversaire, Ola !","tgt":"Wszystkiego najlepszego, Olu!","lit":"tout[gén.] · meilleur[gén.] · Ola"}],"tip":{"title":"« Ile masz lat ? » : dire son âge avec « lat » et « lata »","example":"Mon frère a vingt-deux ans. — Mój brat ma dwadzieścia dwa <b>lata</b>.","body":"Comme en français, on « a » son âge en polonais : on utilise le verbe avoir. Pour demander l'âge d'un ami, on dit « ile masz lat ? », mot à mot « combien tu as d'années ? ». On répond « mam dwadzieścia pięć lat », j'ai vingt-cinq ans. Le mot ans change selon le nombre, et c'est la seule vraie difficulté. Après deux, trois et quatre, on dit « lata » : « dwa lata », deux ans, « cztery lata », quatre ans. Cela reste vrai pour vingt-deux, trente-trois ou quarante-quatre : « dwadzieścia dwa lata ». Pour tous les autres nombres, de cinq à vingt et un, puis vingt-cinq à trente et un, et ainsi de suite, on dit « lat » : « pięć lat », cinq ans. Et pour un an seulement, on dit « rok ». Astuce : si le nombre se termine par deux, trois ou quatre, ajoutez un « a » final, « lata » ; sinon, coupez court avec « lat ».","lit":"mon · frère · a · vingt · deux · ans[lata]"}},{"title":"Se dire au revoir","phrases":[{"fr":"Oh, il est déjà tard.","tgt":"Oj, już późno.","lit":"oh · déjà · tard"},{"fr":"Je dois rentrer chez moi.","tgt":"Muszę wracać do domu.","lit":"je-dois · rentrer · à · maison[gén.]"},{"fr":"Merci pour ce super dîner.","tgt":"Dziękuję za świetną kolację.","lit":"merci · pour · excellent · dîner[acc.]"},{"fr":"C'était vraiment super !","tgt":"Było naprawdę super!","lit":"c'était · vraiment · super"},{"fr":"Et on se revoit dans une semaine ?","tgt":"Widzimy się za tydzień?","lit":"nous-voyons · se · dans · semaine"},{"fr":"Oui, c'est sûr.","tgt":"Tak, na pewno.","lit":"oui · sur · sûr"},{"fr":"Bonne nuit et à bientôt !","tgt":"Dobranoc i do zobaczenia!","lit":"bonne-nuit · et · au · revoir"},{"fr":"Fais attention à toi en rentrant.","tgt":"Uważaj na siebie w drodze.","lit":"fais-attention · sur · toi-même · en · route"},{"fr":"Dis bonjour à tes parents pour moi.","tgt":"Pozdrów ode mnie rodziców.","lit":"salue · de · moi · parents[acc.]"},{"fr":"Allez, salut, à plus !","tgt":"No to cześć, na razie!","lit":"bon · alors · salut · pour · instant"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Bon, c'est la fin du module.","tgt":"No, to koniec modułu.","lit":"bon · c'est · fin · module[gén.]"},{"fr":"Je comprends déjà pas mal de choses en polonais.","tgt":"Rozumiem już sporo po polsku.","lit":"je-comprends · déjà · pas-mal · en · polonais"},{"fr":"Je sais me présenter, quand même !","tgt":"Przecież umiem się przedstawić!","lit":"pourtant · je-sais · se · présenter"},{"fr":"Je parle de ma famille et de mes loisirs.","tgt":"Mówię o rodzinie i o swoim hobby.","lit":"je-parle · de · famille · et · de · mon · hobby"},{"fr":"C'est justement ça, le but !","tgt":"Właśnie o to chodzi!","lit":"justement · de · ça · il-s'agit"},{"fr":"Le polonais, c'est difficile ?","tgt":"Polski jest trudny?","lit":"polonais · est · difficile"},{"fr":"Ben oui, un peu.","tgt":"No, trochę.","lit":"ben · un-peu"},{"fr":"Mais c'est un plaisir, après tout !","tgt":"Ale przecież to przyjemność!","lit":"mais · pourtant · c'est · plaisir"},{"fr":"Je pense justement au prochain module.","tgt":"Właśnie myślę o następnym module.","lit":"justement · je-pense · à · prochain · module"},{"fr":"Bon, alors on continue !","tgt":"No to jedziemy dalej!","lit":"bon · alors · nous-roulons · plus-loin"}],"tip":{"title":"Les petits mots de la conversation : « no », « przecież », « właśnie »","example":"Je sais me présenter, quand même ! — <b>Przecież</b> umiem się przedstawić!","body":"Pour parler comme un vrai Polonais, il faut quelques petits mots qui donnent de la couleur aux phrases. Le premier, « no », est partout : il veut dire bon, ben ou eh bien, et aussi un oui détendu entre amis. On l'entend en début de phrase : « no to jedziemy », bon, alors on y va. Le deuxième, « przecież », prononcé à peu près « pchétchiech », veut dire quand même ou mais enfin : on l'utilise pour rappeler une évidence. « Przecież umiem się przedstawić », mot à mot « pourtant je sais me présenter », c'est-à-dire je sais quand même me présenter ! Le troisième, « właśnie », prononcé « vouachnié », veut dire justement ou exactement. Pour approuver quelqu'un, dites simplement « no właśnie ! », exactement ! Astuce : glissez un « no » au début de vos phrases et un « właśnie » pour être d'accord, et vous aurez tout de suite l'air plus naturel.","lit":"pourtant · je-sais · se · présenter"}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"S'installer à Poznań","phrases":[{"fr":"J'habite à Poznań depuis trois mois.","tgt":"Mieszkam w Poznaniu od trzech miesięcy."},{"fr":"Mon appartement est tout près de la vieille ville.","tgt":"Moje mieszkanie jest niedaleko Starego Miasta."},{"fr":"Je bosse dans une boîte d'informatique.","tgt":"Pracuję w firmie informatycznej."},{"fr":"Le matin, je bois mon café sur le balcon.","tgt":"Rano piję kawę na balkonie."},{"fr":"Cette ville me plaît énormément.","tgt":"To miasto bardzo mi się podoba."},{"fr":"Les gens d'ici sont très aimables.","tgt":"Ludzie są tu bardzo mili."},{"fr":"Je cherche toujours un bon coiffeur.","tgt":"Wciąż szukam dobrego fryzjera."},{"fr":"Mes voisins m'ont déjà invité à dîner.","tgt":"Sąsiedzi już zaprosili mnie na kolację."},{"fr":"Dans quel quartier habitez-vous ?","tgt":"W jakiej dzielnicy pan mieszka?"},{"fr":"Je commence à parler un peu polonais.","tgt":"Zaczynam trochę mówić po polsku."}]},{"title":"Le week-end dernier au lac Malta","phrases":[{"fr":"Samedi, j'étais au lac Malta.","tgt":"W sobotę byłem nad Maltą."},{"fr":"J'ai couru dix kilomètres autour du lac.","tgt":"Przebiegłem dziesięć kilometrów dookoła jeziora."},{"fr":"Il faisait beau et chaud.","tgt":"Było ładnie i ciepło."},{"fr":"Ma femme était avec moi.","tgt":"Moja żona była ze mną."},{"fr":"Ma collègue m'a dit : « Moi aussi, j'étais au lac. »","tgt":"Koleżanka powiedziała mi: „Ja też byłam nad jeziorem”."},{"fr":"Après la course, nous avons mangé une glace.","tgt":"Po bieganiu zjedliśmy lody."},{"fr":"Où étiez-vous dimanche ?","tgt":"Gdzie pan był w niedzielę?"},{"fr":"Moi, j'étais à la maison toute la journée.","tgt":"Ja cały dzień byłem w domu."},{"fr":"Le soir, nous avons regardé un film.","tgt":"Wieczorem oglądaliśmy film."},{"fr":"C'était un très bon week-end.","tgt":"To był bardzo dobry weekend."}],"tip":{"title":"Le passé : « byłem », « byłam », le verbe s'accorde au genre","example":"Samedi, j'étais au lac Malta. — W sobotę <b>byłem</b> nad Maltą.","body":"Pour parler du passé en polonais, le verbe dit qui parle, mais aussi si c'est un homme ou une femme. Un homme dit « byłem », j'étais, et une femme dit « byłam ». Prenez « w sobotę byłem nad Maltą » : mot à mot, le samedi, j'étais, au bord de, Malta. Le « ł » se prononce comme un « ou » très bref, donc « byłem » sonne un peu comme « bi-ouèm ». Cela marche avec tous les verbes : « robiłem », je faisais, pour un homme, « robiłam » pour une femme, et aussi « był », il était, « była », elle était. Pour retenir : le « a » final, comme dans « pani », signale presque toujours le féminin.","lit":"le samedi · j'étais (homme) · au bord de · Malta"}},{"title":"Les chèvres de l'hôtel de ville","phrases":[{"fr":"À midi, tout le monde regarde la tour de l'hôtel de ville.","tgt":"W południe wszyscy patrzą na wieżę ratusza."},{"fr":"Deux chèvres mécaniques sortent et se donnent des coups de tête.","tgt":"Dwa mechaniczne koziołki wychodzą i trykają się rogami."},{"fr":"Elles se cognent douze fois.","tgt":"Trykają się dwanaście razy."},{"fr":"Sur la place, il y a toujours plein de touristes.","tgt":"Na rynku zawsze jest dużo turystów."},{"fr":"Je suis venu ici avec des amis de France.","tgt":"Przyszedłem tu z przyjaciółmi z Francji."},{"fr":"Ils ont pris une foule de photos.","tgt":"Zrobili mnóstwo zdjęć."},{"fr":"Ensuite, nous avons bu un café sur la place.","tgt":"Potem wypiliśmy kawę na rynku."},{"fr":"Les maisons colorées de la place sont superbes.","tgt":"Kolorowe kamienice na rynku są piękne."},{"fr":"À quelle heure sortent les chèvres ?","tgt":"O której wychodzą koziołki?"},{"fr":"Mes amis ne connaissaient pas cette légende.","tgt":"Moi przyjaciele nie znali tej legendy."}]},{"title":"Le marché de Jeżyce","phrases":[{"fr":"Le samedi matin, je fais les courses au marché de Jeżyce.","tgt":"W sobotę rano robię zakupy na Rynku Jeżyckim."},{"fr":"Je voudrais un kilo de pommes, s'il vous plaît.","tgt":"Poproszę kilogram jabłek."},{"fr":"Combien coûtent ces fraises ?","tgt":"Ile kosztują te truskawki?"},{"fr":"Douze złotys le kilo.","tgt":"Dwanaście złotych za kilogram."},{"fr":"D'où viennent ces tomates ?","tgt":"Skąd są te pomidory?"},{"fr":"Je prendrais aussi un peu de fromage blanc.","tgt":"Chciałbym jeszcze trochę twarogu."},{"fr":"La vendeuse m'a rajouté un bouquet d'aneth.","tgt":"Sprzedawczyni dorzuciła mi pęczek koperku."},{"fr":"J'ai laissé mon sac à la maison.","tgt":"Zostawiłem torbę w domu."},{"fr":"Vous pourriez me donner un sachet ?","tgt":"Czy może mi pani dać torebkę?"},{"fr":"Ici, tout est plus frais qu'au supermarché.","tgt":"Tutaj wszystko jest świeższe niż w supermarkecie."}]},{"title":"Une journée en open space","phrases":[{"fr":"Je travaille dans un grand bureau ouvert.","tgt":"Pracuję w dużym, otwartym biurze."},{"fr":"Le matin, je fais toujours la liste des tâches.","tgt":"Rano zawsze robię listę zadań."},{"fr":"Aujourd'hui, j'ai fait la liste très vite.","tgt":"Dzisiaj zrobiłem listę bardzo szybko."},{"fr":"Et vous, qu'est-ce que vous faites, là ?","tgt":"A pan co teraz robi?"},{"fr":"Je prépare une présentation pour le client.","tgt":"Robię prezentację dla klienta."},{"fr":"Vous avez déjà fini le rapport ?","tgt":"Zrobił pan już raport?"},{"fr":"Non, à six heures, j'étais encore en train de le faire.","tgt":"Nie, o szóstej jeszcze go robiłem."},{"fr":"Mon collègue a fait du café pour tout le monde.","tgt":"Kolega zrobił kawę dla wszystkich."},{"fr":"Il y a trop de bruit, je n'arrive pas à me concentrer.","tgt":"Jest za głośno, nie mogę się skupić."},{"fr":"Finalement, j'ai tout fait avant cinq heures.","tgt":"W końcu zrobiłem wszystko przed piątą."}],"tip":{"title":"Les deux aspects : « robić » et « zrobić »","example":"Aujourd'hui, j'ai fait la liste très vite. — Dzisiaj <b>zrobiłem</b> listę bardzo szybko.","body":"En polonais, la plupart des verbes vont par paires. « Robić » parle de l'action en cours ou habituelle, un peu comme notre imparfait : je faisais, j'étais en train de faire. « Zrobić » parle de l'action terminée, avec un résultat : j'ai fait, c'est fini. Dans « dzisiaj zrobiłem listę », mot à mot aujourd'hui, j'ai fait jusqu'au bout, la liste, le petit « z » du début annonce que la liste est terminée. Comparez « robiłem raport », je travaillais sur le rapport, et « zrobiłem raport », le rapport est bouclé. Astuce : quand vous voulez dire c'est fait, ajoutez le petit préfixe, comme un tampon posé sur la tâche.","lit":"aujourd'hui · j'ai fait (jusqu'au bout) · liste · très · vite"}},{"title":"Des projets pour samedi","phrases":[{"fr":"Samedi, je vais cuisiner toute la journée.","tgt":"W sobotę będę gotować cały dzień."},{"fr":"Le matin, j'irai au marché.","tgt":"Rano pójdę na targ."},{"fr":"J'achèterai des champignons et des pommes de terre.","tgt":"Kupię grzyby i ziemniaki."},{"fr":"Ensuite, je ferai une soupe aux champignons.","tgt":"Potem zrobię zupę grzybową."},{"fr":"L'après-midi, je vais faire le ménage dans l'appartement.","tgt":"Po południu będę sprzątać mieszkanie."},{"fr":"Le soir, mes amis viendront dîner.","tgt":"Wieczorem przyjaciele przyjdą na kolację."},{"fr":"Qu'est-ce que vous allez faire ce week-end ?","tgt":"Co pan będzie robić w ten weekend?"},{"fr":"Je vais travailler un peu depuis chez moi.","tgt":"Będę trochę pracować z domu."},{"fr":"Et dimanche, je vais me reposer.","tgt":"W niedzielę będę odpoczywać."},{"fr":"Je vous appellerai demain matin.","tgt":"Zadzwonię do pana jutro rano."}],"tip":{"title":"Le futur : « będę » + infinitif, et le perfectif qui regarde vers demain","example":"Samedi, je vais cuisiner toute la journée. — W sobotę <b>będę</b> <b>gotować</b> cały dzień.","body":"Pour une action qui va durer ou se répéter, le polonais utilise « będę », je serai, suivi de l'infinitif : « będę gotować », je vais cuisiner. Mot à mot, « w sobotę będę gotować cały dzień » donne : le samedi, je serai, cuisiner, toute la journée. Pour une action ponctuelle qu'on va mener à son terme, c'est encore plus simple : on conjugue le verbe perfectif comme au présent, et il prend un sens futur. Ainsi « kupię » veut dire j'achèterai, et « zrobię », je ferai. Retenez l'image : « będę » pour le film qui se déroule, le verbe perfectif pour la photo finale de demain.","lit":"le samedi · je serai · cuisiner · toute · journée"}},{"title":"Des pyzy faits maison","phrases":[{"fr":"Ce soir, je fais des pyzy pour la première fois.","tgt":"Dziś wieczorem pierwszy raz robię pyzy."},{"fr":"Les pyzy sont des boulettes de pâte levée cuites à la vapeur.","tgt":"Pyzy to drożdżowe kluski gotowane na parze."},{"fr":"Ma voisine m'a donné sa recette.","tgt":"Sąsiadka dała mi swój przepis."},{"fr":"Il faut de la farine, du lait et de la levure.","tgt":"Potrzeba mąki, mleka i drożdży."},{"fr":"La pâte doit lever pendant une heure.","tgt":"Ciasto musi rosnąć przez godzinę."},{"fr":"J'ai mis beaucoup trop de farine.","tgt":"Dodałem za dużo mąki."},{"fr":"On les mange avec de la viande et de la sauce.","tgt":"Je się je z mięsem i sosem."},{"fr":"Mes pyzy sont un peu trop petits.","tgt":"Moje pyzy są trochę za małe."},{"fr":"Vous avez déjà goûté des pyzy ?","tgt":"Jadł pan już kiedyś pyzy?"},{"fr":"La prochaine fois, ça ira mieux.","tgt":"Następnym razem będzie lepiej."}]},{"title":"La soupe aux champignons","phrases":[{"fr":"En automne, je ramasse des champignons dans la forêt.","tgt":"Jesienią zbieram grzyby w lesie."},{"fr":"Hier, j'en ai rapporté un panier plein.","tgt":"Wczoraj przyniosłem pełny koszyk."},{"fr":"Ma grand-mère faisait la meilleure soupe aux champignons.","tgt":"Babcia robiła najlepszą zupę grzybową."},{"fr":"Je fais la soupe selon sa recette.","tgt":"Gotuję zupę według jej przepisu."},{"fr":"D'abord, je fais tremper les champignons secs.","tgt":"Najpierw moczę suszone grzyby."},{"fr":"La soupe doit cuire une demi-heure.","tgt":"Zupa musi się gotować pół godziny."},{"fr":"Toute la cuisine sent bon.","tgt":"W całej kuchni pięknie pachnie."},{"fr":"Vous voulez goûter ?","tgt":"Chce pan spróbować?"},{"fr":"Il manque un peu de sel.","tgt":"Brakuje trochę soli."},{"fr":"C'est la meilleure soupe que j'aie jamais mangée.","tgt":"To najlepsza zupa, jaką kiedykolwiek jadłem."}]},{"title":"Le vélo en ville","phrases":[{"fr":"Je vais au travail à vélo.","tgt":"Jeżdżę do pracy rowerem."},{"fr":"À Poznań, il y a beaucoup de pistes cyclables.","tgt":"W Poznaniu jest dużo ścieżek rowerowych."},{"fr":"J'ai loué un vélo de la ville.","tgt":"Wypożyczyłem miejski rower."},{"fr":"Le trajet prend vingt minutes.","tgt":"Droga zajmuje dwadzieścia minut."},{"fr":"Quand il pleut, je prends le tram.","tgt":"Kiedy pada, jadę tramwajem."},{"fr":"Ce matin, j'ai failli tomber.","tgt":"Dziś rano prawie się przewróciłem."},{"fr":"Il faut faire attention aux piétons.","tgt":"Trzeba uważać na pieszych."},{"fr":"Où est-ce que je peux laisser mon vélo ?","tgt":"Gdzie mogę zostawić rower?"},{"fr":"Mon casque est trop petit.","tgt":"Mój kask jest za mały."},{"fr":"À vélo, j'arrive plus vite qu'en voiture.","tgt":"Rowerem dojeżdżam szybciej niż samochodem."}]},{"title":"Une panne à la maison","phrases":[{"fr":"Ma machine à laver ne marche plus.","tgt":"Moja pralka już nie działa."},{"fr":"Hier, l'eau a coulé dans toute la salle de bains.","tgt":"Wczoraj woda wylała się na całą łazienkę."},{"fr":"J'ai appelé un plombier.","tgt":"Zadzwoniłem po hydraulika."},{"fr":"Il viendra jeudi après-midi.","tgt":"Przyjdzie w czwartek po południu."},{"fr":"Combien va coûter la réparation ?","tgt":"Ile będzie kosztować naprawa?"},{"fr":"Il faut changer une pièce.","tgt":"Trzeba wymienić jedną część."},{"fr":"En attendant, je lave mes vêtements à la main.","tgt":"Na razie piorę ubrania ręcznie."},{"fr":"La voisine m'a proposé sa machine.","tgt":"Sąsiadka zaproponowała mi swoją pralkę."},{"fr":"C'est très gentil de votre part, madame.","tgt":"To bardzo miło z pani strony."},{"fr":"Enfin, tout fonctionne de nouveau.","tgt":"Wreszcie wszystko znowu działa."}]},{"title":"Chez le médecin","phrases":[{"fr":"Depuis hier, j'ai mal à la gorge.","tgt":"Od wczoraj boli mnie gardło."},{"fr":"J'ai pris rendez-vous chez le médecin.","tgt":"Umówiłem się do lekarza."},{"fr":"Est-ce que vous avez de la température ?","tgt":"Czy ma pan gorączkę?"},{"fr":"Ce matin, j'avais trente-huit de fièvre.","tgt":"Rano miałem trzydzieści osiem stopni."},{"fr":"Le médecin m'a examiné.","tgt":"Lekarz mnie zbadał."},{"fr":"Ce n'est qu'un rhume.","tgt":"To tylko przeziębienie."},{"fr":"Il faut boire beaucoup de thé chaud.","tgt":"Trzeba pić dużo ciepłej herbaty."},{"fr":"Il m'a prescrit un sirop.","tgt":"Przepisał mi syrop."},{"fr":"La pharmacie est juste en face.","tgt":"Apteka jest naprzeciwko."},{"fr":"Dans trois jours, j'irai mieux.","tgt":"Za trzy dni poczuję się lepiej."}]},{"title":"Aller au travail : à pied ou en tram","phrases":[{"fr":"Aujourd'hui, je vais au travail à pied.","tgt":"Dzisiaj idę do pracy pieszo."},{"fr":"Demain, j'irai en tram.","tgt":"Jutro pojadę tramwajem."},{"fr":"Où allez-vous, monsieur ?","tgt":"Dokąd pan idzie?"},{"fr":"Je vais à la boulangerie du coin.","tgt":"Idę do piekarni na rogu."},{"fr":"Ma femme va à Varsovie en train.","tgt":"Żona jedzie pociągiem do Warszawy."},{"fr":"Dimanche, nous allons au lac Malta à vélo.","tgt":"W niedzielę jedziemy nad Maltę rowerem."},{"fr":"Je marche lentement, je ne suis pas pressé.","tgt":"Idę powoli, nie spieszę się."},{"fr":"Ce bus va directement à la vieille ville ?","tgt":"Czy ten autobus jedzie prosto na Stare Miasto?"},{"fr":"Vous y allez en voiture ou à pied ?","tgt":"Jedzie pan samochodem czy idzie pan pieszo?"},{"fr":"Quand il fait beau, je préfère y aller à pied.","tgt":"Kiedy jest ładna pogoda, wolę iść pieszo."}],"tip":{"title":"Les verbes de mouvement : « iść » à pied et « jechać » en véhicule","example":"Vous y allez en voiture ou à pied ? — <b>Jedzie</b> pan samochodem czy <b>idzie</b> pan pieszo?","body":"Le polonais fait une différence que le français ignore : la façon dont on se déplace. « Iść » veut dire aller à pied, et « jechać » aller en véhicule, que ce soit en tram, en voiture, à vélo ou en train. On dit donc « idę do pracy », je vais au travail à pied, mais « jadę tramwajem », je vais en tram. Dans « jedzie pan samochodem czy idzie pan pieszo », mot à mot : roulez, monsieur, en voiture, ou marchez, monsieur, à pied. Avant de dire aller, posez-vous une seule question : est-ce que mes pieds touchent le sol ? Si oui, « idę », sinon « jadę ».","lit":"roulez · monsieur · en voiture · ou · marchez · monsieur · à pied"}},{"title":"Courir autour du lac Malta","phrases":[{"fr":"Je vais courir trois fois par semaine.","tgt":"Biegam trzy razy w tygodniu."},{"fr":"Autour du lac, il y a un joli parcours.","tgt":"Dookoła jeziora jest ładna trasa."},{"fr":"Le tour complet fait environ cinq kilomètres.","tgt":"Całe okrążenie ma około pięciu kilometrów."},{"fr":"Je me lève à six heures pour aller courir.","tgt":"Wstaję o szóstej, żeby pobiegać."},{"fr":"Au début, je courais très lentement.","tgt":"Na początku biegałem bardzo wolno."},{"fr":"Maintenant, je fais tout le tour en trente minutes.","tgt":"Teraz przebiegam całe okrążenie w trzydzieści minut."},{"fr":"L'hiver, on peut skier juste à côté.","tgt":"Zimą tuż obok można jeździć na nartach."},{"fr":"Vous voulez courir avec moi samedi ?","tgt":"Chce pan pobiegać ze mną w sobotę?"},{"fr":"Après avoir couru, j'ai toujours très faim.","tgt":"Po bieganiu zawsze jestem bardzo głodny."},{"fr":"En mai, je participerai à un semi-marathon.","tgt":"W maju wezmę udział w półmaratonie."}]},{"title":"Un dîner entre collègues","phrases":[{"fr":"Vendredi, j'ai invité mes collègues à dîner.","tgt":"W piątek zaprosiłem kolegów z pracy na kolację."},{"fr":"J'ai préparé des pierogi au fromage et aux pommes de terre.","tgt":"Zrobiłem pierogi ruskie."},{"fr":"Ania a apporté un gâteau.","tgt":"Ania przyniosła ciasto."},{"fr":"Marek est arrivé avec une heure de retard.","tgt":"Marek spóźnił się godzinę."},{"fr":"Servez-vous, ne vous gênez pas !","tgt":"Częstujcie się, śmiało!"},{"fr":"Qui veut encore du thé ?","tgt":"Kto chce jeszcze herbaty?"},{"fr":"Nous avons parlé boulot toute la soirée.","tgt":"Cały wieczór rozmawialiśmy o pracy."},{"fr":"Puis nous avons joué aux cartes.","tgt":"Potem graliśmy w karty."},{"fr":"Tout le monde est parti vers minuit.","tgt":"Wszyscy wyszli około północy."},{"fr":"C'était une soirée très réussie.","tgt":"To był bardzo udany wieczór."}]},{"title":"Un dimanche tranquille","phrases":[{"fr":"Le dimanche, je me lève tard.","tgt":"W niedzielę wstaję późno."},{"fr":"Je prépare un grand petit-déjeuner.","tgt":"Robię duże śniadanie."},{"fr":"Des œufs, du pain frais et du fromage.","tgt":"Jajka, świeże pieczywo i ser."},{"fr":"Ensuite, je lis un livre sur le canapé.","tgt":"Potem czytam książkę na kanapie."},{"fr":"Parfois, j'appelle mes parents en France.","tgt":"Czasem dzwonię do rodziców we Francji."},{"fr":"L'après-midi, je me promène dans le parc.","tgt":"Po południu spaceruję po parku."},{"fr":"Le parc Sołacki est mon préféré.","tgt":"Park Sołacki to mój ulubiony park."},{"fr":"Le soir, je prépare mon sac pour lundi.","tgt":"Wieczorem pakuję torbę na poniedziałek."},{"fr":"Je ne regarde presque jamais la télévision.","tgt":"Prawie nie oglądam telewizji."},{"fr":"J'adore ces dimanches calmes.","tgt":"Uwielbiam takie spokojne niedziele."}]},{"title":"Réparer son vélo","phrases":[{"fr":"Mon pneu arrière est crevé.","tgt":"Mam przebitą tylną oponę."},{"fr":"Je ne sais pas réparer un vélo.","tgt":"Nie umiem naprawić roweru."},{"fr":"Mon voisin m'a montré comment faire.","tgt":"Sąsiad pokazał mi, jak to zrobić."},{"fr":"D'abord, il faut enlever la roue.","tgt":"Najpierw trzeba zdjąć koło."},{"fr":"Vous avez une pompe ?","tgt":"Ma pan pompkę?"},{"fr":"La chaîne est très sale.","tgt":"Łańcuch jest bardzo brudny."},{"fr":"Les freins ne marchent pas bien.","tgt":"Hamulce słabo działają."},{"fr":"Je vais apporter le vélo à l'atelier.","tgt":"Zawiozę rower do serwisu."},{"fr":"Le mécanicien a tout changé en une heure.","tgt":"Mechanik wszystko wymienił w godzinę."},{"fr":"Maintenant, mon vélo roule comme un neuf.","tgt":"Teraz mój rower jeździ jak nowy."}]},{"title":"Une démarche à la mairie","phrases":[{"fr":"Je dois déclarer ma nouvelle adresse.","tgt":"Muszę się zameldować pod nowym adresem."},{"fr":"Où se trouve le guichet numéro quatre ?","tgt":"Gdzie jest okienko numer cztery?"},{"fr":"J'ai attendu presque une heure.","tgt":"Czekałem prawie godzinę."},{"fr":"Il me manque un document.","tgt":"Brakuje mi jednego dokumentu."},{"fr":"Vous pouvez revenir demain ?","tgt":"Może pan przyjść jutro?"},{"fr":"Il faut remplir ce formulaire.","tgt":"Trzeba wypełnić ten formularz."},{"fr":"Je n'ai pas de stylo, vous en avez un ?","tgt":"Nie mam długopisu, ma pani jakiś?"},{"fr":"L'employée était très patiente.","tgt":"Urzędniczka była bardzo cierpliwa."},{"fr":"Combien de temps faut-il attendre ?","tgt":"Jak długo trzeba czekać?"},{"fr":"Tout est réglé, merci beaucoup.","tgt":"Wszystko załatwione, dziękuję bardzo."}]},{"title":"Organiser un anniversaire","phrases":[{"fr":"Samedi, c'est l'anniversaire de ma femme.","tgt":"W sobotę są urodziny mojej żony."},{"fr":"Je veux lui faire une surprise.","tgt":"Chcę jej zrobić niespodziankę."},{"fr":"J'ai réservé une table dans un restaurant de la vieille ville.","tgt":"Zarezerwowałem stolik w restauracji na Starym Mieście."},{"fr":"J'ai invité ses meilleures amies.","tgt":"Zaprosiłem jej najlepsze przyjaciółki."},{"fr":"Personne ne doit rien lui dire.","tgt":"Nikt nie może jej nic powiedzieć."},{"fr":"Qu'est-ce que je pourrais lui offrir ?","tgt":"Co mógłbym jej dać w prezencie?"},{"fr":"Elle adore les livres et les fleurs.","tgt":"Ona uwielbia książki i kwiaty."},{"fr":"J'ai commandé un gâteau au chocolat.","tgt":"Zamówiłem tort czekoladowy."},{"fr":"Elle a été vraiment surprise.","tgt":"Była naprawdę zaskoczona."},{"fr":"Joyeux anniversaire, ma chérie !","tgt":"Wszystkiego najlepszego, kochanie!"}]},{"title":"Conseils à un ami qui vient à Poznań","phrases":[{"fr":"Viens me voir à Poznań !","tgt":"Przyjedź do mnie do Poznania!"},{"fr":"À la gare, monte dans le tram.","tgt":"Na dworcu wsiądź do tramwaju."},{"fr":"Va voir les chèvres à midi.","tgt":"Idź zobaczyć koziołki w południe."},{"fr":"Ne sois pas en retard, ça ne dure pas longtemps.","tgt":"Nie spóźniaj się, to trwa krótko."},{"fr":"Fais une photo de la place pour moi.","tgt":"Zrób dla mnie zdjęcie rynku."},{"fr":"Ne fais pas de bruit, le bébé dort.","tgt":"Nie rób hałasu, dziecko śpi."},{"fr":"Goûte absolument les pyzy.","tgt":"Koniecznie spróbuj pyz."},{"fr":"N'achète pas de souvenirs sur la place, ils sont trop chers.","tgt":"Nie kupuj pamiątek na rynku, są za drogie."},{"fr":"Va au lac Malta si tu aimes courir.","tgt":"Jedź nad Maltę, jeśli lubisz biegać."},{"fr":"Appelle-moi quand tu arrives.","tgt":"Zadzwoń, jak dojedziesz."}],"tip":{"title":"L'impératif : « zrób », « idź », et la défense avec « nie rób »","example":"Fais une photo de la place pour moi. — <b>Zrób</b> dla mnie zdjęcie rynku.","body":"Pour donner un conseil ou un ordre à un ami, on raccourcit le verbe. « Zrób » veut dire fais, « idź », va à pied, « jedź », va en véhicule, et « zadzwoń », appelle. Dans « zrób dla mnie zdjęcie rynku », mot à mot : fais, pour, moi, photo, de la place. Pour interdire, on met « nie » devant, mais on prend en général le verbe de l'action en cours : on dit « nie rób », ne fais pas, et presque jamais « nie zrób ». De même, « nie kupuj », n'achète pas. Astuce : le conseil vise un résultat, donc la forme qui termine, et l'interdiction vise l'action elle-même, donc la forme qui dure.","lit":"fais · pour · moi · photo · [de la] place"}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module m'a beaucoup appris.","tgt":"Ten moduł dużo mnie nauczył."},{"fr":"Maintenant, je sais parler du passé.","tgt":"Teraz umiem mówić o przeszłości."},{"fr":"Je peux aussi dire ce que je ferai demain.","tgt":"Mogę też powiedzieć, co zrobię jutro."},{"fr":"Je confonds encore parfois les deux aspects.","tgt":"Czasem jeszcze mylę oba aspekty."},{"fr":"La différence entre « iść » et « jechać » est logique.","tgt":"Różnica między „iść” a „jechać” jest logiczna."},{"fr":"Le polonais devient plus facile pour moi.","tgt":"Polski staje się dla mnie łatwiejszy."},{"fr":"J'ai appris beaucoup de mots de cuisine.","tgt":"Nauczyłem się dużo słów o gotowaniu."},{"fr":"Chaque matin, je répète les phrases dans le tram.","tgt":"Codziennie rano powtarzam zdania w tramwaju."},{"fr":"Mes voisins disent que je parle de mieux en mieux.","tgt":"Sąsiedzi mówią, że mówię coraz lepiej."},{"fr":"Je suis prêt pour le module suivant.","tgt":"Jestem gotowy na następny moduł."}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Gdańsk","phrases":[{"fr":"Le train arrive à Gdańsk dans dix minutes.","tgt":"Pociąg przyjeżdża do Gdańska za dziesięć minut."},{"fr":"J'ai voyagé toute la nuit depuis Cracovie.","tgt":"Jechałem całą noc z Krakowa."},{"fr":"Je suis un peu fatigué, mais très content d'être là.","tgt":"Jestem trochę zmęczony, ale bardzo się cieszę, że tu jestem."},{"fr":"Excusez-moi, où est la station de taxis ?","tgt":"Przepraszam, gdzie jest postój taksówek?"},{"fr":"Notre hôtel se trouve près de la vieille ville.","tgt":"Nasz hotel jest niedaleko Starego Miasta."},{"fr":"On peut y aller à pied en quinze minutes.","tgt":"Można tam dojść pieszo w piętnaście minut."},{"fr":"J'ai réservé une chambre pour quatre nuits.","tgt":"Zarezerwowałem pokój na cztery noce."},{"fr":"La gare elle-même est vraiment belle.","tgt":"Sam dworzec jest naprawdę ładny."},{"fr":"On sent déjà l'odeur de la mer.","tgt":"Już czuć zapach morza."},{"fr":"Enfin à Gdańsk !","tgt":"Nareszcie w Gdańsku!"}]},{"title":"Flâner sur la rue Longue","phrases":[{"fr":"Nous nous promenons sur la rue Longue.","tgt":"Spacerujemy ulicą Długą."},{"fr":"Les façades des maisons sont très colorées.","tgt":"Fasady kamienic są bardzo kolorowe."},{"fr":"Hier soir, il y avait un monde fou ici.","tgt":"Wczoraj wieczorem było tu mnóstwo ludzi."},{"fr":"Ce bâtiment ressemble à un petit palais.","tgt":"Ten budynek wygląda jak mały pałac."},{"fr":"Regarde ce musicien de rue !","tgt":"Spójrz na tego ulicznego muzyka!"},{"fr":"On a bu un café sur une terrasse.","tgt":"Wypiliśmy kawę w kawiarnianym ogródku."},{"fr":"Cette rue mène tout droit jusqu'à la rivière.","tgt":"Ta ulica prowadzi prosto nad rzekę."},{"fr":"Pourriez-vous nous prendre en photo ?","tgt":"Czy mógłby pan zrobić nam zdjęcie?"},{"fr":"Bien sûr, souriez !","tgt":"Oczywiście, proszę się uśmiechnąć!"},{"fr":"Je n'avais jamais vu une rue aussi belle.","tgt":"Nigdy nie widziałem tak pięknej ulicy."}]},{"title":"Arrivées et départs","phrases":[{"fr":"Nous sommes arrivés à Gdańsk avant-hier.","tgt":"Przyjechaliśmy do Gdańska przedwczoraj."},{"fr":"Mes amis arrivent de Varsovie demain matin.","tgt":"Moi przyjaciele przyjadą jutro rano z Warszawy."},{"fr":"Quand partez-vous de l'hôtel ?","tgt":"Kiedy wyjeżdża pan z hotelu?"},{"fr":"Nous quittons Gdańsk dimanche.","tgt":"Wyjeżdżamy z Gdańska w niedzielę."},{"fr":"Demain, nous irons à Sopot.","tgt":"Jutro pojedziemy do Sopotu."},{"fr":"Ma sœur est déjà partie à la plage.","tgt":"Moja siostra już pojechała na plażę."},{"fr":"Le bus part à huit heures précises.","tgt":"Autobus odjeżdża punktualnie o ósmej."},{"fr":"À quelle heure arrive le train de Gdynia ?","tgt":"O której przyjeżdża pociąg z Gdyni?"},{"fr":"Partons plus tôt pour éviter les bouchons.","tgt":"Wyjedźmy wcześniej, żeby uniknąć korków."},{"fr":"Je suis venu ici pour voir la mer.","tgt":"Przyjechałem tutaj, żeby zobaczyć morze."}],"tip":{"title":"Les préfixes de mouvement : « przyjechać », « wyjechać », « pojechać »","example":"Nous sommes arrivés à Gdańsk avant-hier. — <b>Przyjechaliśmy</b> do Gdańska przedwczoraj.","body":"En polonais, on part d'un seul verbe, « jechać », aller en véhicule, et on lui colle un petit préfixe qui donne la direction. « Przy » veut dire arriver, venir jusqu'ici : « przyjechałem », je suis arrivé. « Wy » veut dire sortir, partir d'un endroit : « wyjeżdżam jutro », je pars demain. « Po » veut simplement dire se mettre en route, aller une fois quelque part : « pojedziemy do Sopotu », nous irons à Sopot. Décomposez « przyjechaliśmy » : « przy », arrivée, « jecha », rouler, « liśmy », nous au passé. Astuce pour retenir : « przy » ressemble à « près », on arrive près de vous, et « wy » sonne comme une sortie, on s'en va.","lit":"nous-sommes-arrivés · à · Gdańsk [génitif] · avant-hier"}},{"title":"La grue sur la Motława","phrases":[{"fr":"Voici la célèbre grue de Gdańsk.","tgt":"Oto słynny gdański Żuraw."},{"fr":"Autrefois, elle servait à charger les marchandises sur les navires.","tgt":"Dawniej służył do ładowania towarów na statki."},{"fr":"Aujourd'hui, elle fait partie d'un musée maritime.","tgt":"Dziś jest częścią muzeum morskiego."},{"fr":"Les quais de la Motława sont pleins de restaurants.","tgt":"Nabrzeże Motławy jest pełne restauracji."},{"fr":"Le soir, les lumières se reflètent dans l'eau.","tgt":"Wieczorem światła odbijają się w wodzie."},{"fr":"On pourrait faire une croisière sur la rivière.","tgt":"Moglibyśmy wybrać się w rejs po rzece."},{"fr":"Un bateau d'excursion part toutes les heures.","tgt":"Statek wycieczkowy odpływa co godzinę."},{"fr":"Combien coûte un billet pour la croisière ?","tgt":"Ile kosztuje bilet na rejs?"},{"fr":"Trente złotys par personne, les enfants paient la moitié.","tgt":"Trzydzieści złotych od osoby, dzieci płacą połowę."},{"fr":"Cette vue sur la vieille ville est magnifique.","tgt":"Ten widok na Stare Miasto jest wspaniały."}]},{"title":"Les habitudes du voyageur","phrases":[{"fr":"Chaque matin, je vais me promener au bord de la rivière.","tgt":"Codziennie rano chodzę na spacer nad rzekę."},{"fr":"En ce moment, je vais à la boulangerie.","tgt":"Teraz idę do piekarni."},{"fr":"Où allez-vous comme ça, monsieur ?","tgt":"Dokąd pan idzie?"},{"fr":"Je vais au marché aux poissons.","tgt":"Idę na targ rybny."},{"fr":"Le soir, nous allons souvent à la plage.","tgt":"Wieczorami często chodzimy na plażę."},{"fr":"Ici, tout le monde va partout à pied.","tgt":"Tutaj wszyscy chodzą wszędzie pieszo."},{"fr":"Aujourd'hui, nous allons au musée de l'ambre.","tgt":"Dzisiaj idziemy do Muzeum Bursztynu."},{"fr":"Vous allez souvent au bord de la mer, madame ?","tgt":"Czy często chodzi pani nad morze?"},{"fr":"Je n'aime pas marcher sous la pluie.","tgt":"Nie lubię chodzić w deszczu."},{"fr":"Où vas-tu avec ce grand sac ?","tgt":"Gdzie idziesz z tą wielką torbą?"}],"tip":{"title":"« Iść » ou « chodzić » : une fois ou d'habitude","example":"Chaque matin, je vais me promener au bord de la rivière. — Codziennie rano <b>chodzę</b> na spacer nad rzekę.","body":"Le français n'a qu'un verbe « aller », le polonais en a deux pour aller à pied. « Iść » sert pour un trajet précis, maintenant, vers un but : « idę do piekarni », je vais à la boulangerie, là, tout de suite. « Chodzić » sert pour l'habitude, les allers-retours, la répétition : « chodzę na spacer », je vais me promener, chaque jour. Décomposez « codziennie rano chodzę na spacer » : « codziennie », chaque jour, « rano », le matin, « chodzę », je vais, d'habitude, « na spacer », en promenade. Même logique en véhicule : « jadę », je roule maintenant, et « jeżdżę », je roule souvent. Astuce : si vous pouvez ajouter « en ce moment », c'est « idę » ; si vous pouvez ajouter « souvent », c'est « chodzę ».","lit":"chaque-jour · matin · je-vais [d'habitude] · à · promenade · au-bord-de · rivière [accusatif]"}},{"title":"L'hôtel en bord de mer","phrases":[{"fr":"Notre hôtel est juste au bord de la mer.","tgt":"Nasz hotel jest tuż nad morzem."},{"fr":"J'ai une réservation au nom de Martin.","tgt":"Mam rezerwację na nazwisko Martin."},{"fr":"Votre chambre se trouve au troisième étage, monsieur.","tgt":"Pana pokój jest na trzecim piętrze."},{"fr":"Est-ce que la chambre a vue sur la mer ?","tgt":"Czy pokój ma widok na morze?"},{"fr":"Nous servons le petit-déjeuner de sept à dix heures.","tgt":"Śniadanie podajemy od siódmej do dziesiątej."},{"fr":"Le spa est ouvert jusqu'à vingt et une heures.","tgt":"Spa jest czynne do dwudziestej pierwszej."},{"fr":"Pourriez-vous me réveiller à six heures, madame ?","tgt":"Czy mogłaby pani obudzić mnie o szóstej?"},{"fr":"Je voudrais une serviette de plage en plus.","tgt":"Poproszę dodatkowy ręcznik plażowy."},{"fr":"Le parking de l'hôtel est-il payant ?","tgt":"Czy parking hotelowy jest płatny?"},{"fr":"Oui, quarante złotys par jour.","tgt":"Tak, czterdzieści złotych za dobę."}]},{"title":"Le train côtier vers Sopot","phrases":[{"fr":"Le petit train urbain relie Gdańsk, Sopot et Gdynia.","tgt":"Kolejka miejska łączy Gdańsk, Sopot i Gdynię."},{"fr":"Il passe à peu près toutes les dix minutes.","tgt":"Jeździ mniej więcej co dziesięć minut."},{"fr":"Il faut composter son billet avant de monter dans le train.","tgt":"Bilet trzeba skasować przed wejściem do pociągu."},{"fr":"Est-ce que ce train s'arrête à Sopot ?","tgt":"Czy ten pociąg zatrzymuje się w Sopocie?"},{"fr":"Oui, c'est le quatrième arrêt.","tgt":"Tak, to czwarty przystanek."},{"fr":"Je me suis assis près de la fenêtre.","tgt":"Usiadłem przy oknie."},{"fr":"Par la fenêtre, on voit des forêts et des villas.","tgt":"Za oknem widać lasy i wille."},{"fr":"Pour la jetée, descendez au prochain arrêt.","tgt":"Na molo proszę wysiąść na następnym przystanku."},{"fr":"Le trajet dure à peine vingt minutes.","tgt":"Podróż trwa zaledwie dwadzieścia minut."},{"fr":"Ce petit train est vraiment pratique.","tgt":"Ta kolejka jest naprawdę wygodna."}]},{"title":"La jetée de Sopot","phrases":[{"fr":"La jetée de Sopot est la plus longue jetée en bois d'Europe.","tgt":"Molo w Sopocie jest najdłuższym drewnianym molo w Europie."},{"fr":"Si vous voulez aller sur la jetée, il faut acheter un billet.","tgt":"Jeśli chce pan wejść na molo, trzeba kupić bilet."},{"fr":"S'il fait beau, on marchera jusqu'au bout.","tgt":"Jeśli będzie ładna pogoda, dojdziemy aż do końca."},{"fr":"Si tu as faim, on peut manger une gaufre.","tgt":"Jeśli jesteś głodny, możemy zjeść gofra."},{"fr":"Si on se dépêche, on verra le coucher du soleil.","tgt":"Jeśli się pospieszymy, zobaczymy zachód słońca."},{"fr":"Au bout de la jetée, le vent souffle fort.","tgt":"Na końcu mola mocno wieje."},{"fr":"Si tu as froid, prends ma veste.","tgt":"Jeśli ci zimno, weź moją kurtkę."},{"fr":"D'ici, des bateaux partent pour Hel.","tgt":"Stąd odpływają statki na Hel."},{"fr":"Si vous prenez un billet aller-retour, ce sera moins cher.","tgt":"Jeśli kupi pan bilet w obie strony, będzie taniej."},{"fr":"Cette promenade sur la jetée est inoubliable.","tgt":"Ten spacer po molo jest niezapomniany."}],"tip":{"title":"« Jeśli » : si, la condition réelle","example":"S'il fait beau, on marchera jusqu'au bout. — <b>Jeśli będzie</b> ładna pogoda, dojdziemy aż do końca.","body":"Pour une condition qui peut vraiment se réaliser, le polonais dit « jeśli », si. La grande différence avec le français, c'est le temps : quand on parle de l'avenir, le polonais met le futur après « jeśli », là où le français met le présent. On dit donc littéralement « si il sera beau temps », « jeśli będzie ładna pogoda », puis « dojdziemy », nous arriverons à pied. Pour une condition au présent, rien ne change : « jeśli jesteś głodny », si tu as faim. Vous entendrez aussi « jak » dans la conversation, avec le même sens, en plus familier. Astuce : pensez à la logique, la météo dont on parle sera belle demain, donc on met le futur des deux côtés.","lit":"si · sera · beau · temps · nous-arriverons-à-pied · jusqu' · à · bout"}},{"title":"Une journée à la plage","phrases":[{"fr":"Ici, le sable est fin et presque blanc.","tgt":"Piasek jest tu drobny i prawie biały."},{"fr":"L'eau de la Baltique est plutôt froide.","tgt":"Woda w Bałtyku jest dość zimna."},{"fr":"J'ai laissé ma crème solaire à l'hôtel.","tgt":"Zostawiłem krem do opalania w hotelu."},{"fr":"Sur la plage, tout le monde installe des pare-vent.","tgt":"Na plaży wszyscy rozstawiają parawany."},{"fr":"Le maître-nageur surveille la baignade jusqu'à dix-huit heures.","tgt":"Ratownik pilnuje kąpieliska do osiemnastej."},{"fr":"Le drapeau rouge signifie que la baignade est interdite.","tgt":"Czerwona flaga oznacza zakaz kąpieli."},{"fr":"Allons nager, l'eau n'est pas si froide !","tgt":"Chodźmy popływać, woda nie jest taka zimna!"},{"fr":"Je vais chercher des glaces pour tout le monde.","tgt":"Pójdę po lody dla wszystkich."},{"fr":"Nous avons trouvé de petits morceaux d'ambre.","tgt":"Znaleźliśmy małe kawałki bursztynu."},{"fr":"J'ai attrapé un coup de soleil sur le dos.","tgt":"Spaliłem sobie plecy na słońcu."}]},{"title":"Le poisson fumé","phrases":[{"fr":"Ici, ça sent le poisson fumé partout.","tgt":"Wszędzie tu pachnie wędzoną rybą."},{"fr":"Qu'est-ce que vous me conseillez, monsieur ?","tgt":"Co pan poleca?"},{"fr":"Le flétan fumé est notre spécialité.","tgt":"Wędzony halibut to nasza specjalność."},{"fr":"Je prendrai un maquereau et deux tranches de pain.","tgt":"Poproszę makrelę i dwie kromki chleba."},{"fr":"Le poisson a été pêché ce matin.","tgt":"Rybę złowiono dziś rano."},{"fr":"Il est encore chaud, faites attention.","tgt":"Jest jeszcze ciepła, proszę uważać."},{"fr":"On le mange avec les doigts, directement sur le papier.","tgt":"Je się ją palcami, prosto z papieru."},{"fr":"Vous avez aussi de la soupe de poisson ?","tgt":"Czy ma pan też zupę rybną?"},{"fr":"Ces sprats fumés sont délicieux.","tgt":"Te wędzone szprotki są pyszne."},{"fr":"Je n'ai jamais mangé un poisson aussi frais.","tgt":"Nigdy nie jadłem tak świeżej ryby."}]},{"title":"Louer des vélos","phrases":[{"fr":"Nous voudrions louer deux vélos pour toute la journée.","tgt":"Chcielibyśmy wypożyczyć dwa rowery na cały dzień."},{"fr":"Il faut laisser une pièce d'identité en caution.","tgt":"Trzeba zostawić dokument tożsamości w zastaw."},{"fr":"La location coûte cinquante złotys par jour.","tgt":"Wypożyczenie kosztuje pięćdziesiąt złotych za dzień."},{"fr":"Le casque est compris dans le prix.","tgt":"Kask jest wliczony w cenę."},{"fr":"La piste cyclable longe toute la côte.","tgt":"Ścieżka rowerowa biegnie wzdłuż całego wybrzeża."},{"fr":"Pouvez-vous régler la selle, s'il vous plaît ?","tgt":"Czy może pan wyregulować siodełko?"},{"fr":"Le frein arrière ne marche pas très bien.","tgt":"Tylny hamulec słabo działa."},{"fr":"Peut-on rendre les vélos à une autre station ?","tgt":"Czy można oddać rowery w innym punkcie?"},{"fr":"Nous avons pédalé jusqu'à Gdynia sans nous arrêter.","tgt":"Dojechaliśmy rowerami aż do Gdyni bez zatrzymywania się."},{"fr":"J'ai mal aux jambes, mais ça valait la peine.","tgt":"Bolą mnie nogi, ale było warto."}]},{"title":"Au guichet de la gare","phrases":[{"fr":"Je voudrais cinq billets pour Gdynia.","tgt":"Poproszę pięć biletów do Gdyni."},{"fr":"Deux billets plein tarif et trois billets réduits.","tgt":"Dwa bilety normalne i trzy ulgowe."},{"fr":"Ça fait quarante-deux złotys en tout.","tgt":"Razem czterdzieści dwa złote."},{"fr":"Le trajet coûte six złotys par personne.","tgt":"Przejazd kosztuje sześć złotych od osoby."},{"fr":"Nous sommes sept personnes.","tgt":"Jest nas siedem osób."},{"fr":"Le train part dans douze minutes.","tgt":"Pociąg odjeżdża za dwanaście minut."},{"fr":"Il reste encore trois places libres.","tgt":"Są jeszcze trzy wolne miejsca."},{"fr":"J'ai fait la queue au guichet pendant vingt minutes.","tgt":"Czekałem w kolejce do kasy dwadzieścia minut."},{"fr":"Un billet pour la journée coûte vingt-deux złotys.","tgt":"Bilet dobowy kosztuje dwadzieścia dwa złote."},{"fr":"Gardez bien les billets jusqu'à la fin du trajet.","tgt":"Proszę zachować bilety do końca podróży."}],"tip":{"title":"Les nombres et le génitif pluriel : « pięć biletów »","example":"Je voudrais cinq billets pour Gdynia. — Poproszę <b>pięć biletów</b> do Gdyni.","body":"En polonais, la fin du nom change selon le nombre qui le précède. Avec deux, trois et quatre, on garde le pluriel normal : « dwa bilety », deux billets, « trzy złote », trois złotys. À partir de cinq, le nom passe au génitif pluriel, comme si l'on disait « cinq de billets » : « pięć biletów », « sześć złotych ». Décomposez « poproszę pięć biletów » : « poproszę », je demande, « pięć », cinq, « biletów », de billets. Attention, la règle se répète dans les grands nombres : on dit « dwadzieścia dwa złote », mais « dwadzieścia pięć złotych ». Astuce : écoutez le dernier chiffre prononcé, s'il s'agit de deux, trois ou quatre, la forme reste courte, sinon on ajoute ce génitif.","lit":"je-demande · cinq · billets [génitif pluriel] · à · Gdynia [génitif]"}},{"title":"Gdynia et son port","phrases":[{"fr":"Gdynia est une ville bien plus moderne que Gdańsk.","tgt":"Gdynia jest dużo nowocześniejsza niż Gdańsk."},{"fr":"Son port est l'un des plus grands du pays.","tgt":"Tutejszy port jest jednym z największych w kraju."},{"fr":"On peut visiter un grand voilier amarré dans le port.","tgt":"Można zwiedzić duży żaglowiec zacumowany w porcie."},{"fr":"Ce voilier a autrefois fait le tour du monde.","tgt":"Ten żaglowiec opłynął kiedyś cały świat."},{"fr":"Le boulevard du bord de mer est idéal pour se promener.","tgt":"Bulwar Nadmorski jest idealny na spacer."},{"fr":"Il y a aussi un grand aquarium près du quai.","tgt":"Przy nabrzeżu jest też duże akwarium."},{"fr":"Les enfants ont adoré les phoques et les méduses.","tgt":"Dzieciom bardzo podobały się foki i meduzy."},{"fr":"L'été, de grands paquebots de croisière font escale ici.","tgt":"Latem zawijają tu wielkie wycieczkowce."},{"fr":"Depuis la colline, on voit toute la baie.","tgt":"Ze wzgórza widać całą zatokę."},{"fr":"Gdynia m'a vraiment surpris.","tgt":"Gdynia naprawdę mnie zaskoczyła."}]},{"title":"Le ferry pour Hel","phrases":[{"fr":"Le ferry pour Hel part à dix heures.","tgt":"Prom na Hel odpływa o dziesiątej."},{"fr":"Il vaut mieux acheter les billets en ligne.","tgt":"Lepiej kupić bilety przez internet."},{"fr":"Peut-on emporter des vélos à bord ?","tgt":"Czy można zabrać rowery na pokład?"},{"fr":"Oui, mais il faut payer un supplément.","tgt":"Tak, ale trzeba dopłacić."},{"fr":"La traversée dure environ une heure.","tgt":"Rejs trwa około godziny."},{"fr":"Montons sur le pont supérieur, la vue est meilleure.","tgt":"Wejdźmy na górny pokład, stamtąd jest lepszy widok."},{"fr":"Aujourd'hui, la mer est un peu agitée.","tgt":"Morze jest dziś trochę wzburzone."},{"fr":"Je crois que j'ai le mal de mer.","tgt":"Chyba mam chorobę morską."},{"fr":"Regarde, on voit déjà le phare de Hel !","tgt":"Patrz, już widać latarnię na Helu!"},{"fr":"Nous accostons dans quelques minutes.","tgt":"Za kilka minut przybijamy do brzegu."}]},{"title":"Sur la presqu'île de Hel","phrases":[{"fr":"Par endroits, la presqu'île est très étroite.","tgt":"Półwysep jest miejscami bardzo wąski."},{"fr":"D'un côté la baie, de l'autre la pleine mer.","tgt":"Z jednej strony zatoka, z drugiej otwarte morze."},{"fr":"Nous avons visité la station des phoques.","tgt":"Zwiedziliśmy fokarium."},{"fr":"On a pu voir le repas des phoques.","tgt":"Widzieliśmy karmienie fok."},{"fr":"On peut monter tout en haut du phare.","tgt":"Można wejść na szczyt latarni morskiej."},{"fr":"Plus de deux cents marches mènent au sommet.","tgt":"Na szczyt prowadzi ponad dwieście stopni."},{"fr":"À cause du vent, beaucoup de surfeurs viennent ici.","tgt":"Ze względu na wiatr przyjeżdża tu wielu surferów."},{"fr":"Les petites maisons de pêcheurs sont charmantes.","tgt":"Małe domki rybackie są urocze."},{"fr":"Nous avons mangé une soupe de poisson sur le port.","tgt":"Zjedliśmy zupę rybną w porcie."},{"fr":"On rentre avec le dernier ferry de dix-huit heures.","tgt":"Wracamy ostatnim promem o osiemnastej."}]},{"title":"Un jour de pluie au bord de la mer","phrases":[{"fr":"Bien qu'il pleuve, nous allons nous promener.","tgt":"Chociaż pada deszcz, idziemy na spacer."},{"fr":"Il pleut, mais il fait doux.","tgt":"Pada, ale jest ciepło."},{"fr":"Bien que la plage soit vide, elle reste belle.","tgt":"Chociaż plaża jest pusta, nadal jest piękna."},{"fr":"Ce musée est petit, mais vraiment intéressant.","tgt":"To muzeum jest małe, ale naprawdę ciekawe."},{"fr":"Bien que je sois fatigué, je veux encore voir la vieille ville.","tgt":"Chociaż jestem zmęczony, chcę jeszcze zobaczyć Stare Miasto."},{"fr":"On a pris nos parapluies, mais on est quand même trempés.","tgt":"Wzięliśmy parasole, ale i tak jesteśmy przemoczeni."},{"fr":"Bien qu'il soit tard, le café est encore ouvert.","tgt":"Chociaż jest późno, kawiarnia jest jeszcze otwarta."},{"fr":"Passons l'après-midi dans un café avec un bon livre.","tgt":"Spędźmy popołudnie w kawiarni z dobrą książką."},{"fr":"Vers le soir, la pluie s'est arrêtée.","tgt":"Pod wieczór przestało padać."},{"fr":"Bien que le temps soit gris, ce voyage me plaît beaucoup.","tgt":"Chociaż pogoda jest szara, bardzo podoba mi się ta podróż."}],"tip":{"title":"« Chociaż » et « ale » : bien que, mais","example":"Bien qu'il pleuve, nous allons nous promener. — <b>Chociaż</b> pada deszcz, idziemy na spacer.","body":"Pour dire bien que, le polonais utilise « chociaż », ou sa forme courte « choć ». Bonne nouvelle : après « chociaż », pas de subjonctif comme en français, on garde le verbe normal. On dit donc littéralement « bien que tombe la pluie, nous allons en promenade » : « chociaż pada deszcz, idziemy na spacer ». Pour dire mais, c'est « ale », toujours précédé d'une petite pause : « pada, ale jest ciepło », il pleut, mais il fait doux. Et pour insister, on ajoute « i tak », quand même : « ale i tak jesteśmy przemoczeni », mais on est quand même trempés. Astuce : « chociaż » ouvre la phrase, « ale » la coupe en deux.","lit":"bien-que · tombe · pluie · nous-allons · à · promenade"}},{"title":"Un petit souci de santé","phrases":[{"fr":"Hier, je suis resté trop longtemps au soleil.","tgt":"Wczoraj za długo byłem na słońcu."},{"fr":"Excusez-moi, où se trouve la pharmacie la plus proche ?","tgt":"Przepraszam, gdzie jest najbliższa apteka?"},{"fr":"J'ai mal à la tête et j'ai un peu de fièvre.","tgt":"Boli mnie głowa i mam lekką gorączkę."},{"fr":"Avez-vous quelque chose contre les coups de soleil ?","tgt":"Czy ma pani coś na oparzenia słoneczne?"},{"fr":"Mettez cette crème trois fois par jour.","tgt":"Proszę smarować się tym kremem trzy razy dziennie."},{"fr":"Buvez beaucoup d'eau et reposez-vous.","tgt":"Proszę pić dużo wody i odpoczywać."},{"fr":"En plus, une guêpe m'a piqué.","tgt":"Do tego użądliła mnie osa."},{"fr":"Ce médicament, il faut une ordonnance ?","tgt":"Czy na ten lek potrzebna jest recepta?"},{"fr":"Non, il est en vente libre.","tgt":"Nie, jest dostępny bez recepty."},{"fr":"Demain, je resterai à l'ombre toute la journée.","tgt":"Jutro cały dzień posiedzę w cieniu."}]},{"title":"Un dîner face à la mer","phrases":[{"fr":"Avez-vous une table libre en terrasse pour deux ?","tgt":"Czy jest wolny stolik na tarasie dla dwóch osób?"},{"fr":"Nous aimerions voir la carte, s'il vous plaît.","tgt":"Poprosimy kartę."},{"fr":"Je vous recommande le cabillaud grillé.","tgt":"Polecam grillowanego dorsza."},{"fr":"Pour moi, des harengs à la crème avec des pommes de terre.","tgt":"Dla mnie śledzie w śmietanie z ziemniakami."},{"fr":"Qu'est-ce que tu prends à boire ?","tgt":"Co bierzesz do picia?"},{"fr":"Un jus de pomme, car je conduis demain matin.","tgt":"Sok jabłkowy, bo jutro rano prowadzę."},{"fr":"Ce soir, la mer est parfaitement calme.","tgt":"Morze jest dziś wieczorem zupełnie spokojne."},{"fr":"Le cabillaud était parfaitement cuit.","tgt":"Dorsz był idealnie przyrządzony."},{"fr":"Pourrions-nous avoir l'addition ?","tgt":"Czy możemy prosić o rachunek?"},{"fr":"Ce n'est pas la peine de me rendre la monnaie, merci.","tgt":"Reszty nie trzeba, dziękuję bardzo."}]},{"title":"Les derniers souvenirs","phrases":[{"fr":"Je cherche quelque chose en ambre pour ma mère.","tgt":"Szukam czegoś z bursztynu dla mamy."},{"fr":"Ce pendentif est fait à la main ici, à Gdańsk.","tgt":"Ten wisiorek jest ręcznie robiony tutaj, w Gdańsku."},{"fr":"Comment savoir si c'est du vrai ambre ?","tgt":"Skąd wiadomo, że to prawdziwy bursztyn?"},{"fr":"Vous recevrez un certificat avec chaque bijou.","tgt":"Do każdego wyrobu dostanie pan certyfikat."},{"fr":"Je vais aussi prendre ces magnets pour mes collègues.","tgt":"Wezmę też te magnesy dla kolegów z pracy."},{"fr":"Pourriez-vous faire un paquet cadeau, madame ?","tgt":"Czy może pani zapakować to na prezent?"},{"fr":"Il nous reste encore quelques złotys.","tgt":"Zostało nam jeszcze kilka złotych."},{"fr":"Achetons un pot de miel au marché.","tgt":"Kupmy słoik miodu na targu."},{"fr":"Ma valise est déjà presque pleine à craquer.","tgt":"Moja walizka już prawie pęka w szwach."},{"fr":"Demain matin, nous rentrons en France.","tgt":"Jutro rano wracamy do Francji."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait découvrir toute la côte baltique.","tgt":"Ten moduł pozwolił nam odkryć całe wybrzeże Bałtyku."},{"fr":"Maintenant, je sais acheter des billets et demander mon chemin en polonais.","tgt":"Teraz umiem kupić bilety i zapytać o drogę po polsku."},{"fr":"Les préfixes des verbes de mouvement me semblent plus clairs.","tgt":"Przedrostki czasowników ruchu wydają mi się jaśniejsze."},{"fr":"Je fais enfin la différence entre « iść » et « chodzić ».","tgt":"Wreszcie rozróżniam „iść” i „chodzić”."},{"fr":"Je compte mes złotys sans hésiter.","tgt":"Liczę złotówki bez wahania."},{"fr":"En voyage, je me débrouille de mieux en mieux tout seul.","tgt":"Coraz lepiej radzę sobie sam w podróży."},{"fr":"Parler avec les gens rend le voyage plus riche.","tgt":"Rozmowy z ludźmi wzbogacają podróż."},{"fr":"Après chaque leçon, j'ai envie de retourner en Pologne.","tgt":"Po każdej lekcji mam ochotę wrócić do Polski."},{"fr":"Félicitations, ce sont d'énormes progrès !","tgt":"Gratulacje, to ogromne postępy!"},{"fr":"On se retrouve dans le prochain module !","tgt":"Do zobaczenia w następnym module!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée au chalet de Zakopane","phrases":[{"fr":"Enfin, on est arrivés à Zakopane !","tgt":"Nareszcie dotarliśmy do Zakopanego!"},{"fr":"Le chalet en bois est encore plus beau que sur les photos.","tgt":"Drewniany domek jest jeszcze ładniejszy niż na zdjęciach."},{"fr":"Qui a les clés de la porte ?","tgt":"Kto ma klucze do drzwi?"},{"fr":"Je les ai laissées dans la voiture, je reviens tout de suite.","tgt":"Zostawiłem je w samochodzie, zaraz wracam."},{"fr":"On voit les montagnes depuis la fenêtre de la cuisine.","tgt":"Z okna w kuchni widać góry."},{"fr":"Tu prends quelle chambre, celle d'en haut ou celle d'en bas ?","tgt":"Którą sypialnię bierzesz, na górze czy na dole?"},{"fr":"Je préfère dormir en haut, juste sous le toit.","tgt":"Wolę spać na górze, pod samym dachem."},{"fr":"Il fait un peu froid ici, allume le feu dans la cheminée.","tgt":"Trochę tu zimno, rozpal ogień w kominku."},{"fr":"On défait les valises et on va faire les courses.","tgt":"Rozpakujemy się i pójdziemy na zakupy."},{"fr":"Ce week-end va être génial, j'en suis sûr.","tgt":"Ten weekend będzie super, jestem pewien."}]},{"title":"Retrouver les copains","phrases":[{"fr":"Salut Marek, ça fait une éternité !","tgt":"Siema, Marek, kopę lat!"},{"fr":"Salut, quoi de neuf de ton côté ?","tgt":"Siema, co tam u ciebie?"},{"fr":"Tranquille, tout va bien chez moi.","tgt":"Spoko, u mnie wszystko gra."},{"fr":"Désolé pour le retard, il y avait des bouchons sur la route.","tgt":"Sorki za spóźnienie, na drodze były korki."},{"fr":"Pas de souci, nous aussi, on vient juste d'arriver.","tgt":"Spoko, my też dopiero przyjechaliśmy."},{"fr":"Tu veux boire un truc chaud ?","tgt":"Chcesz się napić czegoś ciepłego?"},{"fr":"Avec plaisir, je suis complètement gelé.","tgt":"Chętnie, strasznie zmarzłem."},{"fr":"C'est cool de tous se revoir enfin.","tgt":"Super, że wreszcie wszyscy się widzimy."},{"fr":"Bon, je vais poser mes affaires, à plus !","tgt":"Dobra, idę odłożyć rzeczy, na razie!"},{"fr":"D'accord, on se retrouve en bas !","tgt":"Spoko, widzimy się na dole!"}],"tip":{"title":"Le registre familier entre amis : « siema », « spoko », « na razie »","example":"Tranquille, tout va bien chez moi. — <b>Spoko</b>, u mnie wszystko gra.","body":"Entre amis, le polonais se détend autant que le français. Au lieu de « dzień dobry », on lance « siema », qui veut dire salut, et pour dire que tout va bien, on répond simplement « spoko », tranquille ou pas de souci. Notre exemple, « spoko, u mnie wszystko gra », se décompose en tranquille, chez moi, tout, joue : chez moi, tout roule. Pour partir, on dit « na razie », mot à mot pour le moment, c'est notre à plus. Vous entendrez aussi « dobra », bon ou d'accord, et « sorki », pardon. Astuce : « spoko » s'emploie presque aussi souvent que cool en français, mais gardez ces mots pour les copains, jamais avec un inconnu.","lit":"tranquille · chez · moi · tout · joue"}},{"title":"Préparer la randonnée","phrases":[{"fr":"Demain, on va jusqu'au lac Morskie Oko.","tgt":"Jutro idziemy nad Morskie Oko."},{"fr":"Il faudra se lever très tôt pour éviter la foule.","tgt":"Trzeba będzie wstać bardzo wcześnie, żeby uniknąć tłumów."},{"fr":"N'oublie pas tes chaussures de randonnée.","tgt":"Nie zapomnij butów trekkingowych."},{"fr":"Combien de temps faut-il marcher depuis le parking ?","tgt":"Jak długo idzie się z parkingu?"},{"fr":"À peu près deux heures, si on ne traîne pas.","tgt":"Mniej więcej dwie godziny, jeśli nie będziemy się guzdrać."},{"fr":"Je vais préparer des sandwichs pour tout le monde.","tgt":"Zrobię kanapki dla wszystkich."},{"fr":"Qui s'occupe de l'eau et des barres de céréales ?","tgt":"Kto się zajmie wodą i batonikami?"},{"fr":"Moi, je prends la trousse de secours.","tgt":"Ja wezmę apteczkę."},{"fr":"Prends aussi une veste chaude, il fait frais là-haut.","tgt":"Weź też ciepłą kurtkę, na górze jest chłodno."},{"fr":"On part à six heures pile, d'accord ?","tgt":"Wychodzimy punktualnie o szóstej, dobra?"}]},{"title":"En route vers Morskie Oko","phrases":[{"fr":"La route est longue, mais le paysage est magnifique.","tgt":"Droga jest długa, ale widoki są przepiękne."},{"fr":"Attends-moi, je dois renouer mon lacet.","tgt":"Poczekaj na mnie, muszę zawiązać sznurówkę."},{"fr":"On fait une petite pause à l'ombre ?","tgt":"Zrobimy małą przerwę w cieniu?"},{"fr":"Regarde, on voit déjà les sommets enneigés.","tgt":"Patrz, już widać ośnieżone szczyty."},{"fr":"J'ai un peu mal aux jambes, mais ça va.","tgt":"Trochę bolą mnie nogi, ale jest okej."},{"fr":"Bois un peu d'eau, tu as l'air fatigué.","tgt":"Napij się wody, wyglądasz na zmęczonego."},{"fr":"On est à mi-chemin, tu vas y arriver !","tgt":"Jesteśmy w połowie drogi, dasz radę!"},{"fr":"Il y a énormément de monde sur le sentier aujourd'hui.","tgt":"Na szlaku jest dziś mnóstwo ludzi."},{"fr":"Plus on monte, plus il fait frais.","tgt":"Im wyżej, tym chłodniej."},{"fr":"Encore un virage et on y est !","tgt":"Jeszcze jeden zakręt i jesteśmy na miejscu!"}]},{"title":"La météo en montagne","phrases":[{"fr":"Le ciel est gris, il va peut-être pleuvoir.","tgt":"Niebo jest szare, może będzie padać."},{"fr":"L'orage arrivera sans doute plutôt dans l'après-midi.","tgt":"Burza chyba przyjdzie dopiero po południu."},{"fr":"Peut-être qu'on devrait partir plus tôt.","tgt":"Może powinniśmy wyjść wcześniej."},{"fr":"Je crois bien que j'ai oublié mon parapluie.","tgt":"Chyba zapomniałem parasolki."},{"fr":"Le vent se lève, il va sans doute faire plus froid.","tgt":"Zrywa się wiatr, chyba zrobi się zimniej."},{"fr":"On verra peut-être le soleil demain matin.","tgt":"Może jutro rano zobaczymy słońce."},{"fr":"Le brouillard se dissipera sans doute vers midi.","tgt":"Mgła chyba opadnie koło południa."},{"fr":"Peut-être, mais je n'en suis pas certain.","tgt":"Może, ale nie jestem pewien."},{"fr":"En montagne, la météo change très vite.","tgt":"W górach pogoda zmienia się bardzo szybko."},{"fr":"Tu as sans doute raison, restons prudents.","tgt":"Chyba masz rację, bądźmy ostrożni."}],"tip":{"title":"« Może » et « chyba » : peut-être, sans doute","example":"Tu as sans doute raison, restons prudents. — <b>Chyba</b> masz rację, bądźmy ostrożni.","body":"Pour nuancer ce qu'on dit, le polonais a deux petits mots très pratiques. « Może » signifie peut-être et se place tout simplement en tête de phrase : « może będzie padać », peut-être qu'il va pleuvoir. « Chyba » est plus sûr de lui, c'est je crois bien ou sans doute : « chyba masz rację » se décompose en sans doute, tu as, raison. Contrairement au français, pas besoin d'ajouter que, la phrase continue directement. Seuls, ils servent aussi de réponse : « może », peut-être, et « chyba nie », je crois que non. Astuce : « może » laisse la porte ouverte, « chyba » penche déjà vers le oui.","lit":"sans-doute · tu-as · raison · soyons · prudents"}},{"title":"Au bord du lac","phrases":[{"fr":"Waouh, l'eau a une couleur incroyable !","tgt":"Ale ta woda ma niesamowity kolor!"},{"fr":"Les montagnes se reflètent dans le lac.","tgt":"Góry odbijają się w jeziorze."},{"fr":"On s'assoit sur ce rocher et on mange un morceau ?","tgt":"Usiądziemy na tym kamieniu i coś zjemy?"},{"fr":"Je n'ai jamais vu un endroit aussi beau.","tgt":"Nigdy nie widziałem tak pięknego miejsca."},{"fr":"Prends-moi en photo avec le lac derrière.","tgt":"Zrób mi zdjęcie z jeziorem w tle."},{"fr":"Attention, les pierres sont glissantes ici.","tgt":"Uważaj, kamienie są tu śliskie."},{"fr":"On fait le tour du lac à pied ?","tgt":"Obejdziemy jezioro dookoła?"},{"fr":"Ça prend environ une heure, mais ça vaut le coup.","tgt":"Zajmuje to mniej więcej godzinę, ale warto."},{"fr":"L'eau est glacée, même en plein été.","tgt":"Woda jest lodowata, nawet w środku lata."},{"fr":"Je pourrais rester ici toute la journée.","tgt":"Mógłbym tu zostać cały dzień."}]},{"title":"Au refuge de montagne","phrases":[{"fr":"Le refuge se trouve juste au bord du lac.","tgt":"Schronisko stoi tuż nad jeziorem."},{"fr":"On entre se réchauffer un peu ?","tgt":"Wejdziemy się trochę ogrzać?"},{"fr":"Il y a une longue file d'attente au comptoir.","tgt":"Przy ladzie jest długa kolejka."},{"fr":"Je vais prendre une soupe chaude et un thé.","tgt":"Wezmę gorącą zupę i herbatę."},{"fr":"Ils sont connus pour leur gâteau aux pommes, il faut le goûter.","tgt":"Słyną z szarlotki, trzeba jej spróbować."},{"fr":"Tu gardes la table ? Moi, je vais commander.","tgt":"Przypilnujesz stolika? Ja pójdę zamówić."},{"fr":"Ça fait du bien de s'asseoir après une telle marche.","tgt":"Ale dobrze usiąść po takim marszu."},{"fr":"Les murs sont couverts de vieilles photos de montagne.","tgt":"Ściany są obwieszone starymi zdjęciami gór."},{"fr":"Certains randonneurs passent la nuit ici.","tgt":"Niektórzy turyści tu nocują."},{"fr":"Un jour, j'aimerais dormir dans un refuge moi aussi.","tgt":"Kiedyś też chciałbym przenocować w schronisku."}]},{"title":"Une soirée au chalet","phrases":[{"fr":"Ce soir, on fait un barbecue devant le chalet.","tgt":"Dziś wieczorem robimy grilla przed domkiem."},{"fr":"Qui s'occupe de la musique ?","tgt":"Kto się zajmie muzyką?"},{"fr":"Kasia a pris sa guitare, génial !","tgt":"Kasia wzięła gitarę, super!"},{"fr":"Passe-moi les saucisses, s'il te plaît.","tgt":"Podaj mi kiełbaski, proszę."},{"fr":"Le feu prend bien, on peut commencer à griller.","tgt":"Ogień już się ładnie pali, możemy grillować."},{"fr":"Tu veux encore un peu de salade ?","tgt":"Chcesz jeszcze trochę sałatki?"},{"fr":"Non merci, je n'ai plus faim du tout.","tgt":"Nie, dzięki, już się najadłem."},{"fr":"Racontons des histoires drôles autour du feu.","tgt":"Opowiadajmy śmieszne historie przy ognisku."},{"fr":"Regarde le ciel, on voit plein d'étoiles.","tgt":"Spójrz na niebo, widać mnóstwo gwiazd."},{"fr":"Je n'oublierai jamais une soirée comme celle-là.","tgt":"Takiego wieczoru nigdy nie zapomnę."}]},{"title":"Flâner sur la rue Krupówki","phrases":[{"fr":"On descend faire un tour sur Krupówki ?","tgt":"Przejdziemy się po Krupówkach?"},{"fr":"Le samedi, il y a toujours autant de monde.","tgt":"W sobotę zawsze jest tu tyle ludzi."},{"fr":"Ça sent le fromage grillé, j'ai faim !","tgt":"Pachnie grillowanym serem, jestem głodny!"},{"fr":"Je voudrais deux oscypki grillés avec des canneberges.","tgt":"Poproszę dwa grillowane oscypki z żurawiną."},{"fr":"C'est combien, ce petit fromage ?","tgt":"Ile kosztuje ten mały serek?"},{"fr":"Dix złotys pièce.","tgt":"Dziesięć złotych za sztukę."},{"fr":"Fais attention, il est encore très chaud.","tgt":"Uważaj, jest jeszcze bardzo gorący."},{"fr":"C'est fumé, salé, vraiment délicieux.","tgt":"Jest wędzony, słony, naprawdę pyszny."},{"fr":"J'en achète un pour mes parents, en cadeau.","tgt":"Kupię jeden dla rodziców, w prezencie."},{"fr":"On continue jusqu'au bout de la rue ?","tgt":"Idziemy dalej, do końca ulicy?"}]},{"title":"Raconter ses vacances","phrases":[{"fr":"Alors, tes vacances se sont bien passées ?","tgt":"No i jak, udały ci się wakacje?"},{"fr":"Oui, je suis allé en Mazurie avec ma copine.","tgt":"Tak, byłem na Mazurach z dziewczyną."},{"fr":"On a loué un petit voilier pendant une semaine.","tgt":"Wynajęliśmy małą żaglówkę na tydzień."},{"fr":"Le premier jour, il a plu sans arrêt.","tgt":"Pierwszego dnia cały czas padało."},{"fr":"Mais ensuite, il a fait beau jusqu'à la fin.","tgt":"Ale potem do końca była piękna pogoda."},{"fr":"On se baignait dans un lac différent chaque jour.","tgt":"Codziennie kąpaliśmy się w innym jeziorze."},{"fr":"Le soir, on mangeait du poisson grillé au port.","tgt":"Wieczorami jedliśmy grillowaną rybę w porcie."},{"fr":"Et toi, qu'est-ce que tu as fait cet été ?","tgt":"A ty, co robiłeś tego lata?"},{"fr":"Je suis resté à Cracovie, j'ai beaucoup travaillé.","tgt":"Zostałem w Krakowie, dużo pracowałem."},{"fr":"L'année prochaine, je veux absolument voir la Baltique.","tgt":"W przyszłym roku koniecznie chcę zobaczyć Bałtyk."}]},{"title":"Les bains chauds","phrases":[{"fr":"Après la randonnée, rien de mieux que les bains chauds.","tgt":"Po wędrówce nie ma nic lepszego niż termy."},{"fr":"L'eau chaude vient des profondeurs de la terre.","tgt":"Gorąca woda płynie z głębi ziemi."},{"fr":"On y va en bus ou en voiture ?","tgt":"Jedziemy tam autobusem czy samochodem?"},{"fr":"N'oublie pas ton maillot et ta serviette.","tgt":"Nie zapomnij kąpielówek i ręcznika."},{"fr":"Le bassin extérieur est à trente-six degrés.","tgt":"Basen na zewnątrz ma trzydzieści sześć stopni."},{"fr":"C'est génial d'être dans l'eau chaude quand il neige.","tgt":"Super się siedzi w ciepłej wodzie, kiedy pada śnieg."},{"fr":"Mes muscles se détendent enfin.","tgt":"Wreszcie rozluźniają mi się mięśnie."},{"fr":"On reste encore une demi-heure ?","tgt":"Zostajemy jeszcze pół godziny?"},{"fr":"J'ai les doigts tout fripés à force de rester dans l'eau.","tgt":"Mam pomarszczone palce od siedzenia w wodzie."},{"fr":"Ce soir, je vais dormir comme un loir.","tgt":"Dziś będę spał jak suseł."}]},{"title":"Les bons plans du coin","phrases":[{"fr":"Il paraît qu'il y a un super restaurant au bout de la rue.","tgt":"Podobno na końcu ulicy jest świetna restauracja."},{"fr":"J'ai entendu dire qu'ils servent le meilleur żurek de la ville.","tgt":"Słyszałem, że podają tam najlepszy żurek w mieście."},{"fr":"Il paraît qu'il faut réserver une table longtemps à l'avance.","tgt":"Podobno trzeba rezerwować stolik dużo wcześniej."},{"fr":"J'ai entendu dire que la vue depuis la colline de Gubałówka est superbe.","tgt":"Słyszałem, że z Gubałówki jest piękny widok."},{"fr":"Il paraît qu'on peut monter là-haut en funiculaire.","tgt":"Podobno można tam wjechać kolejką."},{"fr":"Kasia a entendu dire que le sentier était fermé.","tgt":"Kasia słyszała, że szlak jest zamknięty."},{"fr":"Ah bon ? Qui t'a dit ça ?","tgt":"Serio? Kto ci to powiedział?"},{"fr":"Il paraît qu'il y a des chamois près du lac.","tgt":"Podobno koło jeziora są kozice."},{"fr":"J'ai entendu dire qu'il allait neiger ce week-end.","tgt":"Słyszałem, że w ten weekend ma padać śnieg."},{"fr":"Il paraît, mais je n'y crois pas trop.","tgt":"Podobno, ale jakoś w to nie wierzę."}],"tip":{"title":"« Podobno » et « słyszałem, że » : il paraît que","example":"Il paraît qu'il y a des chamois près du lac. — <b>Podobno</b> koło jeziora są kozice.","body":"Pour rapporter une rumeur ou un bon plan, on commence la phrase par « podobno », il paraît. Comme avec « chyba », aucun que n'est nécessaire : « podobno koło jeziora są kozice » se décompose en il paraît, près du lac, sont, des chamois. Pour dire j'ai entendu dire que, on utilise « słyszałem, że », littéralement j'ai entendu que, et une femme dira « słyszałam, że ». Ici, le petit mot « że » joue exactement le rôle de notre que. Pour réagir, lancez « serio ? », sérieux, ou « kto ci to powiedział ? », qui t'a dit ça. Astuce : avec « podobno », vous prenez une petite distance, vous ne garantissez rien.","lit":"il-paraît · près-de · lac [gén.] · sont · chamois"}},{"title":"Jeux et musique au coin du feu","phrases":[{"fr":"Qui joue aux cartes ce soir ?","tgt":"Kto gra dziś wieczorem w karty?"},{"fr":"Je ne connais pas les règles, tu peux m'expliquer ?","tgt":"Nie znam zasad, wytłumaczysz mi?"},{"fr":"C'est simple, tu vas piger très vite.","tgt":"To proste, szybko załapiesz."},{"fr":"C'est ton tour !","tgt":"Twoja kolej!"},{"fr":"Tu triches, je t'ai vu !","tgt":"Oszukujesz, widziałem!"},{"fr":"Mais non, j'ai juste de la chance.","tgt":"Wcale nie, po prostu mam szczęście."},{"fr":"Quelqu'un connaît une chanson de montagnards ?","tgt":"Ktoś zna jakąś góralską piosenkę?"},{"fr":"Chantons tous ensemble le refrain.","tgt":"Zaśpiewajmy razem refren."},{"fr":"Je chante faux, mais je m'amuse comme un fou.","tgt":"Fałszuję, ale świetnie się bawię."},{"fr":"Il est déjà minuit, le temps passe trop vite.","tgt":"Już północ, czas leci za szybko."}]},{"title":"Les projets du week-end","phrases":[{"fr":"Quand est-ce que tu rentres à Varsovie ?","tgt":"Kiedy wracasz do Warszawy?"},{"fr":"Quand j'étais petit, je venais ici chaque hiver.","tgt":"Kiedy byłem mały, przyjeżdżałem tu każdej zimy."},{"fr":"Quand on aura fini le petit-déjeuner, on ira faire du vélo.","tgt":"Kiedy zjemy śniadanie, pojedziemy na rowery."},{"fr":"Appelle-moi quand tu seras prêt.","tgt":"Zadzwoń, kiedy będziesz gotowy."},{"fr":"Samedi, on monte au Kasprowy Wierch en téléphérique.","tgt":"W sobotę wjeżdżamy kolejką na Kasprowy Wierch."},{"fr":"Quand on sera en haut, on verra toutes les Tatras.","tgt":"Kiedy będziemy na górze, zobaczymy całe Tatry."},{"fr":"Dimanche, on fera la grasse matinée.","tgt":"W niedzielę się wyśpimy."},{"fr":"Quand je suis arrivé vendredi, il neigeait encore.","tgt":"Kiedy przyjechałem w piątek, jeszcze padał śnieg."},{"fr":"Et quand est-ce qu'on se revoit tous ensemble ?","tgt":"A kiedy znowu spotkamy się wszyscy razem?"},{"fr":"Quand tu veux, moi je suis toujours partant.","tgt":"Kiedy tylko chcesz, zawsze chętnie."}],"tip":{"title":"« Kiedy » : quand, au passé et au futur","example":"Quand on aura fini le petit-déjeuner, on ira faire du vélo. — <b>Kiedy</b> zjemy śniadanie, pojedziemy na rowery.","body":"« Kiedy » veut dire quand, aussi bien pour poser une question que pour relier deux actions. Au passé, il fonctionne comme en français : « kiedy byłem mały », quand j'étais petit. Pour l'avenir, le français dit quand on aura fini, mais le polonais se contente d'un simple futur. « Kiedy zjemy śniadanie, pojedziemy na rowery » se décompose en quand, nous mangerons, petit-déjeuner, nous irons, sur les vélos. On choisit la forme accomplie du verbe, « zjemy » et non « jemy », pour montrer que l'action sera terminée. Astuce : pensez quand ce sera fait, et dites le verbe au futur, sans détour.","lit":"quand · nous-mangerons · petit-déjeuner · nous-irons · sur · vélos"}},{"title":"Une petite mésaventure","phrases":[{"fr":"Tu ne devineras jamais ce qui m'est arrivé hier.","tgt":"Nie zgadniesz, co mi się wczoraj przytrafiło."},{"fr":"Je me suis perdu en redescendant de la montagne.","tgt":"Zgubiłem się, schodząc z gór."},{"fr":"Mon téléphone était complètement déchargé.","tgt":"Rozładował mi się telefon."},{"fr":"La nuit commençait à tomber, j'avais un peu peur.","tgt":"Zaczynało się ściemniać, trochę się bałem."},{"fr":"Heureusement, j'ai croisé deux randonneurs.","tgt":"Na szczęście spotkałem dwoje turystów."},{"fr":"Ils m'ont montré le bon chemin jusqu'au village.","tgt":"Pokazali mi właściwą drogę do wsi."},{"fr":"Pourquoi tu ne nous as pas appelés ?","tgt":"Czemu do nas nie zadzwoniłeś?"},{"fr":"Il n'y avait pas de réseau, c'était impossible.","tgt":"Nie było zasięgu, nie dało się."},{"fr":"La prochaine fois, je prendrai une batterie externe.","tgt":"Następnym razem wezmę powerbank."},{"fr":"Au moins, j'ai une bonne histoire à raconter.","tgt":"Przynajmniej mam dobrą historię do opowiadania."}]},{"title":"Photos et souvenirs","phrases":[{"fr":"Montre-moi les photos d'hier, je veux les voir.","tgt":"Pokaż mi wczorajsze zdjęcia, chcę je zobaczyć."},{"fr":"Sur celle-ci, on a tous les yeux fermés !","tgt":"Na tym wszyscy mamy zamknięte oczy!"},{"fr":"Celle du lac au lever du soleil est superbe.","tgt":"To z jeziorem o wschodzie słońca jest świetne."},{"fr":"Tu peux me les envoyer ce soir ?","tgt":"Wyślesz mi je dziś wieczorem?"},{"fr":"Je vais en imprimer quelques-unes pour ma chambre.","tgt":"Wydrukuję kilka do swojego pokoju."},{"fr":"J'ai acheté une petite boîte en bois sculpté.","tgt":"Kupiłem małe rzeźbione pudełko z drewna."},{"fr":"C'est un cadeau pour ma sœur, elle adore ce genre de choses.","tgt":"To prezent dla siostry, uwielbia takie rzeczy."},{"fr":"Moi, j'ai pris un pull en laine de mouton.","tgt":"A ja kupiłem sweter z owczej wełny."},{"fr":"Il est un peu lourd, mais très chaud.","tgt":"Jest trochę ciężki, ale bardzo ciepły."},{"fr":"Chaque fois que je le porterai, je penserai à Zakopane.","tgt":"Za każdym razem, gdy go założę, pomyślę o Zakopanem."}]},{"title":"Discuter avec les gens du coin","phrases":[{"fr":"Bonjour, vous habitez ici toute l'année ?","tgt":"Dzień dobry, mieszka pan tu cały rok?"},{"fr":"Oui, ma famille vit dans cette vallée depuis toujours.","tgt":"Tak, moja rodzina od zawsze mieszka w tej dolinie."},{"fr":"Vous parlez le patois des montagnards ?","tgt":"Mówi pan gwarą góralską?"},{"fr":"Bien sûr, mais avec les touristes, je parle normalement.","tgt":"Oczywiście, ale z turystami mówię normalnie."},{"fr":"Qu'est-ce que vous nous conseillez de visiter ?","tgt":"Co nam pan poleca zwiedzić?"},{"fr":"Allez voir la vallée de Kościeliska, c'est plus calme.","tgt":"Proszę pójść do Doliny Kościeliskiej, tam jest spokojniej."},{"fr":"Et où est-ce qu'on mange bien par ici ?","tgt":"A gdzie tu można dobrze zjeść?"},{"fr":"Chez ma cousine, juste à côté de la gare.","tgt":"U mojej kuzynki, zaraz obok dworca."},{"fr":"Merci beaucoup, c'est très gentil de votre part.","tgt":"Bardzo dziękujemy, to bardzo miłe z pana strony."},{"fr":"Bon séjour, et beau temps dans les montagnes !","tgt":"Miłego pobytu i pięknej pogody w górach!"}]},{"title":"Appeler les copains par leur prénom","phrases":[{"fr":"Kasia, viens voir, il y a un écureuil !","tgt":"Kasiu, chodź zobaczyć, jest wiewiórka!"},{"fr":"Marek, tu as vu mes lunettes de soleil ?","tgt":"Marku, widziałeś moje okulary przeciwsłoneczne?"},{"fr":"Monsieur Tomek, merci pour votre accueil !","tgt":"Panie Tomku, dziękujemy za gościnę!"},{"fr":"Maman, on rentre demain soir.","tgt":"Mamo, wracamy jutro wieczorem."},{"fr":"Ania, passe-moi le sel, s'il te plaît.","tgt":"Aniu, podaj mi sól, proszę."},{"fr":"Paweł, debout, il est déjà neuf heures !","tgt":"Pawle, wstawaj, już dziewiąta!"},{"fr":"Madame Ewa, à quelle heure faut-il rendre les clés ?","tgt":"Pani Ewo, o której musimy oddać klucze?"},{"fr":"Mes amis, merci pour ce week-end inoubliable !","tgt":"Przyjaciele, dzięki za ten niezapomniany weekend!"},{"fr":"Basia, c'est toi qui conduis ou c'est moi ?","tgt":"Basiu, ty prowadzisz czy ja?"},{"fr":"Bon, les amis, on se met en route !","tgt":"Dobra, ludzie, ruszamy!"}],"tip":{"title":"Le vocatif : interpeller quelqu'un, « Kasiu », « panie Tomku »","example":"Monsieur Tomek, merci pour votre accueil ! — <b>Panie Tomku</b>, dziękujemy za gościnę!","body":"Quand on appelle quelqu'un en polonais, son prénom change de terminaison : c'est le vocatif. Kasia devient « Kasiu », Ania devient « Aniu », Marek devient « Marku » et Ewa devient « Ewo ». Avec la politesse, monsieur se dit « panie » et madame reste « pani » : « panie Tomku, dziękujemy za gościnę » se décompose en monsieur Tomek, nous remercions, pour l'hospitalité. Retenez le réflexe : les prénoms tendres en « sia » ou « nia » finissent en « u », beaucoup d'autres en « o » ou en « e ». Entre jeunes, on entend parfois le prénom sans changement, mais le vocatif sonne toujours plus chaleureux. Astuce : le premier vocatif que tout le monde apprend, c'est « mamo », maman !","lit":"monsieur [voc.] · Tomek [voc.] · nous-remercions · pour · hospitalité"}},{"title":"Le dernier soir","phrases":[{"fr":"Je n'arrive pas à croire que c'est déjà fini.","tgt":"Nie mogę uwierzyć, że to już koniec."},{"fr":"Ces trois jours sont passés beaucoup trop vite.","tgt":"Te trzy dni minęły o wiele za szybko."},{"fr":"Qu'est-ce qui t'a le plus plu ce week-end ?","tgt":"Co ci się najbardziej podobało w ten weekend?"},{"fr":"Pour moi, c'est le lac au petit matin.","tgt":"Dla mnie jezioro wczesnym rankiem."},{"fr":"Moi, j'ai préféré la soirée aux bains chauds.","tgt":"Mnie najbardziej podobał się wieczór w termach."},{"fr":"On range le chalet ce soir ou demain matin ?","tgt":"Sprzątamy domek dziś wieczorem czy jutro rano?"},{"fr":"Ce soir, sinon on sera en retard demain.","tgt":"Dziś wieczorem, bo inaczej jutro się spóźnimy."},{"fr":"Il faudrait revenir en hiver pour skier.","tgt":"Trzeba by tu wrócić zimą na narty."},{"fr":"Bonne idée, je m'occupe de réserver le même chalet.","tgt":"Dobry pomysł, zajmę się rezerwacją tego samego domku."},{"fr":"Trinquons à notre amitié et aux prochaines vacances !","tgt":"Wypijmy za naszą przyjaźń i następne wakacje!"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a emmenés dans les Tatras avec des amis.","tgt":"Ten moduł zabrał nas w Tatry z przyjaciółmi."},{"fr":"On sait maintenant raconter une randonnée ou des vacances en polonais.","tgt":"Teraz umiemy po polsku opowiedzieć o wędrówce albo o wakacjach."},{"fr":"Le tutoiement et le registre familier n'ont plus de secret pour nous.","tgt":"Mówienie na ty i język potoczny nie mają już dla nas tajemnic."},{"fr":"On dit « peut-être » et « il paraît » sans hésiter.","tgt":"Bez wahania mówimy już „może” i „podobno”."},{"fr":"Le vocatif nous permet d'interpeller nos amis par leur prénom.","tgt":"Dzięki wołaczowi możemy zwracać się do przyjaciół po imieniu."},{"fr":"Nos conversations sonnent déjà beaucoup plus naturelles.","tgt":"Nasze rozmowy brzmią już dużo bardziej naturalnie."},{"fr":"Le deuxième niveau est maintenant derrière nous, bravo !","tgt":"Drugi poziom jest już za nami, brawo!"},{"fr":"Le niveau trois nous réserve un polonais encore plus riche.","tgt":"Na trzecim poziomie czeka nas jeszcze bogatsza polszczyzna."},{"fr":"Reposons-nous un peu avant la suite.","tgt":"Odpocznijmy trochę przed dalszą nauką."},{"fr":"À bientôt pour de nouvelles aventures en polonais !","tgt":"Do zobaczenia przy kolejnych przygodach z polskim!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Pologne, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un entretien d'embauche","phrases":[{"fr":"Je voudrais me présenter brièvement.","tgt":"Chciałbym się krótko przedstawić."},{"fr":"Pourriez-vous me dire en quoi consiste le travail à ce poste ?","tgt":"Czy mógłby mi pan powiedzieć, na czym polega praca na tym stanowisku?"},{"fr":"J'aimerais beaucoup travailler dans une équipe internationale.","tgt":"Bardzo chciałbym pracować w międzynarodowym zespole."},{"fr":"Je pourrais commencer dès le mois prochain.","tgt":"Mógłbym zacząć już od przyszłego miesiąca."},{"fr":"Y aurait-il une possibilité de travail partiellement à distance ?","tgt":"Czy byłaby możliwość częściowej pracy zdalnej?"},{"fr":"À votre place, je poserais exactement la même question.","tgt":"Na pana miejscu zadałbym dokładnie to samo pytanie."},{"fr":"J'ai travaillé pendant cinq ans dans une entreprise de logistique à Łódź.","tgt":"Przez pięć lat pracowałem w firmie logistycznej w Łodzi."},{"fr":"Quel salaire pourrais-je espérer pour ce poste ?","tgt":"Jakiego wynagrodzenia mógłbym się spodziewać na tym stanowisku?"},{"fr":"Je rejoindrais votre entreprise avec grand plaisir.","tgt":"Bardzo chętnie dołączyłbym do państwa firmy."},{"fr":"Merci, j'attendrai votre réponse avec impatience.","tgt":"Dziękuję, będę z niecierpliwością czekał na odpowiedź."}],"tip":{"title":"Le conditionnel : « chciałbym », « mógłbym »","example":"Je voudrais me présenter brièvement. — <b>Chciałbym</b> się krótko przedstawić.","body":"Pour parler poliment en polonais, on utilise le conditionnel, et il se fabrique très simplement. On prend le verbe au passé, par exemple « chciał », il voulait, et on colle derrière la petite particule « bym », qui veut dire à la fois « je » et « -rais ». Cela donne « chciałbym », je voudrais, et de la même façon « mógłbym », je pourrais, ou « zadałbym », je poserais. Une femme dira « chciałabym » et « mogłabym ». Pour vouvoyer, on dit « mógłby pan », pourriez-vous monsieur, ou « mogłaby pani », pourriez-vous madame. Astuce : retenez simplement « bym » comme le petit son magique de la politesse.","lit":"je-voudrais · [se] · brièvement · présenter"}},{"title":"Le premier jour au bureau","phrases":[{"fr":"Bonjour, je suis le nouveau responsable des ventes.","tgt":"Dzień dobry, jestem nowym kierownikiem sprzedaży."},{"fr":"Ce matin, on m'a montré mon poste de travail.","tgt":"Rano pokazano mi moje stanowisko pracy."},{"fr":"Notre bureau se trouve dans une ancienne fabrique en briques rouges.","tgt":"Nasze biuro mieści się w dawnej fabryce z czerwonej cegły."},{"fr":"Les collègues m'ont accueilli très chaleureusement.","tgt":"Koledzy przyjęli mnie bardzo serdecznie."},{"fr":"Je dois encore récupérer mon badge d'accès.","tgt":"Muszę jeszcze odebrać swoją kartę dostępu."},{"fr":"Qui est responsable ici des questions informatiques ?","tgt":"Kto tu odpowiada za sprawy informatyczne?"},{"fr":"La cuisine commune est au bout du couloir.","tgt":"Wspólna kuchnia jest na końcu korytarza."},{"fr":"Ma cheffe m'a présenté les projets en cours.","tgt":"Moja szefowa przedstawiła mi bieżące projekty."},{"fr":"À midi, nous sommes tous allés déjeuner ensemble.","tgt":"W południe poszliśmy wszyscy razem na obiad."},{"fr":"Cette première journée s'est mieux passée que prévu.","tgt":"Ten pierwszy dzień poszedł lepiej, niż się spodziewałem."}]},{"title":"Une usine devenue lieu de vie","phrases":[{"fr":"Ce bâtiment a été construit au dix-neuvième siècle.","tgt":"Ten budynek został zbudowany w dziewiętnastym wieku."},{"fr":"L'ancienne filature a été transformée en centre culturel.","tgt":"Dawna przędzalnia została przekształcona w centrum kultury."},{"fr":"Les murs de briques ont été soigneusement rénovés.","tgt":"Ceglane mury zostały starannie odnowione."},{"fr":"La cour est ouverte aux visiteurs tous les jours.","tgt":"Dziedziniec jest codziennie otwarty dla zwiedzających."},{"fr":"Le musée de l'usine est fermé le lundi.","tgt":"Muzeum fabryki jest zamknięte w poniedziałki."},{"fr":"Cette haute cheminée a été conservée comme symbole de la ville.","tgt":"Ten wysoki komin został zachowany jako symbol miasta."},{"fr":"Les anciens entrepôts ont été transformés en lofts.","tgt":"Dawne magazyny zostały przerobione na lofty."},{"fr":"Ce quartier a été entièrement réaménagé en vingt ans.","tgt":"Ta okolica została całkowicie przebudowana w ciągu dwudziestu lat."},{"fr":"La table est déjà réservée pour ce soir.","tgt":"Stolik jest już zarezerwowany na dziś wieczór."},{"fr":"Cette visite était vraiment bien organisée.","tgt":"Ta wycieczka była naprawdę dobrze zorganizowana."}],"tip":{"title":"Le passif : « został zbudowany », « jest otwarty »","example":"Ce bâtiment a été construit au dix-neuvième siècle. — Ten budynek <b>został zbudowany</b> w dziewiętnastym wieku.","body":"Le polonais a deux façons de dire le passif, et c'est plus simple qu'il n'y paraît. Pour une action qui a eu lieu, on utilise le verbe « zostać », devenir, suivi du participe : « został zbudowany », mot à mot il devint construit, c'est-à-dire il a été construit. Pour décrire un état qui dure, on prend simplement « być », être : « jest otwarty », c'est ouvert, ou « jest zamknięte », c'est fermé. Le participe s'accorde comme un adjectif : « została odnowiona » pour une maison, « zostały odnowione » pour des murs. Astuce : avec « został », pensez à un événement ; avec « jest », pensez à une photo.","lit":"ce · bâtiment · devint · construit · en · dix-neuvième · siècle"}},{"title":"Chercher un appartement","phrases":[{"fr":"Je cherche un deux-pièces pas loin du centre.","tgt":"Szukam dwupokojowego mieszkania blisko centrum."},{"fr":"Les charges sont-elles comprises dans le loyer ?","tgt":"Czy opłaty są wliczone w czynsz?"},{"fr":"J'aimerais visiter l'appartement demain après-midi.","tgt":"Chciałbym obejrzeć mieszkanie jutro po południu."},{"fr":"Dans ces vieux immeubles, les plafonds sont très hauts.","tgt":"W tych starych kamienicach sufity są bardzo wysokie."},{"fr":"Les fenêtres de l'appartement donnent sur une cour calme.","tgt":"Okna mieszkania wychodzą na cichy dziedziniec."},{"fr":"Faut-il verser une caution à la signature ?","tgt":"Czy przy podpisywaniu umowy trzeba wpłacić kaucję?"},{"fr":"La caution correspond à deux mois de loyer.","tgt":"Kaucja to równowartość dwumiesięcznego czynszu."},{"fr":"Le chauffage est-il urbain ou au gaz ?","tgt":"Czy ogrzewanie jest miejskie, czy gazowe?"},{"fr":"Y a-t-il un arrêt de tramway à proximité ?","tgt":"Czy w pobliżu jest przystanek tramwajowy?"},{"fr":"Je vous rappellerai d'ici la fin de la semaine.","tgt":"Oddzwonię do pana do końca tygodnia."}]},{"title":"Les démarches administratives","phrases":[{"fr":"Je dois aller à la mairie pour déclarer ma nouvelle adresse.","tgt":"Muszę iść do urzędu, żeby zameldować się pod nowym adresem."},{"fr":"Que faut-il apporter pour obtenir ce document ?","tgt":"Co trzeba przynieść, żeby dostać ten dokument?"},{"fr":"Je suis venu tôt pour ne pas faire la queue.","tgt":"Przyszedłem wcześnie, żeby nie stać w kolejce."},{"fr":"Il faut d'abord prendre un numéro à la borne.","tgt":"Najpierw trzeba pobrać numerek z automatu."},{"fr":"L'employée m'a demandé de remplir ce formulaire.","tgt":"Urzędniczka poprosiła, żebym wypełnił ten formularz."},{"fr":"J'aimerais que vous vérifiiez mes documents.","tgt":"Chciałbym, żeby pani sprawdziła moje dokumenty."},{"fr":"Pour gagner du temps, on peut prendre rendez-vous en ligne.","tgt":"Żeby zaoszczędzić czas, można umówić się przez internet."},{"fr":"Il manque encore une signature sur ce formulaire.","tgt":"Na tym formularzu brakuje jeszcze podpisu."},{"fr":"Rappelez-moi de faire une copie de ce document, s'il vous plaît.","tgt":"Proszę mi przypomnieć, żebym zrobił kopię tego dokumentu."},{"fr":"Tout est en ordre, je peux enfin respirer.","tgt":"Wszystko jest w porządku, wreszcie mogę odetchnąć."}],"tip":{"title":"« Żeby » : pour que, afin de","example":"Je suis venu tôt pour ne pas faire la queue. — Przyszedłem wcześnie, <b>żeby</b> nie stać w kolejce.","body":"Le petit mot « żeby » sert à exprimer un but, comme « pour » ou « afin de » en français. Quand le sujet ne change pas, on le fait suivre de l'infinitif : « żeby nie stać w kolejce », mot à mot pour ne pas être debout dans la queue. Quand on demande quelque chose à quelqu'un, on colle la terminaison de la personne sur « żeby » et on met le verbe au passé : « żebym zrobił », que je fasse, ou « żeby pani sprawdziła », que vous vérifiiez, madame. C'est l'équivalent polonais de notre subjonctif, mais avec une forme du passé. Astuce : dès que vous pensez « pour » ou « pour que », lancez « żeby » et le reste suit.","lit":"je-suis-venu · tôt · pour-que · [ne… pas] · être-debout · dans · queue"}},{"title":"Déjeuner au bar à lait","phrases":[{"fr":"À midi, le bar à lait du coin est toujours plein de monde.","tgt":"W południe bar mleczny na rogu jest zawsze pełen ludzi."},{"fr":"Je mangerais volontiers une soupe aux cornichons.","tgt":"Chętnie zjadłbym zupę ogórkową."},{"fr":"Ici, on commande et on paie directement au comptoir.","tgt":"Tu zamawia się i płaci od razu przy ladzie."},{"fr":"Les pierogi aux pommes de terre et au fromage blanc sont la spécialité de la maison.","tgt":"Pierogi z ziemniakami i twarogiem to specjalność tego lokalu."},{"fr":"Un repas complet coûte à peine vingt złotys.","tgt":"Pełny obiad kosztuje zaledwie dwadzieścia złotych."},{"fr":"Je prendrai aussi une boisson aux fruits, s'il vous plaît.","tgt":"Poproszę jeszcze kompot."},{"fr":"Les plats changent tous les jours selon le menu au tableau.","tgt":"Codziennie są inne dania, według menu na tablicy."},{"fr":"Les bars à lait existent en Pologne depuis des décennies.","tgt":"Bary mleczne istnieją w Polsce od dziesięcioleci."},{"fr":"On y croise aussi bien des étudiants que des retraités.","tgt":"Spotyka się tu zarówno studentów, jak i emerytów."},{"fr":"Ce déjeuner tout simple me rappelle la cuisine de ma grand-mère.","tgt":"Ten prosty obiad przypomina mi kuchnię babci."}]},{"title":"Une réunion d'équipe","phrases":[{"fr":"La réunion commence à dix heures précises.","tgt":"Spotkanie zaczyna się punktualnie o dziesiątej."},{"fr":"Commençons par ce que chacun a fait cette semaine.","tgt":"Zacznijmy od tego, co każdy z nas zrobił w tym tygodniu."},{"fr":"Je voudrais présenter les résultats du dernier trimestre.","tgt":"Chciałbym przedstawić wyniki z ostatniego kwartału."},{"fr":"Nos ventes ont progressé de dix pour cent.","tgt":"Nasza sprzedaż wzrosła o dziesięć procent."},{"fr":"Avez-vous des questions sur ce point ?","tgt":"Czy mają państwo pytania do tego punktu?"},{"fr":"Je ne suis pas tout à fait d'accord avec cette proposition.","tgt":"Nie do końca zgadzam się z tą propozycją."},{"fr":"Pourrions-nous reporter cette décision à la semaine prochaine ?","tgt":"Czy moglibyśmy przełożyć tę decyzję na przyszły tydzień?"},{"fr":"Qui va rédiger le compte rendu de la réunion ?","tgt":"Kto przygotuje notatkę ze spotkania?"},{"fr":"Nous avons dépassé le temps prévu d'un quart d'heure.","tgt":"Przekroczyliśmy zaplanowany czas o kwadrans."},{"fr":"Merci à tous, on se revoit jeudi.","tgt":"Dziękuję wszystkim, widzimy się w czwartek."}]},{"title":"Flâner rue Piotrkowska","phrases":[{"fr":"La rue Piotrkowska est l'une des plus longues rues commerçantes du pays.","tgt":"Ulica Piotrkowska jest jedną z najdłuższych ulic handlowych w Polsce."},{"fr":"Le soir, la rue est pleine de promeneurs.","tgt":"Wieczorem ulica jest pełna spacerujących ludzi."},{"fr":"J'ai demandé mon chemin à un passant qui parlait français.","tgt":"Zapytałem o drogę przechodnia mówiącego po francusku."},{"fr":"Un musicien qui joue du violon attire les passants.","tgt":"Grający na skrzypcach muzyk przyciąga przechodniów."},{"fr":"En été, les cafés qui proposent des terrasses sont pleins.","tgt":"Latem kawiarnie oferujące ogródki są pełne gości."},{"fr":"J'ai un ami qui travaille dans une agence de publicité.","tgt":"Mam znajomego pracującego w agencji reklamowej."},{"fr":"Les étudiants qui habitent en centre-ville viennent souvent ici le soir.","tgt":"Studenci mieszkający w centrum często przychodzą tu wieczorem."},{"fr":"Regardez ces façades, elles ont été superbement restaurées.","tgt":"Proszę spojrzeć na te fasady, zostały pięknie odnowione."},{"fr":"Le dimanche, on voit ici des familles se promener avec des poussettes.","tgt":"W niedzielę widać tu rodziny spacerujące z wózkami."},{"fr":"C'est vraiment le cœur battant de la ville.","tgt":"To naprawdę bijące serce miasta."}],"tip":{"title":"Les participes actifs : « pracujący », « mówiący »","example":"J'ai demandé mon chemin à un passant qui parlait français. — Zapytałem o drogę przechodnia <b>mówiącego</b> po francusku.","body":"Pour dire « qui travaille » ou « qui parle », le polonais aime remplacer toute la proposition par un seul mot, le participe actif. On le fabrique à partir de la forme « ils » du présent : « pracują », ils travaillent, devient « pracujący », travaillant, et « mówią », ils parlent, devient « mówiący », parlant. Il suffit donc d'ajouter le son « tsy » à la fin, puis d'accorder comme un adjectif : « mówiącego », « spacerujące ». Dans notre exemple, mot à mot on dit j'ai demandé le chemin à un passant parlant en français. Astuce : pensez à nos mots en « -ant », et vous aurez le bon réflexe.","lit":"j'ai-demandé · sur · chemin · passant · parlant · en · français"}},{"title":"Signer le bail","phrases":[{"fr":"Le propriétaire m'a envoyé le contrat de location.","tgt":"Właściciel przysłał mi umowę najmu."},{"fr":"Je voudrais lire chaque clause attentivement.","tgt":"Chciałbym uważnie przeczytać każdy punkt."},{"fr":"Nous signons le bail pour une durée d'un an.","tgt":"Umowę zawieramy na okres jednego roku."},{"fr":"Qui paie les réparations en cas de panne ?","tgt":"Kto płaci za naprawy w razie awarii?"},{"fr":"A-t-on le droit d'avoir un animal dans l'immeuble ?","tgt":"Czy w budynku można trzymać zwierzęta?"},{"fr":"À la remise des clés, nous ferons ensemble l'état des lieux.","tgt":"Przy przekazaniu kluczy razem sporządzimy protokół."},{"fr":"Il y a une petite rayure sur le parquet.","tgt":"Na parkiecie jest mała rysa."},{"fr":"Notez-la dans l'état des lieux, s'il vous plaît.","tgt":"Proszę to zapisać w protokole."},{"fr":"Relevons ensemble les compteurs d'eau et d'électricité.","tgt":"Spiszmy razem stan liczników wody i prądu."},{"fr":"Voici les clés, l'appartement est à votre disposition.","tgt":"Oto klucze, mieszkanie jest do pana dyspozycji."}]},{"title":"Le jour du déménagement","phrases":[{"fr":"Nous déménageons samedi prochain.","tgt":"Przeprowadzamy się w przyszłą sobotę."},{"fr":"J'ai loué une camionnette pour toute la journée.","tgt":"Wynająłem busa na cały dzień."},{"fr":"Deux collègues ont promis de m'aider à porter les meubles.","tgt":"Dwaj koledzy obiecali, że pomogą mi przenosić meble."},{"fr":"Il n'y a pas d'ascenseur, et nous habitons au troisième étage.","tgt":"Nie ma windy, a mieszkamy na trzecim piętrze."},{"fr":"Les cartons de livres sont terriblement lourds.","tgt":"Pudła z książkami są strasznie ciężkie."},{"fr":"Attention, il y a de la vaisselle dans ce carton.","tgt":"Ostrożnie, w tym pudle są naczynia."},{"fr":"Nous avons d'abord monté le lit, puis mangé un morceau.","tgt":"Najpierw złożyliśmy łóżko, a potem coś zjedliśmy."},{"fr":"Pour les remercier, je les ai invités à dîner.","tgt":"Żeby im podziękować, zaprosiłem ich na kolację."},{"fr":"Il me faudra plusieurs jours pour tout déballer.","tgt":"Rozpakowanie wszystkiego zajmie mi kilka dni."},{"fr":"Je me sens déjà chez moi dans ce nouveau quartier.","tgt":"W nowej dzielnicy już czuję się jak u siebie."}]},{"title":"Ouvrir un compte en banque","phrases":[{"fr":"Je voudrais ouvrir un compte personnel.","tgt":"Chciałbym założyć konto osobiste."},{"fr":"Quels documents dois-je présenter ?","tgt":"Jakie dokumenty muszę przedstawić?"},{"fr":"Mon employeur a besoin de mon numéro de compte.","tgt":"Mój pracodawca potrzebuje numeru mojego konta."},{"fr":"La tenue de compte est-elle gratuite ?","tgt":"Czy prowadzenie konta jest bezpłatne?"},{"fr":"La carte sera envoyée par courrier sous une semaine.","tgt":"Karta zostanie wysłana pocztą w ciągu tygodnia."},{"fr":"Je peux aussi tout gérer depuis une application.","tgt":"Mogę też wszystko załatwiać w aplikacji."},{"fr":"Les virements entre banques polonaises sont très rapides.","tgt":"Przelewy między polskimi bankami są bardzo szybkie."},{"fr":"J'ai oublié le code de ma carte, que dois-je faire ?","tgt":"Zapomniałem PIN-u do karty, co mam zrobić?"},{"fr":"Le conseiller m'a tout expliqué avec patience.","tgt":"Doradca cierpliwie wszystko mi wyjaśnił."},{"fr":"En une demi-heure, tout était réglé.","tgt":"W pół godziny wszystko było załatwione."}]},{"title":"Écrire un courriel professionnel","phrases":[{"fr":"Suite à notre conversation, je vous envoie le rapport.","tgt":"W związku z naszą rozmową przesyłam raport."},{"fr":"Je vous prie de bien vouloir confirmer la date de la réunion.","tgt":"Uprzejmie proszę o potwierdzenie terminu spotkania."},{"fr":"Je vous prie d'excuser le retard de ma réponse.","tgt":"Bardzo przepraszam za opóźnienie w odpowiedzi."},{"fr":"En raison des travaux, le bureau sera fermé vendredi.","tgt":"W związku z remontem biuro będzie w piątek nieczynne."},{"fr":"Veuillez trouver ci-joint le contrat signé.","tgt":"W załączniku przesyłam podpisaną umowę."},{"fr":"Je vous prie de me répondre d'ici jeudi.","tgt":"Uprzejmie proszę o odpowiedź do czwartku."},{"fr":"Concernant votre demande, nous avons besoin d'informations complémentaires.","tgt":"W związku z pańskim zapytaniem potrzebujemy dodatkowych informacji."},{"fr":"Je reste à votre disposition pour toute question.","tgt":"Pozostaję do dyspozycji w razie pytań."},{"fr":"Je vous remercie d'avance pour votre aide.","tgt":"Z góry dziękuję za pomoc."},{"fr":"Bien cordialement.","tgt":"Łączę pozdrowienia."}],"tip":{"title":"Le langage du bureau : « uprzejmie proszę », « w związku z »","example":"Je vous prie de bien vouloir confirmer la date de la réunion. — <b>Uprzejmie proszę</b> o potwierdzenie terminu spotkania.","body":"Au bureau, les Polonais utilisent quelques formules toutes faites qui sonnent tout de suite professionnelles. « Uprzejmie proszę », mot à mot je prie aimablement, correspond à notre « je vous prie de bien vouloir » ; on le fait suivre de « o » et d'un nom : « uprzejmie proszę o odpowiedź », je vous prie de répondre. « W związku z », mot à mot en lien avec, veut dire suite à, en raison de, ou concernant : « w związku z remontem », en raison des travaux. Ces formules s'entendent aussi à l'oral, au téléphone ou en réunion. Astuce : apprenez-les comme des blocs entiers, sans les découper.","lit":"aimablement · je-prie · sur · confirmation · date · réunion"}},{"title":"Une consultation chez le médecin","phrases":[{"fr":"Je voudrais prendre rendez-vous chez un médecin généraliste.","tgt":"Chciałbym umówić się na wizytę do lekarza rodzinnego."},{"fr":"Depuis trois jours, j'ai mal à la gorge.","tgt":"Od trzech dni boli mnie gardło."},{"fr":"Le médecin m'a prescrit un sirop et conseillé du repos.","tgt":"Lekarz przepisał mi syrop i zalecił odpoczynek."},{"fr":"Ai-je besoin d'un arrêt de travail ?","tgt":"Czy potrzebuję zwolnienia lekarskiego?"},{"fr":"L'arrêt de travail arrive électroniquement chez l'employeur.","tgt":"Zwolnienie trafia elektronicznie prosto do pracodawcy."},{"fr":"Où se trouve la pharmacie la plus proche ?","tgt":"Gdzie jest najbliższa apteka?"},{"fr":"Faut-il prendre ce médicament pendant les repas ?","tgt":"Czy ten lek trzeba brać podczas posiłku?"},{"fr":"Aujourd'hui, je me sens déjà un peu mieux.","tgt":"Dzisiaj czuję się już trochę lepiej."},{"fr":"La cotisation santé est prélevée sur mon salaire.","tgt":"Składka zdrowotna jest potrącana z mojej pensji."},{"fr":"Après un peu de repos, tout ira bien.","tgt":"Po krótkim odpoczynku wszystko będzie dobrze."}]},{"title":"Se déplacer à Łódź","phrases":[{"fr":"Depuis la nouvelle gare souterraine, on rejoint Varsovie en un peu plus d'une heure.","tgt":"Z nowego podziemnego dworca do Warszawy jedzie się trochę ponad godzinę."},{"fr":"Je prends le tramway pour aller au travail.","tgt":"Do pracy jeżdżę tramwajem."},{"fr":"Un abonnement mensuel revient beaucoup moins cher.","tgt":"Bilet miesięczny wychodzi dużo taniej."},{"fr":"On peut acheter son billet directement dans le tramway.","tgt":"Bilet można kupić bezpośrednio w tramwaju."},{"fr":"N'oubliez pas de valider votre billet.","tgt":"Proszę pamiętać o skasowaniu biletu."},{"fr":"Le soir, je rentre souvent à vélo.","tgt":"Wieczorami często wracam rowerem."},{"fr":"On se déplace facilement à pied dans le centre.","tgt":"Po centrum łatwo poruszać się pieszo."},{"fr":"Aux heures de pointe, les rues sont souvent embouteillées.","tgt":"W godzinach szczytu ulice są często zakorkowane."},{"fr":"Le contrôleur m'a demandé mon titre de transport.","tgt":"Kontroler poprosił mnie o bilet."},{"fr":"Heureusement, j'avais bien validé mon billet.","tgt":"Na szczęście miałem skasowany bilet."}]},{"title":"Le télétravail","phrases":[{"fr":"Je travaille de chez moi deux jours par semaine.","tgt":"Dwa dni w tygodniu pracuję z domu."},{"fr":"Je me suis aménagé un coin de travail dans la chambre.","tgt":"Urządziłem sobie kącik do pracy w sypialni."},{"fr":"La connexion est parfois trop lente pour les visioconférences.","tgt":"Internet jest czasem za wolny na wideokonferencje."},{"fr":"Pourriez-vous couper votre micro, s'il vous plaît ?","tgt":"Czy mógłby pan wyłączyć mikrofon?"},{"fr":"Je ne vous entends pas très bien.","tgt":"Słabo pana słyszę."},{"fr":"Je partage mon écran pour vous montrer le tableau.","tgt":"Udostępniam ekran, żeby pokazać państwu tabelę."},{"fr":"À la maison, il est difficile de séparer le travail de la vie privée.","tgt":"W domu trudno oddzielić pracę od życia prywatnego."},{"fr":"À midi, je fais une vraie pause pour marcher un peu.","tgt":"W południe robię sobie prawdziwą przerwę na spacer."},{"fr":"Le lundi, toute l'équipe se retrouve au bureau.","tgt":"W poniedziałki cały zespół spotyka się w biurze."},{"fr":"Ce mode de travail mixte me convient très bien.","tgt":"Taki mieszany tryb pracy bardzo mi odpowiada."}]},{"title":"La vie dans l'immeuble","phrases":[{"fr":"Ma voisine du dessus arrose toujours mes plantes quand je pars.","tgt":"Sąsiadka z góry zawsze podlewa moje kwiaty, kiedy wyjeżdżam."},{"fr":"Pourriez-vous baisser un peu la musique, s'il vous plaît ?","tgt":"Czy mógłby pan trochę ściszyć muzykę?"},{"fr":"Jeudi soir, il y a une réunion des copropriétaires.","tgt":"W czwartek wieczorem jest zebranie wspólnoty mieszkaniowej."},{"fr":"Il a été décidé de repeindre la cage d'escalier.","tgt":"Postanowiono odmalować klatkę schodową."},{"fr":"Le voisin d'en face m'a prêté sa perceuse.","tgt":"Sąsiad z naprzeciwka pożyczył mi wiertarkę."},{"fr":"Dans la cour, les enfants jouent jusqu'au soir.","tgt":"Na podwórku dzieci bawią się do wieczora."},{"fr":"Il faut trier les déchets dans des bacs de couleurs différentes.","tgt":"Śmieci trzeba segregować do pojemników w różnych kolorach."},{"fr":"Une voisine âgée m'a apporté une part de gâteau.","tgt":"Starsza sąsiadka przyniosła mi kawałek ciasta."},{"fr":"Je l'aide parfois à monter ses courses.","tgt":"Czasem pomagam jej wnieść zakupy na górę."},{"fr":"De bons voisins, ça vaut de l'or.","tgt":"Dobrzy sąsiedzi są na wagę złota."}]},{"title":"Un week-end à Łódź","phrases":[{"fr":"Le week-end, je vais souvent courir dans la forêt de Łagiewniki.","tgt":"W weekendy często biegam w Lesie Łagiewnickim."},{"fr":"Cette grande forêt se trouve à l'intérieur même de la ville.","tgt":"Ten duży las leży w granicach miasta."},{"fr":"Dimanche, nous avons pique-niqué dans un parc près du centre.","tgt":"W niedzielę urządziliśmy piknik w parku niedaleko centrum."},{"fr":"Chaque automne, la ville organise un festival de lumières.","tgt":"Co jesień miasto organizuje festiwal świateł."},{"fr":"Les façades sont illuminées par des projections colorées.","tgt":"Fasady budynków są podświetlane kolorowymi projekcjami."},{"fr":"Le soir, nous sommes allés à un concert dans une ancienne usine.","tgt":"Wieczorem poszliśmy na koncert w dawnej fabryce."},{"fr":"S'il fait beau, nous irons à vélo jusqu'au plan d'eau.","tgt":"Jeśli pogoda pozwoli, pojedziemy rowerami nad zalew."},{"fr":"Il y a aussi un musée du cinéma très intéressant.","tgt":"Jest tu też bardzo ciekawe muzeum kinematografii."},{"fr":"La célèbre école de cinéma se trouve ici.","tgt":"Tutaj mieści się słynna szkoła filmowa."},{"fr":"Ce week-end m'a fait découvrir une autre facette de la ville.","tgt":"Ten weekend pokazał mi inne oblicze miasta."}]},{"title":"Les courses au marché couvert","phrases":[{"fr":"Le samedi matin, je fais mes courses au marché couvert.","tgt":"W sobotę rano robię zakupy na hali targowej."},{"fr":"Ces fraises viennent-elles de la région ?","tgt":"Czy te truskawki są z okolicy?"},{"fr":"Je voudrais un kilo de pommes de terre nouvelles.","tgt":"Poproszę kilogram młodych ziemniaków."},{"fr":"Pourrais-je avoir un sac en papier ?","tgt":"Czy mógłbym prosić o papierową torbę?"},{"fr":"Ce fromage fumé de montagne est délicieux.","tgt":"Ten oscypek jest pyszny."},{"fr":"Le vendeur m'a fait goûter plusieurs sortes de cornichons.","tgt":"Sprzedawca dał mi spróbować kilku rodzajów ogórków kiszonych."},{"fr":"Puis-je payer par carte ou seulement en espèces ?","tgt":"Mogę zapłacić kartą czy tylko gotówką?"},{"fr":"Ça fait trente-cinq złotys en tout.","tgt":"Razem trzydzieści pięć złotych."},{"fr":"Gardez la monnaie, c'est pour vous.","tgt":"Reszty nie trzeba."},{"fr":"Les produits du marché ont vraiment plus de goût.","tgt":"Produkty z targu naprawdę mają lepszy smak."}]},{"title":"Une proposition de promotion","phrases":[{"fr":"Ma cheffe m'a convoqué pour l'entretien annuel.","tgt":"Szefowa zaprosiła mnie na coroczną rozmowę oceniającą."},{"fr":"Elle a souligné la qualité de mon travail.","tgt":"Podkreśliła jakość mojej pracy."},{"fr":"On me propose de diriger une petite équipe.","tgt":"Proponują mi kierowanie małym zespołem."},{"fr":"Ce serait un vrai défi pour moi.","tgt":"To byłoby dla mnie prawdziwe wyzwanie."},{"fr":"J'aurais besoin d'une formation en management.","tgt":"Potrzebowałbym szkolenia z zarządzania."},{"fr":"L'entreprise financerait une partie de la formation.","tgt":"Firma sfinansowałaby część szkolenia."},{"fr":"À partir de janvier, j'aurais une augmentation.","tgt":"Od stycznia dostałbym podwyżkę."},{"fr":"J'ai demandé quelques jours pour réfléchir.","tgt":"Poprosiłem o kilka dni do namysłu."},{"fr":"Finalement, j'ai accepté cette proposition avec joie.","tgt":"W końcu z radością przyjąłem tę propozycję."},{"fr":"Ce soir, nous fêtons cela au restaurant.","tgt":"Dziś wieczorem świętujemy to w restauracji."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a fait découvrir la vie quotidienne à Łódź.","tgt":"Ten moduł pozwolił nam poznać codzienne życie w Łodzi."},{"fr":"Nous avons passé un entretien, signé un bail et rempli des formulaires.","tgt":"Przeszliśmy rozmowę kwalifikacyjną, podpisaliśmy umowę najmu i wypełniliśmy formularze."},{"fr":"Le conditionnel permet de parler avec beaucoup de politesse.","tgt":"Tryb przypuszczający pozwala mówić bardzo uprzejmie."},{"fr":"Le passif sert à décrire ce qui a été fait.","tgt":"Strona bierna pomaga opisać, co zostało zrobione."},{"fr":"Avec « żeby », on exprime facilement un but.","tgt":"Dzięki „żeby” łatwo wyrazić cel."},{"fr":"Le langage du bureau n'a plus de secret pour nous.","tgt":"Język biurowy nie ma już dla nas tajemnic."},{"fr":"Parler polonais nous vient chaque jour un peu plus facilement.","tgt":"Mówienie po polsku z każdym dniem przychodzi nam łatwiej."},{"fr":"Le prochain module nous emmènera en voyage à travers la Pologne.","tgt":"Następny moduł zabierze nas w podróż po Polsce."},{"fr":"Prenons d'abord le temps de réviser ces phrases.","tgt":"Najpierw poświęćmy chwilę na powtórkę tych zdań."},{"fr":"Bravo, et à bientôt !","tgt":"Brawo i do zobaczenia wkrótce!"}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Giżycko","phrases":[{"fr":"On est arrivés à Giżycko en fin d'après-midi, juste avant le coucher du soleil.","tgt":"Dotarliśmy do Giżycka późnym popołudniem, tuż przed zachodem słońca."},{"fr":"Le port était plein de voiliers aux voiles blanches.","tgt":"Port był pełen żaglówek z białymi żaglami."},{"fr":"Depuis le quai, on voit déjà le lac s'étendre jusqu'à l'horizon.","tgt":"Z nabrzeża widać już jezioro ciągnące się aż po horyzont."},{"fr":"La Mazurie compte, paraît-il, plus de deux mille lacs.","tgt":"Mazury mają podobno ponad dwa tysiące jezior."},{"fr":"Nous avons réservé une chambre dans une petite pension près du port.","tgt":"Zarezerwowaliśmy pokój w małym pensjonacie niedaleko portu."},{"fr":"La propriétaire nous a accueillis avec un thé et une part de gâteau.","tgt":"Właścicielka przywitała nas herbatą i kawałkiem ciasta."},{"fr":"Le soir, on a flâné le long du canal qui traverse la ville.","tgt":"Wieczorem spacerowaliśmy wzdłuż kanału, który przecina miasto."},{"fr":"L'air sentait l'eau, les pins et la fumée des grillades.","tgt":"Powietrze pachniało wodą, sosnami i dymem z grilla."},{"fr":"Demain matin, nous irons chercher notre bateau.","tgt":"Jutro rano pójdziemy odebrać naszą łódź."},{"fr":"J'ai l'impression que ces vacances vont être exceptionnelles.","tgt":"Mam wrażenie, że te wakacje będą wyjątkowe."}]},{"title":"Louer un voilier","phrases":[{"fr":"Nous cherchons un voilier qui puisse accueillir quatre personnes.","tgt":"Szukamy żaglówki, która pomieści cztery osoby."},{"fr":"Le bateau que nous avons réservé a l'air presque neuf.","tgt":"Łódź, którą zarezerwowaliśmy, wygląda na prawie nową."},{"fr":"Le loueur nous a montré le contrat qu'il fallait signer.","tgt":"Właściciel wypożyczalni pokazał nam umowę, którą trzeba było podpisać."},{"fr":"Le maître de port, qui travaille ici depuis trente ans, connaît chaque lac par cœur.","tgt":"Bosman, który pracuje tu od trzydziestu lat, zna każde jezioro na pamięć."},{"fr":"Avez-vous un permis qui vous autorise à barrer seul ?","tgt":"Czy ma pan uprawnienia, które pozwalają samodzielnie prowadzić jacht?"},{"fr":"La caution, que nous récupérerons au retour, s'élève à mille złotys.","tgt":"Kaucja, którą odzyskamy po powrocie, wynosi tysiąc złotych."},{"fr":"Il faut porter en permanence les gilets de sauvetage qui sont rangés dans la cabine.","tgt":"Kamizelki ratunkowe, które leżą w kabinie, trzeba mieć na sobie przez cały czas."},{"fr":"Montrez-moi la carte sur laquelle les ports sont indiqués, s'il vous plaît.","tgt":"Proszę mi pokazać mapę, na której zaznaczone są porty."},{"fr":"Le moteur, dont nous aurons besoin dans les canaux, démarre sans problème.","tgt":"Silnik, którego będziemy potrzebować na kanałach, zapala bez problemu."},{"fr":"C'est exactement le bateau dont je rêvais.","tgt":"To jest dokładnie ta łódź, o której marzyłem."}],"tip":{"title":"Les relatives avec « który », « która », « które »","example":"Le bateau que nous avons réservé a l'air presque neuf. — Łódź, <b>którą</b> zarezerwowaliśmy, wygląda na prawie nową.","body":"Pour dire « qui » ou « que », le polonais utilise un seul mot, « który », qui se comporte comme un adjectif. Il prend le genre du nom qu'il reprend : « który » pour le masculin, « która » pour le féminin, « które » pour le neutre et la plupart des pluriels. Il change aussi de forme selon son rôle dans la phrase : dans « łódź, którą zarezerwowaliśmy », mot à mot bateau, que nous-avons-réservé, « którą » est complément, donc il se termine par le son « on ». Avec une préposition, on dit par exemple « o której », dont ou à laquelle : « łódź, o której marzyłem », le bateau dont je rêvais. À l'oral, marquez une petite pause juste avant « który », là où l'on mettrait une virgule. Astuce : demandez-vous d'abord masculin ou féminin, puis sujet ou complément, et la bonne forme vient toute seule.","lit":"bateau · que [acc.] · nous-avons-réservé · semble · sur · presque · neuve"}},{"title":"Premières leçons de navigation","phrases":[{"fr":"Un moniteur est monté à bord pour notre première heure de navigation.","tgt":"Na pierwszą godzinę żeglugi wszedł z nami na pokład instruktor."},{"fr":"Il nous a d'abord expliqué comment hisser la grand-voile.","tgt":"Najpierw wyjaśnił nam, jak postawić grot."},{"fr":"Tenez la barre fermement, mais sans vous crisper.","tgt":"Proszę trzymać ster mocno, ale bez napięcia."},{"fr":"Quand le vent tourne, il faut réagir immédiatement.","tgt":"Kiedy wiatr się zmienia, trzeba od razu zareagować."},{"fr":"Je ne m'attendais pas à ce que le bateau penche autant.","tgt":"Nie spodziewałem się, że łódź będzie się tak mocno przechylać."},{"fr":"Attention à la bôme quand on change de cap !","tgt":"Uwaga na bom przy zmianie kursu!"},{"fr":"Au bout d'une heure, je commençais à comprendre les gestes de base.","tgt":"Po godzinie zaczynałem rozumieć podstawowe ruchy."},{"fr":"Le moniteur m'a félicité pour mon premier virement de bord réussi.","tgt":"Instruktor pochwalił mnie za mój pierwszy udany zwrot."},{"fr":"Vous apprenez vite, vous pourrez bientôt naviguer sans moi.","tgt":"Szybko się pan uczy, niedługo będzie pan mógł pływać beze mnie."},{"fr":"On a passé tout l'après-midi à s'entraîner dans la baie.","tgt":"Całe popołudnie ćwiczyliśmy w zatoce."}]},{"title":"D'un lac à l'autre","phrases":[{"fr":"Ici, on navigue d'un lac à l'autre par des canaux étroits.","tgt":"Tutaj pływa się z jeziora na jezioro wąskimi kanałami."},{"fr":"Le matin, on se lève tôt pour profiter du vent.","tgt":"Rano wstaje się wcześnie, żeby złapać wiatr."},{"fr":"Le lac se rétrécit, puis s'ouvre soudain sur une immense étendue d'eau.","tgt":"Jezioro się zwęża, a potem nagle otwiera się na ogromną taflę wody."},{"fr":"Comment s'appelle ce lac, sur la gauche ?","tgt":"Jak się nazywa to jezioro po lewej stronie?"},{"fr":"Sur l'eau, on oublie complètement le temps qui passe.","tgt":"Na wodzie zupełnie zapomina się o upływie czasu."},{"fr":"Des enfants se baignaient près de la rive.","tgt":"Dzieci kąpały się przy brzegu."},{"fr":"Je me suis habitué très vite au rythme du bateau.","tgt":"Bardzo szybko przyzwyczaiłem się do rytmu łodzi."},{"fr":"Ici, personne ne se presse.","tgt":"Tutaj nikt się nie spieszy."},{"fr":"On dit que ce passage est le plus beau de toute la région.","tgt":"Mówi się, że ten odcinek jest najpiękniejszy w całej okolicy."},{"fr":"Nous nous sommes arrêtés pour déjeuner dans une petite crique.","tgt":"Zatrzymaliśmy się na obiad w małej zatoczce."}],"tip":{"title":"« Się » : les verbes pronominaux et le « on » impersonnel","example":"Ici, on navigue d'un lac à l'autre par des canaux étroits. — Tutaj <b>pływa się</b> z jeziora na jezioro wąskimi kanałami.","body":"Le petit mot « się », prononcé « chè », correspond à notre « me, te, se », mais il ne change jamais : « myję się », je me lave, « myjesz się », tu te laves. Il aime se placer tôt dans la phrase, souvent juste après le premier mot, sans être forcément collé au verbe : « jak się nazywa ? », comment ça s'appelle ? Beaucoup de verbes pronominaux le sont aussi en français, comme « kąpać się », se baigner, ou « zatrzymać się », s'arrêter. Mais « się » sert aussi à traduire notre « on » général : on prend le verbe à la troisième personne et on ajoute « się ». Ainsi « pływa się », mot à mot navigue se, veut dire on navigue, et « mówi się » veut dire on dit. Astuce : chaque fois que vous pensez « en général, on fait ceci », dites le verbe suivi de « się ».","lit":"ici · navigue · [se] (on) · de · lac · sur · lac · étroits · canaux"}},{"title":"Passer l'écluse de Guzianka","phrases":[{"fr":"Avant d'entrer dans l'écluse, nous avons abaissé les voiles.","tgt":"Przed wejściem do śluzy zrzuciliśmy żagle."},{"fr":"On a avancé au moteur, très lentement, derrière deux autres bateaux.","tgt":"Płynęliśmy na silniku, bardzo powoli, za dwiema innymi łodziami."},{"fr":"L'éclusier nous a fait signe d'attendre notre tour.","tgt":"Śluzowy dał nam znak, żebyśmy poczekali na swoją kolej."},{"fr":"Il faut bien tenir les cordages pendant que l'eau monte.","tgt":"Trzeba mocno trzymać liny, kiedy woda się podnosi."},{"fr":"En quelques minutes, le niveau de l'eau a changé de presque deux mètres.","tgt":"W ciągu kilku minut poziom wody zmienił się prawie o dwa metry."},{"fr":"Des promeneurs nous regardaient manœuvrer depuis la rive.","tgt":"Spacerowicze przyglądali się z brzegu naszym manewrom."},{"fr":"J'avais un peu peur qu'on heurte le mur en béton.","tgt":"Trochę się bałem, że uderzymy w betonową ścianę."},{"fr":"L'éclusage se paie directement sur place.","tgt":"Za śluzowanie płaci się na miejscu."},{"fr":"De l'autre côté, un lac encore plus sauvage nous attendait.","tgt":"Po drugiej stronie czekało na nas jeszcze dziksze jezioro."},{"fr":"Finalement, cette manœuvre s'est révélée bien plus simple que prévu.","tgt":"Ostatecznie ten manewr okazał się dużo prostszy, niż się spodziewaliśmy."}]},{"title":"Le camping au bord de l'eau","phrases":[{"fr":"Nous avons planté la tente à quelques mètres du rivage.","tgt":"Rozbiliśmy namiot kilka metrów od brzegu."},{"fr":"Le camping est simple, mais l'emplacement est magnifique.","tgt":"Pole namiotowe jest skromne, ale miejsce jest przepiękne."},{"fr":"Excusez-moi, où peut-on prendre une douche chaude ?","tgt":"Przepraszam, gdzie można wziąć ciepły prysznic?"},{"fr":"Il faut payer la nuit à la réception avant vingt-deux heures.","tgt":"Za nocleg trzeba zapłacić w recepcji przed dwudziestą drugą."},{"fr":"Les voisins nous ont prêté une casserole pour faire cuire les pâtes.","tgt":"Sąsiedzi pożyczyli nam garnek, żebyśmy mogli ugotować makaron."},{"fr":"Le soir, les moustiques sont particulièrement nombreux près de l'eau.","tgt":"Wieczorami przy wodzie jest wyjątkowo dużo komarów."},{"fr":"Rangez bien la nourriture pour la nuit, il y a des sangliers dans le coin.","tgt":"Proszę schować jedzenie na noc, bo w okolicy są dziki."},{"fr":"On s'est endormis au doux bruit des vagues.","tgt":"Zasnęliśmy przy cichym szumie fal."},{"fr":"Au réveil, une brume légère flottait au-dessus du lac.","tgt":"Kiedy się obudziliśmy, nad jeziorem unosiła się lekka mgła."},{"fr":"Prendre son café face au lac, c'est un vrai luxe.","tgt":"Picie kawy z widokiem na jezioro to prawdziwy luksus."}]},{"title":"Une balade en forêt","phrases":[{"fr":"En marchant dans la forêt, nous avons entendu un coucou.","tgt":"Idąc przez las, usłyszeliśmy kukułkę."},{"fr":"Mon ami cueillait des myrtilles en chantant doucement.","tgt":"Mój przyjaciel zbierał jagody, cicho śpiewając."},{"fr":"Faites attention en traversant ce petit pont en bois.","tgt":"Proszę uważać, przechodząc przez ten drewniany mostek."},{"fr":"En regardant la carte, j'ai compris que nous nous étions perdus.","tgt":"Patrząc na mapę, zrozumiałem, że zabłądziliśmy."},{"fr":"La forêt de pins s'étend ici sur des kilomètres.","tgt":"Sosnowy las ciągnie się tu przez wiele kilometrów."},{"fr":"En revenant vers le lac, nous avons croisé un chevreuil.","tgt":"Wracając nad jezioro, spotkaliśmy sarnę."},{"fr":"On peut ramasser des champignons, mais seulement si on les connaît bien.","tgt":"Można zbierać grzyby, ale tylko jeśli dobrze się je zna."},{"fr":"J'ai trébuché sur une racine en levant les yeux vers la cime des arbres.","tgt":"Potknąłem się o korzeń, podnosząc wzrok na korony drzew."},{"fr":"Le silence de la forêt est vraiment impressionnant.","tgt":"Cisza w lesie robi ogromne wrażenie."},{"fr":"En sortant du bois, on a vu le lac baigné de soleil.","tgt":"Wychodząc z lasu, zobaczyliśmy jezioro skąpane w słońcu."}],"tip":{"title":"Le gérondif en « -ąc » : « jadąc », « robiąc », en faisant","example":"En marchant dans la forêt, nous avons entendu un coucou. — <b>Idąc</b> przez las, usłyszeliśmy kukułkę.","body":"Pour dire « en faisant », le polonais ajoute au verbe la terminaison « -ąc », prononcée à peu près « onts ». La recette est simple : on part de la forme « ils » du présent et on remplace la fin par « -ąc ». Ainsi « robią », ils font, donne « robiąc », en faisant ; « idą », ils vont à pied, donne « idąc », en marchant ; « jadą », ils roulent, donne « jadąc ». Cette forme ne change jamais, quel que soit le sujet. Dans « idąc przez las, usłyszeliśmy kukułkę », mot à mot en-allant à-travers forêt, nous-avons-entendu coucou, c'est nous qui marchons et nous qui entendons. C'est la règle d'or, comme en français : celui qui fait l'action en « -ąc » est aussi le sujet de la phrase principale. Astuce : pensez d'abord à la forme « ils », puis terminez par un petit « onts » bien net.","lit":"allant · à-travers · forêt · nous-avons-entendu · coucou"}},{"title":"La pluie imprévue","phrases":[{"fr":"Le ciel s'est couvert en à peine un quart d'heure.","tgt":"Niebo zachmurzyło się w ciągu zaledwie kwadransa."},{"fr":"Personne n'avait prévu un tel orage.","tgt":"Nikt nie przewidział takiej burzy."},{"fr":"Nous avons rapidement affalé les voiles et allumé le moteur.","tgt":"Szybko zrzuciliśmy żagle i włączyliśmy silnik."},{"fr":"La pluie tombait si fort qu'on ne voyait plus la rive.","tgt":"Lało tak mocno, że nie było widać brzegu."},{"fr":"Nous nous sommes abrités dans un petit port inconnu.","tgt":"Schroniliśmy się w małym, nieznanym porcie."},{"fr":"J'étais trempé jusqu'aux os.","tgt":"Przemokłem do suchej nitki."},{"fr":"Un pêcheur nous a proposé de nous réchauffer dans sa cabane.","tgt":"Pewien wędkarz zaproponował, żebyśmy ogrzali się w jego chatce."},{"fr":"Vous pourriez nous prêter une serviette, par hasard ?","tgt":"Czy mógłby nam pan przypadkiem pożyczyć ręcznik?"},{"fr":"Une heure plus tard, le soleil brillait comme si de rien n'était.","tgt":"Godzinę później świeciło słońce, jakby nic się nie stało."},{"fr":"Ici, la météo peut changer en quelques minutes.","tgt":"Pogoda tutaj potrafi zmienić się w kilka minut."}]},{"title":"Une soirée autour du feu","phrases":[{"fr":"Le soir, les équipages se retrouvent autour d'un feu de camp.","tgt":"Wieczorem załogi spotykają się przy ognisku."},{"fr":"Quelqu'un a sorti une guitare et tout le monde s'est mis à chanter.","tgt":"Ktoś wyciągnął gitarę i wszyscy zaczęli śpiewać."},{"fr":"Ces chansons de marins se chantent sur tous les lacs de Mazurie.","tgt":"Te szanty śpiewa się na wszystkich mazurskich jeziorach."},{"fr":"Je ne connaissais pas les paroles, mais j'ai fredonné la mélodie.","tgt":"Nie znałem słów, ale nuciłem melodię."},{"fr":"Nous avons fait griller des saucisses sur des bâtons.","tgt":"Piekliśmy kiełbaski na patykach."},{"fr":"Nos voisins nous ont raconté leurs plus belles traversées.","tgt":"Sąsiedzi opowiadali nam o swoich najpiękniejszych rejsach."},{"fr":"D'où venez-vous ? Vous naviguez depuis longtemps ?","tgt":"Skąd państwo przyjechali? Od dawna państwo żeglują?"},{"fr":"On a parlé jusqu'à minuit, sous un ciel plein d'étoiles.","tgt":"Rozmawialiśmy do północy pod niebem pełnym gwiazd."},{"fr":"Je n'aurais jamais cru chanter en polonais devant des inconnus.","tgt":"Nigdy bym nie pomyślał, że będę śpiewał po polsku przed nieznajomymi."},{"fr":"Ce genre de soirée crée des liens en quelques heures.","tgt":"Takie wieczory zbliżają ludzi w kilka godzin."}]},{"title":"La traversée de Śniardwy","phrases":[{"fr":"Aujourd'hui, nous traversons Śniardwy, le plus grand lac de Pologne.","tgt":"Dziś przepływamy przez Śniardwy, największe jezioro w Polsce."},{"fr":"Sur ce lac, les vagues peuvent être étonnamment hautes.","tgt":"Na tym jeziorze fale bywają zaskakująco wysokie."},{"fr":"Le vent a forci dès que nous sommes sortis en eau libre.","tgt":"Wiatr przybrał na sile, gdy tylko wypłynęliśmy na otwartą wodę."},{"fr":"Enfin, le bateau filait sur l'eau.","tgt":"Wreszcie łódź mknęła po wodzie."},{"fr":"Prenons un ris, ce sera plus prudent.","tgt":"Zrefujmy grot, tak będzie bezpieczniej."},{"fr":"On aperçoit déjà Mikołajki, de l'autre côté du lac.","tgt":"Po drugiej stronie jeziora widać już Mikołajki."},{"fr":"Le port de Mikołajki est très animé en été.","tgt":"Port w Mikołajkach latem tętni życiem."},{"fr":"Par miracle, nous avons trouvé une place libre au ponton.","tgt":"Cudem znaleźliśmy wolne miejsce przy pomoście."},{"fr":"Après une telle traversée, une bonne soupe de poisson s'impose.","tgt":"Po takiej przeprawie należy nam się dobra zupa rybna."},{"fr":"Je suis fier de nous : on s'en est sortis comme de vrais marins.","tgt":"Jestem z nas dumny: poradziliśmy sobie jak prawdziwi żeglarze."}]},{"title":"Rendre le bateau","phrases":[{"fr":"Ce matin, nous devons rendre le voilier avant midi.","tgt":"Dziś rano musimy oddać żaglówkę przed południem."},{"fr":"Nous avons lavé le pont et vidé la cabine.","tgt":"Umyliśmy pokład i opróżniliśmy kabinę."},{"fr":"Le loueur a vérifié le bateau dans les moindres détails.","tgt":"Właściciel wypożyczalni dokładnie sprawdził łódź."},{"fr":"Heureusement, il n'a trouvé aucune rayure sur la coque.","tgt":"Na szczęście nie znalazł żadnej rysy na kadłubie."},{"fr":"Il nous a rendu la caution sans faire d'histoires.","tgt":"Oddał nam kaucję bez żadnych dyskusji."},{"fr":"Ça me fait de la peine de quitter ces lacs.","tgt":"Żal mi zostawiać te jeziora."},{"fr":"Une semaine sur l'eau, c'est passé beaucoup trop vite.","tgt":"Tydzień na wodzie minął o wiele za szybko."},{"fr":"Nous reviendrons sûrement l'année prochaine, peut-être en automne.","tgt":"Na pewno wrócimy w przyszłym roku, może jesienią."},{"fr":"Pourriez-vous nous appeler un taxi pour la gare ?","tgt":"Czy mógłby pan zamówić nam taksówkę na dworzec?"},{"fr":"Prochaine étape : Toruń, au bord de la Vistule.","tgt":"Następny przystanek: Toruń nad Wisłą."}]},{"title":"En train vers Toruń","phrases":[{"fr":"Je devrais vérifier l'heure de notre correspondance.","tgt":"Powinienem sprawdzić godzinę naszej przesiadki."},{"fr":"Nous aurions dû acheter les billets en ligne hier soir.","tgt":"Powinniśmy byli kupić bilety przez internet wczoraj wieczorem."},{"fr":"Pour aller à Toruń, vous devriez changer à Olsztyn.","tgt":"Żeby dojechać do Torunia, powinien pan przesiąść się w Olsztynie."},{"fr":"Le train devrait arriver dans dix minutes.","tgt":"Pociąg powinien przyjechać za dziesięć minut."},{"fr":"Je ne devrais pas laisser mon sac sans surveillance.","tgt":"Nie powinienem zostawiać plecaka bez opieki."},{"fr":"Excusez-moi, cette place devrait être libre, non ?","tgt":"Przepraszam, to miejsce powinno być wolne, prawda?"},{"fr":"On devrait profiter du trajet pour se reposer un peu.","tgt":"Powinniśmy wykorzystać podróż, żeby trochę odpocząć."},{"fr":"D'après le contrôleur, nous devrions arriver avec un léger retard.","tgt":"Według konduktora powinniśmy dojechać z niewielkim opóźnieniem."},{"fr":"Je devrais peut-être appeler l'hôtel pour prévenir de notre retard.","tgt":"Może powinienem zadzwonić do hotelu i uprzedzić, że się spóźnimy."},{"fr":"Par la fenêtre, les lacs laissent place aux champs.","tgt":"Za oknem jeziora ustępują miejsca polom."}],"tip":{"title":"« Powinienem » : je devrais","example":"Je devrais vérifier l'heure de notre correspondance. — <b>Powinienem</b> sprawdzić godzinę naszej przesiadki.","body":"« Powinienem » veut dire je devrais, en un seul mot, et il est suivi d'un verbe à l'infinitif : « powinienem sprawdzić », mot à mot je-devrais vérifier. Une femme dira « powinnam », et pour nous, on dit « powinniśmy ». Pour vouvoyer, on utilise « powinien pan » ou « powinna pani », vous devriez, monsieur ou madame. Le même mot sert aussi à exprimer une probabilité : « pociąg powinien przyjechać », le train devrait arriver. Pour un regret, on ajoute « był » : « powinienem był », j'aurais dû. Prononcez « po-vi-nié-nem », avec l'accent sur l'avant-dernière syllabe, comme toujours en polonais. Astuce : la négation se met simplement devant, « nie powinienem », je ne devrais pas.","lit":"je-devrais · vérifier · heure · notre [gén.] · correspondance [gén.]"}},{"title":"Arrivée à Toruń","phrases":[{"fr":"La vieille ville de Toruń est presque entièrement en brique rouge.","tgt":"Toruńska starówka jest prawie w całości z czerwonej cegły."},{"fr":"Notre hôtel se trouve dans une ruelle tout près de la place du marché.","tgt":"Nasz hotel znajduje się w wąskiej uliczce tuż przy rynku."},{"fr":"Les maisons gothiques sont étonnamment bien conservées.","tgt":"Gotyckie kamienice są zaskakująco dobrze zachowane."},{"fr":"Sur la place, un musicien jouait du violon pour les passants.","tgt":"Na rynku jakiś muzyk grał przechodniom na skrzypcach."},{"fr":"On a l'impression de remonter plusieurs siècles en arrière.","tgt":"Ma się wrażenie, że cofnęło się w czasie o kilka stuleci."},{"fr":"L'hôtel de ville domine toute la place du marché.","tgt":"Ratusz góruje nad całym rynkiem."},{"fr":"On peut monter dans la tour pour admirer la vue.","tgt":"Można wejść na wieżę i podziwiać widok."},{"fr":"Il y a beaucoup d'étudiants, alors la ville est très vivante le soir.","tgt":"Jest tu mnóstwo studentów, więc wieczorami w mieście jest bardzo gwarno."},{"fr":"Pourriez-vous nous conseiller un endroit pour dîner dans le quartier ?","tgt":"Czy mógłby nam pan polecić jakieś miejsce na kolację w okolicy?"},{"fr":"Après une semaine en pleine nature, la ville nous semble presque bruyante.","tgt":"Po tygodniu na łonie natury miasto wydaje nam się wręcz hałaśliwe."}]},{"title":"Les remparts sur la Vistule","phrases":[{"fr":"Les anciens remparts longent encore la Vistule.","tgt":"Dawne mury obronne wciąż ciągną się wzdłuż Wisły."},{"fr":"Nous nous sommes promenés sur le boulevard qui longe le fleuve.","tgt":"Spacerowaliśmy bulwarem nad rzeką."},{"fr":"Cette tour penchée est l'une des curiosités de la ville.","tgt":"Ta krzywa wieża to jedna z ciekawostek miasta."},{"fr":"Selon la légende, celui qui tient debout contre ce mur a la conscience tranquille.","tgt":"Według legendy, kto ustoi przy tej ścianie, ma czyste sumienie."},{"fr":"Bien sûr, j'ai essayé, et je suis tombé tout de suite.","tgt":"Oczywiście spróbowałem i od razu się przewróciłem."},{"fr":"Les anciennes portes de la ville donnent directement sur le fleuve.","tgt":"Dawne bramy miejskie wychodzą prosto na rzekę."},{"fr":"Depuis l'autre rive, la vue sur la vieille ville est superbe.","tgt":"Z drugiego brzegu jest wspaniały widok na starówkę."},{"fr":"On a traversé le pont à pied au coucher du soleil.","tgt":"O zachodzie słońca przeszliśmy pieszo przez most."},{"fr":"La Vistule est bien plus large que je ne l'imaginais.","tgt":"Wisła jest dużo szersza, niż sobie wyobrażałem."},{"fr":"Ce panorama vaut à lui seul le voyage.","tgt":"Już sam ten widok jest wart podróży."}]},{"title":"L'atelier du pain d'épices","phrases":[{"fr":"Toruń est célèbre dans toute la Pologne pour son pain d'épices.","tgt":"Toruń słynie w całej Polsce z pierników."},{"fr":"Nous avons participé à un atelier où l'on fabrique soi-même son pain d'épices.","tgt":"Wzięliśmy udział w warsztatach, na których robiliśmy własne pierniki."},{"fr":"La pâte contient du miel, de la cannelle, du gingembre et des clous de girofle.","tgt":"Ciasto zawiera miód, cynamon, imbir i goździki."},{"fr":"Autrefois, la recette était gardée comme le plus grand des secrets.","tgt":"Dawniej przepisu strzeżono jak największej tajemnicy."},{"fr":"On presse la pâte dans des moules en bois sculptés à la main.","tgt":"Ciasto wciska się do ręcznie rzeźbionych drewnianych form."},{"fr":"Mon pain d'épices est un peu de travers, mais j'en suis très fier.","tgt":"Mój piernik wyszedł trochę krzywy, ale jestem z niego bardzo dumny."},{"fr":"Il faut laisser reposer la pâte, parfois pendant plusieurs semaines.","tgt":"Ciasto trzeba odstawić, czasem nawet na kilka tygodni."},{"fr":"Ça sent la cannelle dans toute la rue.","tgt":"Na całej ulicy pachnie cynamonem."},{"fr":"Je préfère les pains d'épices fourrés à la confiture de prunes.","tgt":"Najbardziej lubię pierniki nadziewane powidłami śliwkowymi."},{"fr":"Peut-on les garder longtemps, si je veux en rapporter à la maison ?","tgt":"Czy można je długo przechowywać, jeśli chcę je zabrać do domu?"}]},{"title":"Copernic et les étoiles","phrases":[{"fr":"Nicolas Copernic est né ici, dans une maison de la vieille ville.","tgt":"Mikołaj Kopernik urodził się tutaj, w jednej z kamienic na starówce."},{"fr":"Sa statue se dresse devant l'hôtel de ville.","tgt":"Jego pomnik stoi przed ratuszem."},{"fr":"Le musée raconte comment il observait le ciel.","tgt":"Muzeum opowiada o tym, jak obserwował niebo."},{"fr":"C'est lui qui a compris que la Terre tourne autour du Soleil.","tgt":"To on zrozumiał, że Ziemia krąży wokół Słońca."},{"fr":"D'ailleurs, l'université de Toruń porte son nom.","tgt":"Zresztą toruński uniwersytet nosi jego imię."},{"fr":"Le soir, nous sommes allés au planétarium.","tgt":"Wieczorem poszliśmy do planetarium."},{"fr":"Allongé dans le noir, j'avais l'impression de flotter parmi les étoiles.","tgt":"Leżąc w ciemności, miałem wrażenie, że unoszę się wśród gwiazd."},{"fr":"La séance était en polonais, mais les images parlaient d'elles-mêmes.","tgt":"Seans był po polsku, ale obrazy mówiły same za siebie."},{"fr":"J'ai compris bien plus de choses que je ne l'aurais cru.","tgt":"Zrozumiałem dużo więcej, niż się spodziewałem."},{"fr":"Ce soir, on regardera le ciel autrement.","tgt":"Dziś wieczorem będziemy patrzeć na niebo inaczej."}]},{"title":"Un dîner au bord de la Vistule","phrases":[{"fr":"Nous avons trouvé une terrasse avec vue sur le fleuve.","tgt":"Znaleźliśmy ogródek z widokiem na rzekę."},{"fr":"Une table pour quatre en terrasse, s'il vous plaît.","tgt":"Poproszę stolik dla czterech osób na zewnątrz."},{"fr":"Quelle spécialité régionale nous conseillez-vous ?","tgt":"Co poleciłby nam pan z regionalnych specjałów?"},{"fr":"Le sandre grillé est la spécialité de la maison.","tgt":"Specjalnością lokalu jest sandacz z grilla."},{"fr":"En entrée, je prendrai les pierogi aux champignons.","tgt":"Na przystawkę wezmę pierogi z grzybami."},{"fr":"Pourriez-vous nous apporter une carafe d'eau ?","tgt":"Czy może nam pan przynieść dzbanek wody?"},{"fr":"Le fleuve brillait sous les dernières lueurs du jour.","tgt":"Rzeka lśniła w ostatnich promieniach słońca."},{"fr":"C'était excellent, transmettez nos compliments au chef, s'il vous plaît.","tgt":"Było znakomite, proszę przekazać nasze gratulacje kucharzowi."},{"fr":"L'addition, s'il vous plaît. Nous payons séparément.","tgt":"Poproszę rachunek. Płacimy osobno."},{"fr":"On a terminé la soirée par une promenade sur les quais.","tgt":"Wieczór zakończyliśmy spacerem po bulwarach."}]},{"title":"On se débrouille de mieux en mieux","phrases":[{"fr":"Je comprends le polonais de mieux en mieux.","tgt":"Coraz lepiej rozumiem po polsku."},{"fr":"Les journées raccourcissent et les soirées sont de plus en plus fraîches.","tgt":"Dni są coraz krótsze, a wieczory coraz chłodniejsze."},{"fr":"Je commande au restaurant avec de plus en plus d'aisance.","tgt":"Coraz swobodniej zamawiam w restauracji."},{"fr":"Plus le voyage avance, plus j'ai envie de rester.","tgt":"Im dłużej trwa podróż, tym bardziej chcę zostać."},{"fr":"Les commerçants me répondent de plus en plus souvent en polonais.","tgt":"Sprzedawcy coraz częściej odpowiadają mi po polsku."},{"fr":"Mon sac est de plus en plus lourd, à cause du pain d'épices !","tgt":"Mój plecak jest coraz cięższy przez te pierniki!"},{"fr":"Il paraît qu'il y a de plus en plus de touristes français en Pologne.","tgt":"Podobno do Polski przyjeżdża coraz więcej turystów z Francji."},{"fr":"Mon accent s'améliore, du moins c'est ce qu'on me dit.","tgt":"Mój akcent jest coraz lepszy, a przynajmniej tak mi mówią."},{"fr":"J'ose de plus en plus souvent parler avec des inconnus.","tgt":"Coraz częściej odważam się rozmawiać z nieznajomymi."},{"fr":"Il nous reste de moins en moins de temps avant le départ.","tgt":"Zostaje nam coraz mniej czasu do wyjazdu."}],"tip":{"title":"« Coraz » : de plus en plus, « coraz lepiej »","example":"Je comprends le polonais de mieux en mieux. — <b>Coraz lepiej</b> rozumiem po polsku.","body":"Pour dire « de plus en plus », le polonais n'a besoin que d'un mot : « coraz », suivi d'un comparatif. « Lepiej » veut dire mieux, donc « coraz lepiej », de mieux en mieux ; « więcej » veut dire plus, donc « coraz więcej », de plus en plus de. Pour « de moins en moins », on garde « coraz » et on prend « mniej », moins : « coraz mniej czasu », de moins en moins de temps. Dans « coraz lepiej rozumiem po polsku », mot à mot de-plus-en-plus mieux je-comprends en-polonais, l'expression se place volontiers en tête de phrase. Ça marche aussi avec les adjectifs : « coraz cięższy », de plus en plus lourd. Prononcez « tso-rass », avec l'accent sur « tso ». Astuce : « coraz » est un ascenseur, et le mot qui le suit dit s'il monte ou s'il descend.","lit":"de-plus-en-plus · mieux · je-comprends · en-polonais"}},{"title":"Raconter son voyage","phrases":[{"fr":"Si je devais choisir un seul moment, ce serait l'orage sur le lac.","tgt":"Gdybym miał wybrać jeden moment, byłaby to burza na jeziorze."},{"fr":"Nous avons vu des paysages que je n'oublierai jamais.","tgt":"Widzieliśmy krajobrazy, których nigdy nie zapomnę."},{"fr":"La Mazurie, c'est le calme ; Toruń, c'est le charme.","tgt":"Mazury to spokój, a Toruń to urok."},{"fr":"Je conseillerais ce voyage à tous ceux qui aiment la nature.","tgt":"Polecałbym tę podróż każdemu, kto kocha przyrodę."},{"fr":"Si c'était à refaire, je resterais plus longtemps sur l'eau.","tgt":"Gdybym mógł to powtórzyć, zostałbym dłużej na wodzie."},{"fr":"Le plus drôle, c'était ma chute au pied de la tour penchée.","tgt":"Najzabawniejszy był mój upadek pod krzywą wieżą."},{"fr":"J'ai rapporté trois boîtes de pain d'épices pour la famille.","tgt":"Przywiozłem rodzinie trzy pudełka pierników."},{"fr":"Mes amis n'en revenaient pas que je parle autant polonais.","tgt":"Znajomi nie mogli uwierzyć, że tyle mówię po polsku."},{"fr":"Grâce à ce voyage, j'ai envie de découvrir d'autres régions du pays.","tgt":"Dzięki tej podróży chcę poznać inne regiony Polski."},{"fr":"Ces deux semaines me laisseront de magnifiques souvenirs.","tgt":"Z tych dwóch tygodni zostaną mi piękne wspomnienia."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a menés des lacs de Mazurie jusqu'aux rives de la Vistule.","tgt":"Ten moduł zaprowadził nas od mazurskich jezior aż nad brzegi Wisły."},{"fr":"Nous savons maintenant relier deux idées dans une seule phrase.","tgt":"Umiemy już połączyć dwie myśli w jednym zdaniu."},{"fr":"Les verbes pronominaux ne nous font plus peur.","tgt":"Czasowniki zwrotne już nas nie przerażają."},{"fr":"Grâce au gérondif, nous racontons deux actions à la fois.","tgt":"Dzięki imiesłowom opowiadamy o dwóch czynnościach naraz."},{"fr":"Nous savons aussi dire ce que nous devrions faire.","tgt":"Umiemy też powiedzieć, co powinniśmy zrobić."},{"fr":"Notre polonais devient de plus en plus naturel.","tgt":"Nasz polski jest coraz bardziej naturalny."},{"fr":"Louer un bateau, réserver un camping, commander au restaurant : plus rien ne nous arrête.","tgt":"Wynajęcie łodzi, rezerwacja pola namiotowego, zamówienie w restauracji: nic już nas nie zatrzyma."},{"fr":"Prenez un moment pour répéter les phrases qui vous ont posé problème.","tgt":"Proszę poświęcić chwilę na powtórzenie zdań, które sprawiły panu trudność."},{"fr":"Félicitations, nous avons fait un long chemin depuis le début de ce niveau.","tgt":"Gratulacje, od początku tego poziomu przeszliśmy długą drogę."},{"fr":"Rendez-vous dans le prochain module pour parler de la vie sociale.","tgt":"Do zobaczenia w następnym module, w którym porozmawiamy o życiu towarzyskim."}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un dîner animé à Lublin","phrases":[{"fr":"Leur dispute ? Pas mon cirque, pas mes singes !","tgt":"Ich kłótnia? Nie mój cyrk, nie moje małpy!"},{"fr":"Arrête de tourner autour du pot et dis-nous ce que tu penses.","tgt":"Przestań owijać w bawełnę i powiedz, co myślisz."},{"fr":"Marek est d'une humeur de chien ce soir.","tgt":"Marek ma dziś wieczorem muchy w nosie."},{"fr":"Préparer ce dîner pour huit personnes, c'était du gâteau.","tgt":"Przygotowanie tej kolacji dla ośmiu osób to była bułka z masłem."},{"fr":"Je croise les doigts pour que ton projet marche.","tgt":"Trzymam kciuki, żeby twój projekt się udał."},{"fr":"Ne fais pas une montagne de rien, c'était juste une remarque pour rire.","tgt":"Nie rób z igły wideł, to była tylko żartobliwa uwaga."},{"fr":"Il nous promet monts et merveilles depuis des années.","tgt":"Od lat obiecuje nam gruszki na wierzbie."},{"fr":"Ne me demande pas de chanter, je n'ai aucune oreille.","tgt":"Nie proś mnie, żebym śpiewał, słoń mi nadepnął na ucho."},{"fr":"Quand ils parlent de leurs voisins, je me dis : pas mon cirque, pas mes singes.","tgt":"Kiedy rozmawiają o swoich sąsiadach, myślę sobie: nie mój cyrk, nie moje małpy."},{"fr":"Ces expressions imagées rendent la conversation beaucoup plus vivante.","tgt":"Takie obrazowe wyrażenia bardzo ożywiają rozmowę."}],"tip":{"title":"Les expressions imagées : « nie mój cyrk, nie moje małpy »","example":"Leur dispute ? Pas mon cirque, pas mes singes ! — Ich kłótnia? <b>Nie mój cyrk, nie moje małpy!</b>","body":"Le polonais adore les images, tout comme le français. « Nie mój cyrk, nie moje małpy » se décompose mot à mot en « pas mon cirque, pas mes singes » : c'est la façon drôle et légère de dire « ce n'est pas mon problème ». On la prononce d'un seul élan, en appuyant sur « cyrk » et sur « małpy ». Autres images très courantes : « bułka z masłem », littéralement « petit pain au beurre », veut dire « c'est du gâteau » ; « mieć muchy w nosie », « avoir des mouches dans le nez », veut dire « être de mauvaise humeur » ; et « trzymam kciuki », « je tiens les pouces », c'est notre « je croise les doigts ». Astuce : visualisez la scène, le cirque, les singes, les mouches, et l'expression reviendra toute seule au bon moment.","lit":"leur · dispute ? · [ne… pas] · mon · cirque, · [ne… pas] · mes · singes !"}},{"title":"Débattre sans se fâcher","phrases":[{"fr":"Je ne suis pas tout à fait d'accord avec toi sur ce point.","tgt":"Nie do końca się z tobą zgadzam w tej kwestii."},{"fr":"Tu exagères un peu, tu ne trouves pas ?","tgt":"Trochę przesadzasz, nie uważasz?"},{"fr":"Je comprends ton point de vue, mais je vois les choses autrement.","tgt":"Rozumiem twój punkt widzenia, ale widzę to inaczej."},{"fr":"Laisse-moi finir ma phrase, s'il te plaît.","tgt":"Daj mi skończyć zdanie, proszę."},{"fr":"Sur ce point, je te donne entièrement raison.","tgt":"W tej kwestii przyznaję ci całkowitą rację."},{"fr":"On peut ne pas être d'accord et rester amis.","tgt":"Możemy się nie zgadzać i nadal być przyjaciółmi."},{"fr":"Et comment comptes-tu me convaincre, au juste ?","tgt":"A jak właściwie zamierzasz mnie przekonać?"},{"fr":"Je retire ce que j'ai dit, j'ai parlé sans réfléchir.","tgt":"Cofam to, co powiedziałem, odezwałem się bez zastanowienia."},{"fr":"Ce débat sur le meilleur film de l'année aurait pu durer toute la nuit.","tgt":"Ta dyskusja o najlepszym filmie roku mogłaby trwać całą noc."},{"fr":"Bon, changeons de sujet avant que le thé ne refroidisse.","tgt":"Dobra, zmieńmy temat, zanim herbata wystygnie."}]},{"title":"Les pierogi de grand-mère","phrases":[{"fr":"Bon appétit à tous, servez-vous !","tgt":"Smacznego wszystkim, częstujcie się!"},{"fr":"Ma grand-mère faisait les meilleurs pierogi de tout Lublin.","tgt":"Moja babcia robiła najlepsze pierogi w całym Lublinie."},{"fr":"Elle mettait toujours du fromage blanc et des pommes de terre dedans.","tgt":"Zawsze dawała do nich twaróg i ziemniaki."},{"fr":"Santé ! À grand-mère et à ses pierogi !","tgt":"Na zdrowie! Za babcię i jej pierogi!"},{"fr":"Tu as éternué ? À tes souhaits !","tgt":"Kichnąłeś? Na zdrowie!"},{"fr":"Elle refusait toujours de dévoiler sa recette à qui que ce soit.","tgt":"Nigdy nikomu nie chciała zdradzić swojego przepisu."},{"fr":"Ressers-toi, il en reste plein.","tgt":"Nałóż sobie jeszcze, zostało mnóstwo."},{"fr":"Allez, tiens bon, et appelle-moi si tu as besoin de quoi que ce soit.","tgt":"No to trzymaj się i dzwoń, jeśli będziesz czegoś potrzebował."},{"fr":"Merci pour le dîner, il était délicieux.","tgt":"Dzięki za kolację, była przepyszna."},{"fr":"Salut, et porte-toi bien !","tgt":"Cześć, trzymaj się!"}],"tip":{"title":"Les expressions du quotidien : « smacznego », « na zdrowie », « trzymaj się »","example":"Bon appétit à tous, servez-vous ! — <b>Smacznego</b> wszystkim, częstujcie się!","body":"« Smacznego » veut dire « bon appétit » : mot à mot, on souhaite « du savoureux » à tout le monde. On le dit avant de manger, et même à un voisin de table inconnu dans un bar à lait. « Na zdrowie », littéralement « pour la santé », sert à trinquer, mais aussi à répondre à un éternuement, exactement comme notre « à tes souhaits ». Pour boire en l'honneur de quelqu'un, on dit plutôt « za » suivi du nom, par exemple « za babcię », « à grand-mère ». Enfin « trzymaj się », littéralement « tiens-toi », est un au revoir chaleureux qui signifie « prends soin de toi » ou « tiens bon ». Astuce : trois moments, trois formules, avant le repas, au moment de trinquer, et au moment de partir.","lit":"bon-appétit · à-tous, · servez · [vous] !"}},{"title":"Les secrets de la cuisine polonaise","phrases":[{"fr":"La soupe de seigle aigre se sert souvent dans une miche de pain.","tgt":"Żurek często podaje się w bochenku chleba."},{"fr":"Sans aneth, la cuisine polonaise ne serait pas la même.","tgt":"Bez koperku polska kuchnia nie byłaby taka sama."},{"fr":"Le bigos est encore meilleur le lendemain, réchauffé.","tgt":"Bigos jest jeszcze lepszy następnego dnia, po odgrzaniu."},{"fr":"Chaque famille a sa propre recette de bigos et jure que c'est la meilleure.","tgt":"Każda rodzina ma swój własny przepis na bigos i przysięga, że jest najlepszy."},{"fr":"Les bars à lait proposent une cuisine simple et pas chère.","tgt":"Bary mleczne oferują proste i tanie jedzenie."},{"fr":"Tu as déjà goûté les cornichons marinés de ma tante ?","tgt":"Próbowałeś już kiszonych ogórków mojej cioci?"},{"fr":"En été, on mange une soupe froide à la betterave.","tgt":"Latem jemy chłodnik z buraków."},{"fr":"Pour le dessert, je te conseille le gâteau au fromage blanc.","tgt":"Na deser polecam ci sernik."},{"fr":"La cuisine polonaise est plus variée qu'on ne le croit en France.","tgt":"Polska kuchnia jest bardziej różnorodna, niż się myśli we Francji."},{"fr":"Ce soir, c'est moi qui cuisine, et vous jugerez.","tgt":"Dziś wieczorem ja gotuję, a wy ocenicie."}]},{"title":"Un livre qui m'a marqué","phrases":[{"fr":"C'est comme si ce roman avait été écrit spécialement pour moi.","tgt":"To tak, jakby ta powieść była napisana specjalnie dla mnie."},{"fr":"On dirait que la fin ne t'a pas plu.","tgt":"Wygląda na to, że nie spodobało ci się zakończenie."},{"fr":"L'auteur décrit Varsovie comme s'il y avait vécu toute sa vie.","tgt":"Autor opisuje Warszawę, jakby mieszkał tam całe życie."},{"fr":"J'ai lu les cent dernières pages d'une traite.","tgt":"Przeczytałem ostatnie sto stron jednym tchem."},{"fr":"On dirait que tout le monde lit ce livre en ce moment.","tgt":"Wygląda na to, że wszyscy czytają teraz tę książkę."},{"fr":"Elle parlait des personnages comme s'ils étaient ses amis.","tgt":"Mówiła o bohaterach, jakby byli jej przyjaciółmi."},{"fr":"Ce livre m'a fait voir mon enfance autrement.","tgt":"Ta książka sprawiła, że inaczej spojrzałem na swoje dzieciństwo."},{"fr":"Je te le prête, mais rends-le-moi avant la fin du mois.","tgt":"Pożyczę ci ją, tylko oddaj przed końcem miesiąca."},{"fr":"On dirait que tu as vu un fantôme, qu'est-ce qui se passe ?","tgt":"Wyglądasz, jakbyś zobaczył ducha, co się dzieje?"},{"fr":"Il semblerait que le film tiré du livre sorte au printemps.","tgt":"Wygląda na to, że film na podstawie tej książki wejdzie do kin wiosną."}],"tip":{"title":"« Jakby » et « wygląda na to, że » : on dirait que","example":"On dirait que tu as vu un fantôme, qu'est-ce qui se passe ? — Wyglądasz, <b>jakbyś</b> zobaczył ducha, co się dzieje?","body":"« Jakby » veut dire « comme si ». Il prend les petites terminaisons du conditionnel : « jakbym », comme si je, « jakbyś », comme si tu, « jakbyśmy », comme si nous, et le verbe qui suit se met simplement au passé. Ainsi « wyglądasz, jakbyś zobaczył ducha » se décompose en « tu as l'air, comme si tu avais vu un fantôme ». Pour un constat plus neutre, on dit « wygląda na to, że », mot à mot « ça ressemble à ce que », c'est-à-dire « on dirait que » ou « apparemment » : « wygląda na to, że pada », on dirait qu'il pleut. À l'oral, « wygląda na to » se dit très vite, presque d'un seul souffle. Astuce : « jakby », c'est le « comme si » des comparaisons et des impressions ; « wygląda na to », c'est la remarque du détective qui observe les indices.","lit":"tu-as-l'air, · comme-si-tu · avais-vu · fantôme, · quoi · se · passe ?"}},{"title":"Une soirée cinéma à Varsovie","phrases":[{"fr":"On va au cinéma ce soir ou on regarde un film à la maison ?","tgt":"Idziemy dziś do kina czy oglądamy film w domu?"},{"fr":"J'ai réservé deux places au dernier rang.","tgt":"Zarezerwowałem dwa miejsca w ostatnim rzędzie."},{"fr":"Ce réalisateur polonais a un style vraiment à part.","tgt":"Ten polski reżyser ma naprawdę wyjątkowy styl."},{"fr":"Je préfère voir les films en version originale avec des sous-titres.","tgt":"Wolę oglądać filmy w wersji oryginalnej z napisami."},{"fr":"Les acteurs jouaient de façon tellement naturelle !","tgt":"Aktorzy grali tak naturalnie!"},{"fr":"Le scénario m'a un peu déçu, surtout vers la fin.","tgt":"Scenariusz trochę mnie rozczarował, zwłaszcza pod koniec."},{"fr":"Ne me raconte pas la fin, je n'ai pas encore vu ce film !","tgt":"Nie zdradzaj mi zakończenia, jeszcze nie widziałem tego filmu!"},{"fr":"Ce film vaut la peine d'être vu sur grand écran.","tgt":"Ten film warto obejrzeć na dużym ekranie."},{"fr":"Après la séance, on a discuté du film jusqu'à minuit.","tgt":"Po seansie rozmawialiśmy o filmie do północy."},{"fr":"La prochaine fois, c'est toi qui choisis le film.","tgt":"Następnym razem ty wybierasz film."}]},{"title":"Souvenirs de Cracovie","phrases":[{"fr":"Tu te souviens de notre première soirée sur la place du marché de Cracovie ?","tgt":"Pamiętasz nasz pierwszy wieczór na krakowskim Rynku?"},{"fr":"On s'était promenés sous les arcades de la Halle aux draps.","tgt":"Spacerowaliśmy pod arkadami Sukiennic."},{"fr":"Le Wawel était magnifique au coucher du soleil.","tgt":"Wawel wyglądał przepięknie o zachodzie słońca."},{"fr":"On avait mangé des petits pains en couronne achetés à une charrette dans la rue.","tgt":"Jedliśmy obwarzanki z ulicznego wózka."},{"fr":"Dans le quartier de Kazimierz, on a trouvé un café plein de charme.","tgt":"Na Kazimierzu znaleźliśmy pełną uroku kawiarnię."},{"fr":"On s'était perdus dans les petites rues, et c'était le meilleur moment du voyage.","tgt":"Zgubiliśmy się w małych uliczkach i to był najlepszy moment wyjazdu."},{"fr":"Cracovie a une atmosphère qu'on ne trouve nulle part ailleurs.","tgt":"Kraków ma atmosferę, jakiej nie ma nigdzie indziej."},{"fr":"J'ai encore la photo de nous deux devant le dragon du Wawel.","tgt":"Wciąż mam nasze wspólne zdjęcie przed Smokiem Wawelskim."},{"fr":"Le dragon crachait du feu toutes les quelques minutes, tu te rappelles ?","tgt":"Smok co kilka minut zionął ogniem, pamiętasz?"},{"fr":"Il faudrait qu'on y retourne ensemble un de ces jours.","tgt":"Powinniśmy tam kiedyś razem wrócić."}]},{"title":"Un week-end à Gdańsk","phrases":[{"fr":"Si j'avais su qu'il ferait si froid, j'aurais pris un pull plus chaud.","tgt":"Gdybym wiedział, że będzie tak zimno, wziąłbym cieplejszy sweter."},{"fr":"Si on était partis plus tôt, on aurait vu le coucher du soleil sur la mer.","tgt":"Gdybyśmy wyjechali wcześniej, zobaczylibyśmy zachód słońca nad morzem."},{"fr":"La rue Longue était noire de monde ce samedi-là.","tgt":"W tę sobotę ulica Długa była pełna ludzi."},{"fr":"Si tu avais été avec nous, tu aurais adoré la plage de Sopot.","tgt":"Gdybyś był z nami, zachwyciłbyś się plażą w Sopocie."},{"fr":"On a acheté un petit pendentif en ambre pour ma sœur.","tgt":"Kupiliśmy mały bursztynowy wisiorek dla mojej siostry."},{"fr":"Si je n'avais pas raté le train, je serais arrivé à temps pour le dîner.","tgt":"Gdybym nie spóźnił się na pociąg, zdążyłbym na kolację."},{"fr":"Le vent de la Baltique nous a creusé l'appétit.","tgt":"Wiatr znad Bałtyku zaostrzył nam apetyt."},{"fr":"Si j'étais à ta place, je resterais un jour de plus à Gdańsk.","tgt":"Gdybym był na twoim miejscu, zostałbym w Gdańsku jeszcze jeden dzień."},{"fr":"Le port au coucher du soleil, c'est une image que je n'oublierai jamais.","tgt":"Port o zachodzie słońca to obraz, którego nigdy nie zapomnę."},{"fr":"Si on avait eu plus de temps, on serait allés jusqu'à la presqu'île de Hel.","tgt":"Gdybyśmy mieli więcej czasu, pojechalibyśmy aż na Hel."}],"tip":{"title":"« Gdyby » : l'hypothèse irréelle, si j'avais su","example":"Si j'avais su qu'il ferait si froid, j'aurais pris un pull plus chaud. — <b>Gdybym</b> wiedział, że będzie tak zimno, <b>wziąłbym</b> cieplejszy sweter.","body":"« Gdyby » introduit une hypothèse imaginaire ou qui ne s'est pas réalisée. Bonne nouvelle : à l'oral, le polonais utilise la même forme pour « si je savais » et pour « si j'avais su », c'est le contexte qui fait la différence. On colle la personne à « gdyby » : « gdybym », si je, « gdybyś », si tu, « gdybyśmy », si nous, puis le verbe au passé, comme « wiedział », su. Dans la deuxième partie de la phrase, on accroche « bym » au verbe : « wziąłbym », j'aurais pris, « zostałbym », je serais resté. Mot à mot, « gdybym wiedział » donne donc « si-je su ». Astuce : pensez à un écho, « gdybym » appelle « bym », comme deux rimes qui se répondent d'un bout à l'autre de la phrase.","lit":"si-je · su, · que · sera · si · froid, · j'aurais-pris · plus-chaud · pull"}},{"title":"Randonnée dans les Tatras","phrases":[{"fr":"On est partis de Zakopane à six heures du matin.","tgt":"Wyruszyliśmy z Zakopanego o szóstej rano."},{"fr":"La route vers le lac Morskie Oko n'en finissait pas.","tgt":"Droga do Morskiego Oka ciągnęła się w nieskończoność."},{"fr":"Arrivés au lac, on a oublié toute notre fatigue.","tgt":"Kiedy dotarliśmy nad jezioro, zapomnieliśmy o całym zmęczeniu."},{"fr":"Un épais brouillard est tombé d'un coup, on ne voyait plus rien.","tgt":"Nagle pojawiła się gęsta mgła i nic nie było widać."},{"fr":"Dans un refuge, on a bu le thé le plus chaud de ma vie.","tgt":"W schronisku wypiliśmy najgorętszą herbatę w moim życiu."},{"fr":"Les montagnards parlent un patois que j'avais du mal à comprendre.","tgt":"Górale mówią gwarą, którą trudno mi było zrozumieć."},{"fr":"On a goûté le fromage fumé grillé avec de la confiture de canneberges.","tgt":"Spróbowaliśmy grillowanego oscypka z żurawiną."},{"fr":"Après ça, j'ai eu mal aux jambes pendant trois jours.","tgt":"Potem przez trzy dni bolały mnie nogi."},{"fr":"Malgré la fatigue, c'était l'une des plus belles journées de l'année.","tgt":"Mimo zmęczenia to był jeden z najpiękniejszych dni w roku."},{"fr":"L'été prochain, je voudrais monter jusqu'au sommet du Kasprowy Wierch.","tgt":"Przyszłego lata chciałbym wejść na Kasprowy Wierch."}]},{"title":"Des souvenirs d'enfance à Lublin","phrases":[{"fr":"Raconte-moi le quartier de Lublin où tu as grandi.","tgt":"Opowiedz mi o dzielnicy Lublina, w której dorastałeś."},{"fr":"Tomek a passé toute son enfance près de la porte de Cracovie.","tgt":"Tomek spędził całe dzieciństwo niedaleko Bramy Krakowskiej."},{"fr":"Enfants, on jouait dans la cour jusqu'à la tombée de la nuit.","tgt":"Jako dzieci bawiliśmy się na podwórku aż do zmroku."},{"fr":"Ses grands-parents avaient un jardin plein de pommiers à la campagne.","tgt":"Jego dziadkowie mieli na wsi ogród pełen jabłoni."},{"fr":"Chaque été, il partait en colonie de vacances au bord d'un lac de Mazurie.","tgt":"Każdego lata jeździł na kolonie nad jezioro na Mazurach."},{"fr":"Il dit que les étés semblaient beaucoup plus longs à l'époque.","tgt":"Mówi, że wtedy lata wydawały się dużo dłuższe."},{"fr":"Mon meilleur souvenir d'enfance, c'est l'odeur de la cuisine de ma grand-mère.","tgt":"Moje najlepsze wspomnienie z dzieciństwa to zapach kuchni mojej babci."},{"fr":"Les galettes à l'oignon de Lublin ont pour lui le goût de l'enfance.","tgt":"Lubelskie cebularze smakują mu jak dzieciństwo."},{"fr":"On s'est rencontrés à l'école et on ne s'est jamais perdus de vue.","tgt":"Poznaliśmy się w szkole i nigdy nie straciliśmy ze sobą kontaktu."},{"fr":"C'est fou comme certains souvenirs restent gravés pour toujours.","tgt":"To niesamowite, jak niektóre wspomnienia zostają w pamięci na zawsze."}]},{"title":"Parler de ses projets d'avenir","phrases":[{"fr":"Qu'est-ce que tu comptes faire après tes études ?","tgt":"Co zamierzasz robić po studiach?"},{"fr":"J'aimerais ouvrir un petit café à Lublin un jour.","tgt":"Chciałbym kiedyś otworzyć małą kawiarnię w Lublinie."},{"fr":"Ania envisage de s'installer à Varsovie pour son travail.","tgt":"Ania myśli o przeprowadzce do Warszawy ze względu na pracę."},{"fr":"Je ne sais pas encore, j'hésite entre deux options.","tgt":"Jeszcze nie wiem, waham się między dwiema opcjami."},{"fr":"Dans cinq ans, j'aimerais vivre la moitié de l'année en Pologne.","tgt":"Za pięć lat chciałbym mieszkać w Polsce przez pół roku."},{"fr":"Il faut parfois oser prendre des risques.","tgt":"Czasem trzeba odważyć się zaryzykować."},{"fr":"Mes parents trouvent mon idée un peu folle.","tgt":"Moi rodzice uważają, że mój pomysł jest trochę szalony."},{"fr":"Avant de me lancer, je voudrais mettre un peu d'argent de côté.","tgt":"Zanim zacznę, chciałbym trochę zaoszczędzić."},{"fr":"Quoi qu'il arrive, je veux continuer à apprendre.","tgt":"Cokolwiek się stanie, chcę dalej się uczyć."},{"fr":"On en reparlera dans un an, autour d'un autre dîner.","tgt":"Wrócimy do tej rozmowy za rok, przy kolejnej kolacji."}]},{"title":"Les conseils des amis","phrases":[{"fr":"Aide-moi à choisir : deux têtes valent mieux qu'une.","tgt":"Pomóż mi wybrać: co dwie głowy, to nie jedna."},{"fr":"Ne te décourage pas : Cracovie ne s'est pas faite en un jour.","tgt":"Nie zniechęcaj się: nie od razu Kraków zbudowano."},{"fr":"C'est dans le besoin qu'on reconnaît ses vrais amis.","tgt":"Prawdziwych przyjaciół poznaje się w biedzie."},{"fr":"À quelque chose malheur est bon, comme dit le proverbe.","tgt":"Nie ma tego złego, co by na dobre nie wyszło, jak mówi przysłowie."},{"fr":"Ne vends pas la peau de l'ours avant de l'avoir tué.","tgt":"Nie dziel skóry na niedźwiedziu."},{"fr":"Un tiens vaut mieux que deux tu l'auras.","tgt":"Lepszy wróbel w garści niż gołąb na dachu."},{"fr":"On est bien partout, mais rien ne vaut la maison.","tgt":"Wszędzie dobrze, ale w domu najlepiej."},{"fr":"Trop de cuisiniers gâtent la sauce, alors laisse-moi faire.","tgt":"Gdzie kucharek sześć, tam nie ma co jeść, więc pozwól, że ja to zrobię."},{"fr":"L'appétit vient en mangeant, tu vois bien.","tgt":"Apetyt rośnie w miarę jedzenia, sam widzisz."},{"fr":"Ma grand-mère avait un proverbe pour chaque situation.","tgt":"Moja babcia miała przysłowie na każdą okazję."}],"tip":{"title":"Les proverbes polonais : « co dwie głowy, to nie jedna »","example":"Aide-moi à choisir : deux têtes valent mieux qu'une. — Pomóż mi wybrać: <b>co dwie głowy, to nie jedna</b>.","body":"« Co dwie głowy, to nie jedna » se traduit mot à mot par « ce que deux têtes, ce n'est pas une », autrement dit « deux têtes valent mieux qu'une ». Les Polonais glissent volontiers leurs proverbes dans la conversation, souvent avec un petit sourire complice. Pour encourager quelqu'un, on dit « nie od razu Kraków zbudowano », Cracovie n'a pas été bâtie d'un coup, là où nous parlons d'une autre ville. Pour calmer un ami trop pressé, « nie dziel skóry na niedźwiedziu », ne partage pas la peau sur l'ours encore vivant. Et pour consoler, « nie ma tego złego », à quelque chose malheur est bon. Astuce : apprenez-les comme de petites chansons, avec leur rythme, car c'est la musique qui les fait tenir dans la mémoire.","lit":"aide · moi · choisir : · ce-que · deux · têtes, · ça · [ne… pas] · une"}},{"title":"Lublin ou Varsovie ?","phrases":[{"fr":"Varsovie bouge tout le temps, alors que Lublin est plus tranquille.","tgt":"Warszawa ciągle tętni życiem, a Lublin jest spokojniejszy."},{"fr":"À Varsovie, les loyers sont devenus vraiment chers.","tgt":"W Warszawie wynajem mieszkania zrobił się naprawdę drogi."},{"fr":"Pour un deux-pièces, on paie facilement trois mille złotys par mois.","tgt":"Za dwupokojowe mieszkanie płaci się spokojnie trzy tysiące złotych miesięcznie."},{"fr":"Grâce aux étudiants, Lublin a une ambiance très vivante.","tgt":"Dzięki studentom w Lublinie panuje bardzo żywa atmosfera."},{"fr":"Ce que je préfère à Varsovie, ce sont les soirées sur les quais de la Vistule.","tgt":"W Warszawie najbardziej lubię wieczory na bulwarach nad Wisłą."},{"fr":"À Lublin, on peut aller partout à pied.","tgt":"W Lublinie wszędzie można dojść pieszo."},{"fr":"De Lublin à Varsovie, il faut à peine deux heures de train.","tgt":"Z Lublina do Warszawy jedzie się pociągiem niecałe dwie godziny."},{"fr":"Moi, je choisirais Lublin pour sa qualité de vie.","tgt":"Ja wybrałbym Lublin ze względu na jakość życia."},{"fr":"Toi, tu es un vrai citadin, tu ne pourrais pas vivre sans le bruit de la capitale.","tgt":"Ty jesteś prawdziwym mieszczuchem, nie mógłbyś żyć bez zgiełku stolicy."},{"fr":"Au fond, chaque ville a son charme.","tgt":"W gruncie rzeczy każde miasto ma swój urok."}]},{"title":"Rire de ses erreurs","phrases":[{"fr":"Hier, j'ai confondu deux mots et tout le monde a éclaté de rire.","tgt":"Wczoraj pomyliłem dwa słowa i wszyscy wybuchnęli śmiechem."},{"fr":"J'ai dit « bonne nuit » au boulanger à neuf heures du matin.","tgt":"Powiedziałem piekarzowi „dobranoc” o dziewiątej rano."},{"fr":"Ne t'en fais pas, ça arrive à tout le monde.","tgt":"Nie przejmuj się, każdemu się to zdarza."},{"fr":"Les Polonais apprécient vraiment qu'on essaie de parler leur langue.","tgt":"Polacy naprawdę doceniają, kiedy ktoś próbuje mówić w ich języku."},{"fr":"Mes amis me corrigent toujours avec beaucoup de gentillesse.","tgt":"Przyjaciele zawsze poprawiają mnie bardzo życzliwie."},{"fr":"Je n'arrive toujours pas à prononcer « szczęście » du premier coup.","tgt":"Wciąż nie potrafię wymówić słowa „szczęście” za pierwszym razem."},{"fr":"C'est en se trompant qu'on apprend le plus vite.","tgt":"Na błędach uczymy się najszybciej."},{"fr":"Une fois, j'ai commandé dix pierogi au lieu de deux.","tgt":"Raz zamówiłem dziesięć pierogów zamiast dwóch."},{"fr":"Au moins, je n'ai pas eu faim ce soir-là !","tgt":"Przynajmniej tamtego wieczoru nie byłem głodny!"},{"fr":"Celui qui sait rire de lui-même apprend plus vite.","tgt":"Kto umie śmiać się z siebie, ten szybciej się uczy."}]},{"title":"Un anniversaire surprise","phrases":[{"fr":"On organise une fête surprise pour les trente ans de Kasia.","tgt":"Organizujemy imprezę niespodziankę na trzydzieste urodziny Kasi."},{"fr":"Surtout, ne lui dis rien, elle ne se doute de rien.","tgt":"Tylko nic jej nie mów, niczego się nie domyśla."},{"fr":"Qui se charge du gâteau, et qui s'occupe de la musique ?","tgt":"Kto zajmie się tortem, a kto muzyką?"},{"fr":"On pourrait mettre cinquante złotys chacun pour le cadeau.","tgt":"Moglibyśmy się zrzucić po pięćdziesiąt złotych na prezent."},{"fr":"Quand elle est entrée, on a tous crié « surprise » !","tgt":"Kiedy weszła, wszyscy krzyknęliśmy: „Niespodzianka!”"},{"fr":"Elle était tellement émue qu'elle en a pleuré.","tgt":"Była tak wzruszona, że się rozpłakała."},{"fr":"On a chanté « Sto lat » à tue-tête.","tgt":"Śpiewaliśmy „Sto lat” na cały głos."},{"fr":"Je te souhaite tout le meilleur !","tgt":"Życzę ci wszystkiego najlepszego!"},{"fr":"La fête a duré jusqu'à trois heures du matin.","tgt":"Impreza trwała do trzeciej nad ranem."},{"fr":"Les voisins ont été très patients avec nous.","tgt":"Sąsiedzi byli dla nas bardzo wyrozumiali."}]},{"title":"Des vacances en Mazurie entre amis","phrases":[{"fr":"Et si on louait un voilier sur les lacs de Mazurie cet été ?","tgt":"Może wynajmiemy tego lata żaglówkę na Mazurach?"},{"fr":"Aucun de nous ne sait vraiment naviguer, mais c'est un détail !","tgt":"Nikt z nas tak naprawdę nie umie żeglować, ale to szczegół!"},{"fr":"On pourrait dormir sous la tente au bord de l'eau.","tgt":"Moglibyśmy spać pod namiotem nad wodą."},{"fr":"Il faudra penser à emporter de l'anti-moustique.","tgt":"Trzeba będzie pamiętać o środku na komary."},{"fr":"Le soir, on ferait un feu de camp et on chanterait.","tgt":"Wieczorami palilibyśmy ognisko i śpiewali."},{"fr":"Qui veut se charger de réserver le bateau ?","tgt":"Kto chce zarezerwować łódź?"},{"fr":"Je propose qu'on parte la deuxième semaine de juillet.","tgt":"Proponuję, żebyśmy pojechali w drugim tygodniu lipca."},{"fr":"Ça me convient parfaitement, je prendrai mes congés à ce moment-là.","tgt":"Pasuje mi idealnie, wezmę wtedy urlop."},{"fr":"S'il fait mauvais, on se repliera dans une pension.","tgt":"Jeśli będzie brzydka pogoda, przeniesiemy się do jakiegoś pensjonatu."},{"fr":"J'ai déjà hâte d'y être.","tgt":"Już nie mogę się doczekać."}]},{"title":"Complimenter et remercier","phrases":[{"fr":"Tu as très bon goût, ton appartement est superbement décoré.","tgt":"Masz świetny gust, pięknie urządziłeś to mieszkanie."},{"fr":"Je ne sais pas comment te remercier pour ton aide.","tgt":"Nie wiem, jak ci dziękować za pomoc."},{"fr":"Tu trouves vraiment que mon polonais s'est amélioré ?","tgt":"Naprawdę uważasz, że mój polski się poprawił?"},{"fr":"Tu es très gentil, mais j'ai encore beaucoup à apprendre.","tgt":"Jesteś bardzo miły, ale jeszcze dużo muszę się nauczyć."},{"fr":"Tu es magnifique dans cette robe.","tgt":"W tej sukience wyglądasz cudownie."},{"fr":"Merci de m'avoir accueilli comme un membre de la famille.","tgt":"Dziękuję, że przyjęliście mnie jak członka rodziny."},{"fr":"Sans toi, je ne me serais jamais senti chez moi ici.","tgt":"Bez ciebie nigdy nie poczułbym się tu jak w domu."},{"fr":"Il n'y a pas de quoi, ça m'a fait plaisir.","tgt":"Nie ma za co, to była dla mnie przyjemność."},{"fr":"Tu as fait un super boulot pour organiser cette soirée.","tgt":"Świetnie się spisałeś, organizując ten wieczór."},{"fr":"J'apprécie vraiment ta franchise.","tgt":"Naprawdę cenię twoją szczerość."}]},{"title":"Au revoir sur le quai de la gare","phrases":[{"fr":"Je n'aime pas les adieux, alors faisons ça vite.","tgt":"Nie lubię pożegnań, więc zróbmy to szybko."},{"fr":"Ces deux semaines sont passées beaucoup trop vite.","tgt":"Te dwa tygodnie minęły o wiele za szybko."},{"fr":"Salue toute ta famille de ma part.","tgt":"Pozdrów ode mnie całą rodzinę."},{"fr":"Tu vas me manquer, toi et nos longues discussions.","tgt":"Będę tęsknić za tobą i za naszymi długimi rozmowami."},{"fr":"Tu es toujours le bienvenu à Lublin, tu le sais.","tgt":"Zawsze jesteś mile widziany w Lublinie, wiesz o tym."},{"fr":"La prochaine fois, c'est toi qui viens me voir en France.","tgt":"Następnym razem to ty przyjedziesz do mnie do Francji."},{"fr":"Promets-moi qu'on ne laissera pas passer un an avant de se revoir.","tgt":"Obiecaj mi, że nie minie rok, zanim znowu się zobaczymy."},{"fr":"Allez, monte, le train va partir.","tgt":"No, wsiadaj, pociąg zaraz odjedzie."},{"fr":"Bon voyage, et préviens-moi quand tu seras arrivé !","tgt":"Szczęśliwej podróży i daj znać, jak dojedziesz!"},{"fr":"Je suis resté sur le quai jusqu'à ce que le train disparaisse.","tgt":"Stałem na peronie, dopóki pociąg nie zniknął."}]},{"title":"Regard en arrière sur le parcours en polonais","phrases":[{"fr":"Quand j'ai commencé le polonais, je ne savais même pas dire bonjour.","tgt":"Kiedy zaczynałem uczyć się polskiego, nie umiałem nawet powiedzieć „dzień dobry”."},{"fr":"Les sons « sz », « cz » et « szcz » me faisaient peur au début.","tgt":"Na początku bałem się dźwięków „sz”, „cz” i „szcz”."},{"fr":"Aujourd'hui, je peux discuter pendant des heures avec mes amis polonais.","tgt":"Dziś mogę godzinami rozmawiać z polskimi przyjaciółmi."},{"fr":"Les cas de grammaire ne me font plus aussi peur qu'avant.","tgt":"Przypadki nie przerażają mnie już tak jak kiedyś."},{"fr":"J'ai appris en écoutant, en répétant et en me trompant souvent.","tgt":"Uczyłem się, słuchając, powtarzając i często się myląc."},{"fr":"Chaque trajet pour aller au travail s'est transformé en petite leçon de polonais.","tgt":"Każdy dojazd do pracy zamienił się w krótką lekcję polskiego."},{"fr":"Je rêve parfois en polonais, et ça me surprend toujours.","tgt":"Czasem śnię po polsku i wciąż mnie to zaskakuje."},{"fr":"Cette langue m'a ouvert les portes de tout un pays.","tgt":"Ten język otworzył mi drzwi do całego kraju."},{"fr":"Je suis fier du chemin parcouru depuis la toute première leçon.","tgt":"Jestem dumny z drogi, którą przeszedłem od pierwszej lekcji."},{"fr":"Il me reste encore beaucoup à découvrir, et c'est tant mieux.","tgt":"Wciąż mam wiele do odkrycia i bardzo dobrze."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Dans ce dernier module, nous nous sommes mis à table avec des amis polonais.","tgt":"W tym ostatnim module zasiedliśmy do stołu z polskimi przyjaciółmi."},{"fr":"Nous avons appris à débattre, à plaisanter et à partager nos souvenirs.","tgt":"Nauczyliśmy się dyskutować, żartować i dzielić się wspomnieniami."},{"fr":"Les expressions imagées et les proverbes donnent au polonais une vraie saveur.","tgt":"Obrazowe wyrażenia i przysłowia nadają polszczyźnie prawdziwy smak."},{"fr":"Grâce à « gdyby » et « jakby », on sait maintenant s'exprimer avec plus de finesse.","tgt":"Dzięki słówkom „gdyby” i „jakby” umiemy teraz wyrażać się subtelniej."},{"fr":"Trois niveaux, neuf modules, et des centaines de phrases prononcées à voix haute.","tgt":"Trzy poziomy, dziewięć modułów i setki zdań wypowiedzianych na głos."},{"fr":"Le polonais n'est plus pour nous une langue impossible à maîtriser.","tgt":"Polski przestał być dla nas językiem nie do opanowania."},{"fr":"Continue à parler, à écouter, et n'aie pas peur des fautes.","tgt":"Mów dalej, słuchaj i nie bój się błędów."},{"fr":"Maintenant, le mieux sera d'aller en Pologne et de parler avec les gens.","tgt":"Teraz najlepiej będzie pojechać do Polski i rozmawiać z ludźmi."},{"fr":"Félicitations, tu as parcouru ce long chemin jusqu'au bout !","tgt":"Gratulacje, przeszedłeś tę długą drogę do samego końca!"},{"fr":"Porte-toi bien, et à bientôt en Pologne !","tgt":"Trzymaj się i do zobaczenia w Polsce!"}]}]}]}];
